window.DATA_ST={"chapters":[{"n":1,"level":"初级","title":"盲派体系总览","qs":[{"q":"按盲派的体用划分，下列哪一组全部属于「体」？","opts":["日主、禄、比劫、财","日主、禄、比劫、印","日主、印、食神、官杀","禄、比劫、印、官"],"ans":1,"exp":"体是日主、禄、比劫、印（我自己和我使用的工具）；用是财、官杀（我追求的目标）；食伤可体可用。","sec":"四、体与用","t":"rule"},{"q":"食神和伤官，在体用里各偏向哪边？","opts":["食神、伤官都只属体","食神、伤官都只属用","食神偏体，伤官偏用","食神偏用，伤官偏体"],"ans":2,"exp":"食伤属精神体验，可体可用，其中食神偏体，伤官偏用，要看命局需要。","sec":"四、体与用","t":"diff"},{"q":"大运流年出现命局中已有的同一个字，算宾吗？","opts":["算宾，是外来的别人之物","不算宾，但只主凶不主吉","算宾，但力量比原局更强","不算宾，是原局的字到了，多表示应期"],"ans":3,"exp":"大运流年是外来的，但出现命局中已有的同一个字时，不再算宾，而是命局中的字到了，一般表示原局的应期。","sec":"三、宾与主","t":"rule"},{"q":"年月上的财官，在什么情况下能成为自己的？","opts":["被主位所制，或被制后又被主位所得","只要透出天干就是自己的","年月上的财官一律是别人的","日主旺时就是自己的"],"ans":0,"exp":"年月为宾，但其财官若通过一定关系被主位所制，或被它制后又被主位所得，就能成为自己的；与旺衰无关。","sec":"三、宾与主","t":"calc"},{"q":"命中有财官，一定能得财当官吗？","opts":["不一定，要日主旺才可","不一定，体必须与用发生刑冲合害破墓关系","一定能，财官透干即得","一定能，只要日主旺"],"ans":1,"exp":"体必须与用发生刑、冲、合、害、破、墓等关系，财官才可能被日主得到；盲派不论日主旺衰。","sec":"四、体与用","t":"calc"},{"q":"正向做功与反向做功的区别是什么？","opts":["正向用刑冲克，反向用穿合墓","正向是宾位制主位；反向是主位制宾位","正向是主位体制宾位用；反向是主位用追宾位体","正向是主位用追宾位体；反向是主位体制宾位用"],"ans":2,"exp":"正向做功：主位的体去作用、追求或制去宾位的用；反向做功：主位的用去追求宾位的体，层次一般高于正向。","sec":"五、做功、功神、废神","t":"diff"},{"q":"贼捕结构的判定，关键看什么？","opts":["捕与贼势均力敌，互相制约","贼较旺捕较弱，捕被反制","贼被制但没制死也算","捕较旺贼较弱，贼被制死制净"],"ans":3,"exp":"贼捕要求捕旺贼弱、贼被制死制干净；某字被制但没制死，也做功，但不叫贼捕，分析方法不同。","sec":"七、贼神与捕神","t":"diff"},{"q":"贼捕的应期：局中捕旺而无贼，与运、流年一直只见捕不见贼，分别如何？","opts":["大运见贼为吉；运岁都只见捕不见贼应凶","大运见贼与只见捕不见贼，都应凶","大运见贼为凶；运岁都只见捕不见贼应吉","大运见贼为吉；运岁只见捕不见贼也为吉"],"ans":0,"exp":"局中捕旺喜大运贼神出现（运中捕旺喜流年贼神）；局中有捕无贼、运中见捕不见贼、局运流年都只见捕不见贼应凶。","sec":"七、贼神与捕神","t":"step"},{"q":"同样是「不好」，要判断是生病、破财还是官司，主要靠哪一法？","opts":["理法","象法","宾主法","能量效率法"],"ans":1,"exp":"理法只能断吉凶，断不到具体事件；象法把吉凶具体化、形象化，所以病、破财、官司要靠象。","sec":"二、论命三法：理法、象法、技法","t":"diff"},{"q":"八字中天干与地支的能量相比如何？","opts":["天干能量高，地支能量低","天干地支能量相同","天干能量低，地支能量高","按日主旺衰而定，没有固定"],"ans":2,"exp":"八字中每个字都有能量，天干能量低、地支能量高；功神耗散能量后产生了效率。","sec":"六、能量与效率","t":"rule"}]},{"n":2,"level":"初级","title":"宫位取象与吉凶","qs":[{"q":"看六亲，宫位与六亲的亲缘由近至远，正确排序是哪个？","opts":["日支、月干、月支、时干、时支、年上","时干、时支、日支、月干、月支、年上","日支、时干、时支、月干、月支、年上","日支、时支、时干、月支、月干、年上"],"ans":2,"exp":"亲缘由近至远：日支——时干——时支——月干——月支——年上。","sec":"二、八类宫位取象","t":"step"},{"q":"断买房与买车，分别看哪个宫位？","opts":["房看时柱，车看日支","房看月柱，车看日支","房看日支，车看年柱","房看日支，车看时柱"],"ans":3,"exp":"日支是日主的根，代表家、房子；时为门户，代步工具看时柱。","sec":"二、八类宫位取象","t":"diff"},{"q":"身体取象中，年柱、日支、时柱各主什么部位？","opts":["年柱腿足，日支五脏六腑，时柱头面手眼","年柱腿足，日支头面手眼，时柱五脏六腑","年柱头面，日支五脏六腑，时柱腿足","年柱躯干，日支腿足，时柱五脏六腑"],"ans":0,"exp":"年柱离日干最远主腿足四肢，日支最重要主胸部五脏，时柱主露在外面的器官。","sec":"二、八类宫位取象","t":"xiang"},{"q":"日柱与年月柱受伤，对寿命的影响有何不同？","opts":["日柱年月坏都不影响寿命","日柱坏损寿，年月坏不碍寿","年月坏损寿，日柱坏无碍","日柱年月坏都同样损寿"],"ans":1,"exp":"口诀：日主坐根连体则不能坏；日柱代表五脏六腑，年月代表腿足躯干。","sec":"二、八类宫位取象","t":"rule"},{"q":"天干与地支在宫位取象中，分别代表什么？","opts":["天干为内心，地支为表象","天干为祖上，地支为后代","天干为表象，地支为内心","天干为动象，地支为静象"],"ans":2,"exp":"天干在外，代表性格表象；地支在内，代表内心世界和隐蔽的思想。","sec":"二、八类宫位取象","t":"diff"},{"q":"功神所在，出远门与在家哪个更好？","opts":["无论功神在哪，出远门都吉","功神在日支宜出远门，在年时宜在家","功神在月柱宜出远门，在日支宜在家","功神在日支宜在家，在年时宜出去"],"ans":3,"exp":"用的东西在日支，最好不要出去；在年、时两头，肯定出去好。","sec":"三、地域宫位的应用","t":"rule"},{"q":"月柱与日支相冲、相合，分别主什么？","opts":["冲主背井离乡，合主离不开祖籍","冲主配偶同乡，合主远嫁异地","冲合都主离开祖籍，只是迟早不同","冲主离不开祖籍，合主背井离乡"],"ans":0,"exp":"月日支一冲，必背井离乡；一合，自然离不开；配偶宫合到月令，多是同乡、同学、同事。","sec":"三、地域宫位的应用","t":"diff"},{"q":"日支（配偶宫）与年柱相合，配偶的特点如何论？","opts":["年长但在本地；合到时则远方","年大年长且远方；合到时则年小","年小且在本地；合到时则年大","年大年长；合到月则最小"],"ans":1,"exp":"年为大，时为小；配偶宫合到年则年龄大，且年代表远方。","sec":"四、宫位的年岁（大小）","t":"calc"},{"q":"盲派用生成之数断数目，水、木各主几？","opts":["水主一，木主八","水主六，木主八","水主六，木主三","水主三，木主六"],"ans":2,"exp":"生成之数：木上财主三，如3000万；水主六，如60岁、六千里。","sec":"四、宫位的年岁（大小）","t":"calc"},{"q":"年柱为功神，被哪一柱冲克才为忌？","opts":["被时柱冲克为忌，月日不为忌","被月日时三柱冲克都为忌","被日柱冲克为忌，月时不为忌","被月柱冲克为忌，日时不为忌"],"ans":3,"exp":"年柱功神被月柱冲克为忌，日时较远，冲克无力，一般不为忌。","sec":"五、宫位的吉凶","t":"rule"},{"q":"吉神所在柱被他柱忌神冲克，什么情形下此忌不为忌？","opts":["该忌神又被别的字制住","该忌神在年柱最远处","该忌神被大运冲合","该忌神与日主同柱"],"ans":0,"exp":"例外：忌神若又被别的字制住，则此忌不为忌，要细心辨识。","sec":"五、宫位的吉凶","t":"rule"}]},{"n":3,"level":"初级","title":"十神类象与虚透","qs":[{"q":"按盲派，官杀虚透于天干（即使被制得很好），主什么？","opts":["主当官有权","主有文凭学历","主钱财丰厚","只主名气，不主有官"],"ans":3,"exp":"纯粹虚透的官杀被制是无用的，只表名声名气；真正当官要官杀实而被制净。","sec":"七、十神虚透","t":"rule"},{"q":"官杀被制，按盲派口径，「制净」与「制不净」分别主什么？","opts":["制净当官，制不净当有文化","制净有文化，制不净当官","制净主名气，制不净主官非","制净得权力，制不净主小人"],"ans":0,"exp":"口诀：官杀制净为当官，有化或制不净当文化看；制不净的官杀还可当财看。","sec":"看官杀的规则","t":"diff"},{"q":"官杀由实变虚、然后被制，一般怎么论？","opts":["一定有牢狱","容易有官","只主名气不主官","官杀被废当忌论"],"ans":1,"exp":"例外情形：年月官杀特别重到时上变轻而被制，或日时重到年月变轻而被制，实转虚再被制容易有官。","sec":"看官杀的规则","t":"rule"},{"q":"内食神格的成格条件是什么？","opts":["地支食神被天干官杀所制","天干地支都透食神","地支有食神，天干不透食神","天干透食神，地支无食神"],"ans":2,"exp":"天干为外、地支为内；内食神成格者多为企业家。个别天干透出者，地支食神必须旺相。","sec":"内食神格","t":"rule"},{"q":"天干透食神与内食神（地支食神不透）的职业倾向区别是？","opts":["透干主辛劳职业，内食神主公职","透干多做企业，内食神多做教师","两者都主企业，只是大小不同","透干靠技艺受人尊重，内食神多做企业"],"ans":3,"exp":"透干为「外吃人」，有一技之长；内食神为「被人吃」，养活他人，成格多为企业家。","sec":"内食神格","t":"diff"},{"q":"甲、丙、戊、庚、壬五个阳干，按盲派，羊刃依次落在哪个地支？","opts":["卯、午、未、酉、子","卯、午、辰、酉、子","寅、午、未、申、亥","卯、午、午、酉、子"],"ans":0,"exp":"盲派羊刃：甲在卯、丙在午、戊在未、庚在酉、壬在子，与传统略有差别（戊刃在未）。","sec":"羊刃","t":"calc"},{"q":"日主乙木，地支见卯，按盲派该论什么？","opts":["比肩禄，不论劫财","劫财，不论羊刃","食神","羊刃"],"ans":1,"exp":"阳干有刃、阴干无刃，阴干遇刃当劫财看。","sec":"羊刃","t":"calc"},{"q":"盲派用羊刃，什么情况下算吉？","opts":["羊刃遇财星为吉","羊刃遇印生为吉","羊刃合杀为吉，其余都不吉","羊刃被冲为吉"],"ans":2,"exp":"羊刃太旺太弱都不好，不能被刑冲合，唯独羊刃合杀例外；羊刃喜制服。","sec":"羊刃","t":"rule"},{"q":"某八字时柱为「甲申」，月柱为「丙寅」，时干甲（财）按盲派论虚还是透？","opts":["要看年柱有无根才定","月支寅是甲根，不论虚透","日主不论虚透，故甲不虚","仍论虚透，只论本柱"],"ans":3,"exp":"虚透只论本柱，一柱之干即使在他支见根，该干在此柱仍论虚透。","sec":"定义（只论天干，只论一柱）","t":"calc"},{"q":"下列哪一项不在虚透的判断范围内？","opts":["日主与比劫天干","年干","月干","时干"],"ans":0,"exp":"只论年、月、时三柱天干；地支都是实的，日主与比劫不论虚透。","sec":"定义（只论天干，只论一柱）","t":"rule"},{"q":"印星虚透，局中「用印」与「忌印」的学历判断有何不同？","opts":["两者都没文凭，忌印更差","用印虚透没文凭，忌印虚透有文凭","用印虚透有文凭，忌印虚透没文凭","两者都有文凭，只是高低不同"],"ans":1,"exp":"局中用印而虚透：没文化文凭；局中忌印而虚透，或虽忌被制去，反而有文化文凭。","sec":"各十神虚透的含义","t":"diff"},{"q":"十神虚透用于应期，原局「实而为用」时，大运怕见什么？","opts":["怕大运见合","怕大运见冲","怕大运见虚","怕大运见实"],"ans":2,"exp":"实而为用怕大运中虚，虚而为用怕大运见实；但大运之实若被原局制化则不怕。","sec":"虚透用于应期","t":"rule"}]},{"n":4,"level":"初级","title":"入手方法与命局层次","qs":[{"q":"从日柱入手看做功，日干的三步顺序是什么？","opts":["先看有无合，再看有无生，最后看有无势","先看有无生，再看有无合，最后看有无势","先看有无合，再看有无刑冲，最后看有无势","先看有无势，再看有无合，最后看有无生"],"ans":0,"exp":"日干先看合（只合正官或正财），无合看生（食伤贴近日干），无生无合再看势。","sec":"日柱入手的顺序","t":"step"},{"q":"日干无合、无生，又不在势中，该怎么入手？","opts":["弃日柱，专看月柱","弃日干，专看日支","改看时柱，时柱为子女宫","仍看日干，按日干旺衰定"],"ans":1,"exp":"支是干的躯体，地支所做的功就是天干的，日干无功就看日支。","sec":"日柱入手的顺序","t":"rule"},{"q":"日柱干支都做功，但日干意向与日支意向不一致，以谁为主？","opts":["以日支为主，地支能量大","日柱各占一半，两边并看","弃地支之功，以日干意向为主","弃日干，以日支意向为主"],"ans":2,"exp":"日柱干支意向一致才以日柱论；不一致则弃地支之功，以日干意向为主。","sec":"谁为主","t":"calc"},{"q":"日干有合，但地支做了大功，该以谁的功为主？","opts":["以月令之功为主，日柱都不算","以日干之合为主，合官即是官命","合与地支功各占一半","以日支的功为主，日干之合只是表象"],"ans":3,"exp":"有的八字日干有合或生，但地支做了大功，这时以日支的功为主，干上的合生只是表象。","sec":"日柱入手的顺序","t":"calc"},{"q":"盲派判断富贵八字的两个条件是什么？","opts":["有势，并且做功","日主旺相，并且有官有印","有势，并且日主在势中","五行平衡，并且无冲克"],"ans":0,"exp":"口诀是一是有势、二要做功：只有势不做功不行，做了功没有势功又太小。","sec":"（一）富贵八字：两个条件","t":"rule"},{"q":"以下哪组是盲派成一党的组合？","opts":["木火、金水、水木、火与燥土、金与燥土、水与湿土","木火、金水、水木、火与燥土、金与湿土、水与湿土","木火、金水、木土、火与湿土、金与燥土、水与湿土","木火、金水、水木、火与湿土、金与燥土、水与燥土"],"ans":1,"exp":"火配燥土，金、水配湿土；燥土与金、水，湿土与火不成党，别把燥湿弄反。","sec":"势的种类与成党规则","t":"diff"},{"q":"木火成势，所制的是什么？","opts":["火与燥土，同属一党","水，水中含金也同制","金，金中含水也同制","土，土中遁藏也同制"],"ans":2,"exp":"木火一党制金，金中含水同制；金水一党才制火与燥土。","sec":"势能制什么","t":"diff"},{"q":"下面哪两个字相见，不能看成一党？","opts":["午戌半合","巳午相邻","寅卯同木","未戌相刑"],"ans":3,"exp":"未戌刑、亥申穿都不能看成一党；卯午破单独存在也不成一家。","sec":"势的种类与成党规则","t":"rule"},{"q":"关于三会局，盲派有什么特别规定？","opts":["申酉戌、寅卯辰不论三会，巳午未、亥子丑才论","四方三会全都成局，只看是否透干","申酉戌、巳午未不论三会，寅卯辰、亥子丑才论","三会局都不成立，只论三合"],"ans":0,"exp":"戌是燥土不生金，辰是湿土反生金，所以申酉戌、寅卯辰不论三会；巳午未、亥子丑可结党成势。","sec":"（一）富贵八字：两个条件","t":"rule"},{"q":"局中被夹冲、夹克的字，按盲派口径能不能制死？","opts":["能，夹制比单制更有力","不能，任何夹制都制不死对方","夹冲能制死，夹合不能","能制死，但制后寿命受损"],"ans":1,"exp":"夹冲、夹克、夹合、夹穿等任何夹制，都不能将对方制死。","sec":"（一）富贵八字：两个条件","t":"rule"},{"q":"日支坐官杀库、财库，局中没有刑冲，库开不开？","opts":["自然开，坐下之库随日主可用","大运合库才开，刑冲反而封库","不开，墓库只有刑冲才能制","半开，只作辅助而无大功"],"ans":2,"exp":"口诀：坐下财官临库喜刑冲，不刑冲则不开；戌库要辰冲才能制。","sec":"三、命局层次：富贵、普通、差","t":"rule"},{"q":"制不干净的官杀，按盲派口径当什么看？","opts":["当比劫看","当印看","当食伤看","当财看"],"ans":3,"exp":"官杀被制不净、木党无法制净官时，官当财看；比劫禄做功的是劳碌的体力人。","sec":"（二）普通八字","t":"rule"}]},{"n":5,"level":"初级","title":"十天干与五行干支特性","qs":[{"q":"按盲派，甲乙木算「活木」须同时满足什么条件？","opts":["有近根，且不见金","有近根，且得水生","得月令当令，不论水","天干透水，不论根"],"ans":1,"exp":"活木＝有根＋得水生，缺一不可；根要在月令、坐支、时支，年支太远不当根。","sec":"一、甲乙木","t":"rule"},{"q":"甲辰日柱，局中遇酉。酉对这棵甲木的要害在哪？","opts":["酉冲卯木，使甲失去月令根","酉泄辰土之气，使水无源","酉合辰，铲断辰中乙根","酉金直接克断天干甲木"],"ans":2,"exp":"甲辰辰中有乙有癸本是活木，最怕埋根之铁；酉合辰即铲断辰中之乙，伤根。","sec":"一、甲乙木","t":"calc"},{"q":"卯月生的木，局中分别来酉与来申，结果有何不同？","opts":["来酉与卯合可容；来申冲坏卯","酉申都冲坏卯根，皆凶","酉申都被卯木克住，皆无妨","来酉冲坏卯；来申与卯合，金可容"],"ans":3,"exp":"春木不敢受冲克，有卯不敢见酉；申与卯合，合制了金，金可容。","sec":"一、甲乙木","t":"calc"},{"q":"乙木生在秋天（酉月），喜忌如何？","opts":["喜火怕水，怕有根喜无根","喜水润，有根无根皆可","喜水润怕火，喜有根","喜火也喜有根，水无妨"],"ans":0,"exp":"口诀「乙生酉月用火攻」：乙秋已是成熟庄稼，见水发霉，见火无水能成贵格，反怕有根。","sec":"一、甲乙木","t":"rule"},{"q":"丙火与丁火在旺衰上的要求，哪项对？","opts":["丙喜旺不怕衰；丁不能过旺","丙怕过旺也怕衰；丁旺而不烈、衰而不竭","丙不看旺衰；丁怕过旺","丙丁都怕衰，喜旺"],"ans":1,"exp":"丙火不能过旺，也怕衰、怕湿土晦；丁如烛灯，日主为丁不用看旺衰。","sec":"二、丙丁火","t":"diff"},{"q":"戊土日主遇官杀，哪种说法对？","opts":["寅卯官杀都不怕","寅卯官杀都怕","不怕寅木七杀，怕卯木正官","怕寅木七杀，不怕卯木正官"],"ans":2,"exp":"戊坐寅是长生之地，永远喜七杀、怕正官；官杀旺时仍要有制有化才有用。","sec":"三、戊己土","t":"rule"},{"q":"庚金弱，没有申酉之根时，该怎样取运才吉？","opts":["顺其性，见旺水","顺其性，见旺土生金","逆其性，见旺金帮扶","逆其性，见旺木火"],"ans":3,"exp":"庚见申酉之根要顺其性（旺水且有用）；弱则逆其性，见旺木火吉；不可亦顺亦逆，否则贱不可言。","sec":"四、庚辛金","t":"rule"},{"q":"庚金坐申禄，被局中其他字制得太过，结果是？","opts":["过制为凶，易出病灾伤灾","无碍，金本不看旺衰","只主破财，不涉身体","制得越净越吉，主官贵"],"ans":0,"exp":"庚见禄不能受制太过，禄到即寿到，过制易出病灾伤灾。","sec":"四、庚辛金","t":"rule"},{"q":"通源的壬癸水「流绝」，主什么？","opts":["主水不能做功，一生无为","只主寿绝，与做功得财官无关","主婚姻不成，夫妻缘薄","主破财，财官不聚"],"ans":1,"exp":"看有源之水是否流绝只涉及寿命；流到库归库不算流绝，无根无源之水也不论。","sec":"五、壬癸水","t":"diff"},{"q":"下面哪一组土，不克水反而生金？","opts":["戌、未","辰、戌","辰、丑","丑、未"],"ans":2,"exp":"辰丑为湿土，原则上不克水、生金；戌未为燥土，克水力大（戌克亥、未克子），不生金反脆金。","sec":"六、辰戌丑未","t":"diff"},{"q":"四墓库入墓的对应，哪一项是对的？","opts":["辰墓子不墓亥","戌墓午不墓巳","丑墓酉不墓申","未墓寅不墓卯"],"ans":3,"exp":"子午卯酉因有半合局关系不以墓论：辰墓亥不墓子，未墓寅不墓卯，丑墓申不墓酉，戌墓巳不墓午。","sec":"六、辰戌丑未","t":"diff"},{"q":"局中土金旺、又见丑酉，其中的巳火该怎么论？","opts":["归顺于金，合金局助金","仍为火性，克金制金","化为土，晦火生金","随月令定，不随局变"],"ans":0,"exp":"巳是唯一性质随环境改变的支：火旺有木生则为火克金；火弱土金旺、特别见丑酉则归顺于金。","sec":"六、辰戌丑未","t":"calc"}]},{"n":6,"level":"初级","title":"干支配置（上）：生克、自合与带象","qs":[{"q":"按盲派，同一柱内地支要克天干，必须满足什么条件？","opts":["地支必须有原神透出相生","地支必须得三合局相助","必先与天干合住，合而克之","地支必须得月令当旺"],"ans":2,"exp":"干为君、支为臣，天干克地支，地支不能克天干；只有先合住天干（天地自合）才能合制，如丁亥。","sec":"一、干支生克：君臣与互生","t":"rule"},{"q":"柱中有丁亥，又见巳冲亥，丁亥的自合还成立吗？","opts":["成立，冲只是动它不影响合","成立，反而合得更有力","不成立，要先有申合亥才行","不成立，地支被冲则不能自合"],"ans":3,"exp":"自合柱的地支若被它支冲，则不能自合：丁与亥中壬不能合。","sec":"二、自合：合而制之","t":"calc"},{"q":"盲派说自合柱的「合」，是什么性质？","opts":["合而制之，是做功，不是合绊","合而绊住，双方都不起作用","合而生之，是相生不是制","合而化气，转成另一五行"],"ans":0,"exp":"自合是合而制之，属做功方式，没有合绊的意思；强者制弱者，强弱看气势。","sec":"二、自合：合而制之","t":"rule"},{"q":"丙戌、壬戌的自合，戌要逢什么刑才算自合？逢另一种刑为何不算？","opts":["逢丑刑才合；逢未刑是坏戌","逢未刑开库才合；逢丑刑是坏戌","逢丑刑开库才合；逢未刑是坏戌","逢未刑才合；逢丑刑同样可合"],"ans":1,"exp":"戌逢未刑才开库，自合成立；逢丑刑（金水强时）是坏戌中所藏之物，不算自合。","sec":"二、自合：合而制之","t":"diff"},{"q":"自合九柱中，地支能合克天干的是哪四柱？","opts":["己亥、癸巳、壬戌、丙戌","丁亥、辛巳、壬午、戊子","丁亥、己亥、辛巳、癸巳","壬午、甲午、戊子、丙戌"],"ans":2,"exp":"前四柱丁亥、己亥、辛巳、癸巳地支可合克天干；壬午、甲午、戊子一般天干制地支；丙戌、壬戌须未刑开库。","sec":"二、自合：合而制之","t":"rule"},{"q":"盲派所说「统」，指的是什么情形？","opts":["天干与地支自合，合住不动","地支生天干，一柱表一个象","天干克地支，天干制住地支","天干生地支，一柱表一个象"],"ans":3,"exp":"天干生地支时，这一柱表一个象，上面的字代表下面的字，天干把地支统住了，如甲午、庚子、己酉。","sec":"三、干支之生与带象","t":"rule"},{"q":"下列四柱中，哪一柱属于带象十二柱？","opts":["癸卯","甲子","戊午","乙卯"],"ans":0,"exp":"带象是天干生地支且象一致：甲午、乙巳、丙辰、丙戌、丁丑、丁未、戊申、己酉、庚子、辛亥、壬寅、癸卯。甲子是支生干，戊午是支生干，乙卯是同类。","sec":"三、干支之生与带象","t":"calc"},{"q":"带象里意义最大的两种是什么？","opts":["食伤带比劫、财带食伤","官杀带财帽、印带官杀帽","禄带印帽、比劫带官帽","官杀带印帽、财带比劫帽"],"ans":1,"exp":"意义最大的只有官（杀）带财帽、印带官（杀）帽：印带官帽表示当官，官带财帽表示管财的官；其余作用不大一般不论。","sec":"四、带象的取用原则与命例","t":"rule"},{"q":"带象柱不与主位（日柱）发生关联，盲派怎么处理？","opts":["只在大运引动时才论","只论为宾位的他人象","一概不论，无关则无意义","照样论，只是力量弱一些"],"ans":2,"exp":"带象柱必须与主位有关联才论，关联方式有合、生、禄与原身换象、伏吟、拱局、入墓；刑冲穿一般不算关联。","sec":"四、带象的取用原则与命例","t":"rule"},{"q":"日主为戊，年柱为甲午，按盲派这是什么带象？","opts":["杀带财帽，主管财的官","印带官帽，必为正职","财带杀帽，主与财有关的官","印带杀帽，与日柱有关联则主当官"],"ans":3,"exp":"戊日见甲是七杀，午中丁为正印：印带杀帽，印带官杀帽表示当官，但须与日柱关联。","sec":"四、带象的取用原则与命例","t":"calc"},{"q":"与日主有关的官，在什么位置是正职、什么位置是副职？","opts":["主位坐下为正；宾位或合到时支为副","年支为正；时支被合为副","时支为正；日支被穿为副","宾位为正；主位坐下为副"],"ans":0,"exp":"官在宾位或被合到时支为副职；官在日支被它支穿（穿偏）也是副职；主神在主位、中神在坐下为正职。","sec":"四、带象的取用原则与命例","t":"diff"}]},{"n":7,"level":"初级","title":"干支配置（下）：互通、通根坐库与虚实","qs":[{"q":"按盲派，丁与己的禄（地支）分别是哪一个？","opts":["丁是午，己是巳","丁是巳，己是午","丁是午，己是未","都是午"],"ans":3,"exp":"丙、戊同禄巳，丁、己同禄午；己不禄未，四墓无原身。","sec":"一、干支互通：禄与原身","t":"calc"},{"q":"局中丙火日主自己制不了子水，却见时柱戊子，戊在盲派里起什么作用？","opts":["丙、戊同禄巳可互代，借戊来制","戊子天地合，只主合绊不主制","戊土克子水，但与丙火无关","丙、戊生克无关，戊制子归戊自己"],"ans":0,"exp":"丙戊同禄巳是一家，意思可互用，丙借戊制官等于自己制官。","sec":"一、干支互通：禄与原身","t":"rule"},{"q":"下列哪一柱天干与地支属半禄关系？","opts":["丁巳","丁未","己未","丙戌"],"ans":1,"exp":"未中有丁、丑中有癸，故丁未、癸丑为半禄；丙戌、丁巳是坐强根，不属半禄；己与未无关系。","sec":"二、半禄与一家","t":"diff"},{"q":"辰、戌、丑、未这四墓，在天干有没有原身？","opts":["有，辰戌丑未原身各为所藏本气之干","只有辰、戌有原身，丑、未没有","没有，不能认辰戌原身是戊，丑未原身是己","有，辰戌原身是戊，丑未原身是己"],"ans":2,"exp":"四墓在天干没有代言人，所以墓库必须靠刑冲才有用。","sec":"二、半禄与一家","t":"rule"},{"q":"盲派所说「通根」，指的是什么？","opts":["同一柱或相邻一柱的地支均算","天干在月令地支见根才算","天干在任何一柱地支见根都算","只指同一柱的地支为天干的根"],"ans":3,"exp":"天干在他柱地支见根不论通根，通根一定看坐下；此根不能被他支所伤。","sec":"三、通根与坐库","t":"diff"},{"q":"下面哪组是天干坐库、所坐之库即其根的「连根」四柱，日柱时不能被坏？","opts":["甲辰、丁未、乙未、丙戌","甲辰、丁丑、乙未、丙戌","甲戌、丁丑、乙丑、丙辰","甲辰、丁未、己未、丙戌"],"ans":0,"exp":"这四柱天干与所坐之库同气连根，其根被坏则损寿或伤健康；其余坐库之柱反而喜刑冲开库。","sec":"三、通根与坐库","t":"rule"},{"q":"日柱分别为甲辰、己未、乙丑、辛未，其中哪一柱最需要刑冲才合要求（干支同气又坐库）？","opts":["辛未，坐库不冲则损寿","己未，干支相同又坐库，无刑冲损财伤妻","甲辰，坐库必须冲开","乙丑，不冲就不吉"],"ans":1,"exp":"戊戌、戊辰、己丑、己未干与支同且坐库，须刑冲；甲辰辰是甲之根不需要冲；乙丑可冲可不冲。","sec":"三、通根与坐库","t":"calc"},{"q":"日柱干与支同且坐库（如戊辰）而无刑冲，一般如何断？为什么不能一律武断？","opts":["婚姻多不吉；有刑冲就一定吉","婚姻反好；无刑冲则不伤库","婚姻多不吉；刑冲只是必要条件，非充分条件","婚姻必不吉；无刑冲则库一定不开"],"ans":2,"exp":"财官临库喜刑冲，但组合不同意思会变，刑冲是引拔墓库财官的必要条件，不是充分条件。","sec":"三、通根与坐库","t":"rule"},{"q":"墓库要怎么作用才算「开」？","opts":["刑、冲、合都能开","三合、六合开库最稳","天干透出所藏之字即开","只有刑或冲才能开"],"ans":3,"exp":"墓只有刑或冲才算开，其他作用都不算；入墓只是带象与主位关联的一种方式。","sec":"三、通根与坐库","t":"rule"},{"q":"丙子、丙寅、丙午、丙戌四柱，其中哪柱的丙是虚透？","opts":["丙子","丙午","丙寅","丙戌"],"ans":0,"exp":"丙坐寅午戌有根有生为实，坐子申辰无根无生为虚；地支本身皆实。","sec":"四、干支虚实","t":"calc"},{"q":"财虚透而吉，主才气、人缘、不贪财，但有一个条件是什么？","opts":["不能透双","不能合","不能被冲","不能入库"],"ans":1,"exp":"财虚的人不贪财、人缘好，但一合日主就不一定了；不合则论吉，正财虚尤其好。","sec":"四、干支虚实","t":"rule"},{"q":"原局某字喜虚，大运流年使它通根变实，断为什么？","opts":["主吉，应期落实","正常，根深更有力","反常，象坏了，不吉","主迟发，只是晚运才好"],"ans":2,"exp":"喜虚的字运来见根变实则坏；喜实的字运来虚透也坏，以此断应期。","sec":"四、干支虚实","t":"rule"}]},{"n":8,"level":"初级","title":"合（一）天干五合","qs":[{"q":"按盲派，天干五合的看法是（　）。","opts":["只讲合不讲化，合是相克关系，是做功方式","合只主感情亲近，不属于做功方式","合则化为他行，合化成功才有力","合是相生关系，合了就失去克性"],"ans":0,"exp":"本派不主张合化；能合的两干必有克的关系，旺者把弱者制死，做功效率很高。","sec":"一、总论：合是什么、怎么用","t":"rule"},{"q":"合去、合伤、合绊三者的区别标准是（　）。","opts":["悬殊为合绊，不悬殊为合去，相当为合伤","悬殊为合去，不悬殊为合伤，相当为合绊","相当为合去，悬殊为合伤，不悬殊为合绊","看合的位置：年月为合去，日时为合绊"],"ans":1,"exp":"按双方力量对比：悬殊弱者制死是合去，强弱不悬殊弱者受伤是合伤，力量相当互相绊住是合绊。","sec":"一、总论：合是什么、怎么用","t":"diff"},{"q":"合伤与合去相比，伤六亲的应期和原局含义是（　）。","opts":["应期相同，原局合伤主六亲当年必死","应期略早，原局合伤多为当即破财","应期略晚，原局合伤多为待时而用","应期略晚，原局合伤主六亲全无"],"ans":2,"exp":"合伤弱者受伤未死，比合去略轻，伤六亲应期略晚，原局合伤一般是待时而用。","sec":"三、合伤","t":"diff"},{"q":"要断父亲早亡，必须具备什么条件？","opts":["父星被合去就可断，不必看宫","父星旺而无制，才可断","父宫被冲就可断，不必看星","父星与所坐的父宫同时被坏"],"ans":3,"exp":"看六亲生死，星与宫必须同时被坏；单坏星不一定死，宫有原神相生则一时死不了。","sec":"二、合去（合制）","t":"rule"},{"q":"口诀「父临库，父当早死」的意思是（　）。","opts":["父星落在墓库，不论旺衰都主父早亡","父星落在墓库，旺则无事，弱才早亡","父宫被冲开库，则父亲早亡","父星入库后逢冲，才主父早亡"],"ans":0,"exp":"父星落墓库不论旺衰，都主父早亡；库中有本气可延气，死得稍晚。","sec":"二、合去（合制）","t":"rule"},{"q":"男命月干辛（财）极弱，时干丙旺，丙辛相合，辛被丙合去，应怎么论？","opts":["辛只被合伤，待时再用，不论应期","辛被制去，所代表的财被得到，六亲则有问题","丙辛相绊，双方都失去原性","丙辛合化水，辛的财象转为水象"],"ans":1,"exp":"力量悬殊为合去：被合去之字若是财则被命主得到，若代表六亲则此人死；极弱者才称合去。","sec":"二、合去（合制）","t":"calc"},{"q":"流年天干合住原局旺字，「合留」与「合动」的区别是（　）。","opts":["合留主财，合动主婚姻","合留合动都主人，只是应期先后不同","合留主人，合动主事","合留主事，合动主人"],"ans":2,"exp":"合动与合留看法相同，合动主事，合留主人；多用合留断婚姻应期。","sec":"四、合留与合动","t":"diff"},{"q":"女命流年只合住夫星，夫宫未被动，应断为（　）。","opts":["结婚，夫宫不动才能稳定","结婚，夫星被合住即应婚期","离婚，夫星被合走","谈对象，不是结婚"],"ans":3,"exp":"星为对象、宫为丈夫；只合星是谈对象，星宫都被合动才是结婚应期。","sec":"合留","t":"rule"},{"q":"原局年干丙、日干辛，中间隔着月干戊，丙辛能否成合绊？","opts":["不能，隔开太远绊不住，须紧邻贴合","不能，合绊只在大运与原局之间成立","能，同在原局天干相合就可绊","能，只要年干与日干力量相当就绊"],"ans":0,"exp":"原局合绊要求紧邻两柱天干相合，远了绊不住；大运合原局任一柱才视为紧邻。","sec":"五、合绊","t":"calc"},{"q":"合绊之字被冲，会怎样？功神被绊又如何？","opts":["合绊逢冲则合得更紧；功神被绊反吉","合绊逢冲则不合，恢复原性；功神被绊不吉","合绊逢冲则化为他行；功神被绊反吉","合绊逢冲则双方皆伤；功神被绊不吉"],"ans":1,"exp":"合绊逢冲则不合，双方恢复原性；功神被绊失去作用不吉，忌神被绊则喜。","sec":"五、合绊","t":"rule"},{"q":"八字中食神合印、劫财合财、伤官合杀，换象后分别主（　）。","opts":["劫取之财、学术思想、伤官当权力","学术思想、合伙之财、伤官主灾病","学术思想、劫取之财、伤官当权力","学术思想、劫取之财、伤官主子女"],"ans":2,"exp":"食神合印是思想性学问；劫财合财是不劳而获的劫取之财；伤官合杀，伤官当权力看。","sec":"六、天干五合的换象原理","t":"xiang"}]},{"n":9,"level":"初级","title":"合（二）地支六合","qs":[{"q":"地支六合与天干五合相比，多出的一种合法是什么？","opts":["去合（合后一方被合走掉）","生合（一方生另一方，如辰酉）","破合（合后双方都被破坏）","化合（合后一定变成另一五行）"],"ans":1,"exp":"天干合只有克合；地支六合还有生合。六合一般不讲化，通称合绊。","sec":"一、六合总论","t":"diff"},{"q":"配偶星是正官或正财、坐在正位时，他星来合它，主什么？","opts":["主早婚，但婚姻没有什么影响","婚姻更稳固，合住了就不走","配偶被别人合跑，婚姻不顺","配偶星被制，反而更加吉利"],"ans":2,"exp":"得正位的配偶星不喜他星来合；若是偏星（偏财、七杀）则可被制。","sec":"一、六合总论","t":"rule"},{"q":"辰酉合属于哪一类合？辰酉合时被克伤的遁藏之气是什么？","opts":["克合兼闭气；酉中辛金被辰土克","生合；酉中辛金被辰土所克伤","克合；辰中癸水被酉金克伤","生合兼合伤；辰中乙木被酉克伤"],"ans":3,"exp":"辰酉是生合，又能闭辰中水库，并合伤辰中乙木。","sec":"二、六合的四种作用","t":"calc"},{"q":"墓库逢六合，库里的气怎样？怎样才能让库发挥作用？","opts":["合则库闭，只有逢刑、冲才能开库","合则库开，库气自然就流通了","合则库闭，逢合局再合才能开","合则库闭，逢穿才能够开库"],"ans":0,"exp":"墓库只有刑冲才能开；合库则闭气，库中遁藏之物成无用之物。","sec":"二、六合的四种作用","t":"rule"},{"q":"被生合保护着的字，若是局中「要制的字」，见大运流年再来生、来合，结果如何？","opts":["被制得更干净，吉","制不了，凶不可免","没有影响，仍可制","被生旺，反而转凶为吉"],"ans":1,"exp":"生合有「受保护」之意；要制的字被合保护就制不了。","sec":"二、六合的四种作用","t":"rule"},{"q":"婚姻应期的「合留」归纳：原局星宫已有合，流年用什么去应？","opts":["流年刑之为应","流年再合之为应","流年冲之为应","流年克之为应"],"ans":2,"exp":"原局星宫有合，流年冲应；原局有冲，流年合应；不冲不合，流年去合星或宫为应。","sec":"三、六合的用法","t":"rule"},{"q":"「流年合大运」与「流年干支与原局某柱天地合」，各是什么结论？","opts":["流年合大运为合绊；天地合为合动","两者都是合动，一概不论合绊","两者都是合绊，没有区别","流年合大运为合动；天地合按合绊"],"ans":3,"exp":"流年合正在行的大运不是互绊，而是引动大运；流年干支与原局某柱天地合才是合绊。","sec":"三、六合的用法","t":"diff"},{"q":"寅亥合时，寅得亥水之后，寅木的象是什么？","opts":["成湿木，不生火反灭火","成旺木，更能生火","成枯木，需要火去生","成死木，被水荡走"],"ans":0,"exp":"亥中壬水灭寅中丙火，寅得亥为湿木，不生火反灭火。","sec":"四、六合逐个详解（一）：寅亥、卯戌、辰酉","t":"calc"},{"q":"财库戌被卯合住（卯戌合），一见卯运流年会怎样？为什么？","opts":["卯制戌，库中财被制住而得财","闭了戌库，主破财","开了戌库，主发大财","合到卯财，主进财"],"ans":1,"exp":"卯戌合闭戌库，火库的作用要冲才发挥；原局财库被合闭，一见卯就破财。","sec":"四、六合逐个详解（一）：寅亥、卯戌、辰酉","t":"rule"},{"q":"六合里，哪一个合做功效率最高、能量最大？","opts":["午未合","子丑合","巳申合","辰酉合"],"ans":2,"exp":"巳申合最彻底；午未合最差，只增火力闭木库；子丑合效率不高。","sec":"五、六合逐个详解（二）：巳申、午未、子丑","t":"diff"},{"q":"子丑合「有两重性」，指的是什么？","opts":["既能合绊又能合去，要看流年","合后既成水又成土，五行互换","既可开库又可闭库，要看冲刑","好东西、坏东西都被绊，看大运扶谁"],"ans":3,"exp":"子丑合是合绊：局中毛病被绊是好事，好东西被绊是坏事；走哪边的运，哪一边被绊。","sec":"五、六合逐个详解（二）：巳申、午未、子丑","t":"rule"},{"q":"六合换象（互用对方信息）的前提条件是什么？","opts":["克合中一方制住另一方才能换","必须三合成局才能换象","必须天干透出才能换象","只要合上了就能换象"],"ans":0,"exp":"克合当一方制去一方时，象可互换；没有制住则不能换。","sec":"六、六合换象","t":"rule"}]},{"n":10,"level":"初级","title":"合（三）三合局与暗合","qs":[{"q":"亥、卯、未三字会聚成局，是什么局？中神是哪个字？","opts":["水局，中神卯","木局，中神亥","木局，中神卯","木局，中神未"],"ans":2,"exp":"亥卯未合木局，子午卯酉为中神，所以中神是卯；亥、未是佐神。","sec":"一、三合局总论","t":"calc"},{"q":"在天干五合、地支六合、三合等合法中，能「合化」成另一五行的是哪种？","opts":["只有六合能合化","天干五合与三合局都能合化","六合和三合局都能合化","只有三合局能合化"],"ans":3,"exp":"三合局是所有合法里唯一能合化的；六合讲紧密，不讲合成了什么。","sec":"一、三合局总论","t":"diff"},{"q":"三合局成不成局，同五行在天干透不透有关系吗？成局的必要条件是什么？","opts":["无关；三个字必须齐现，中神最重要","无关；只要两个字就能成三合局","必须中神透出天干，其他两字可缺一","必须同五行透出天干才成局"],"ans":0,"exp":"成局与天干透不透无关，必须三字齐现，其中中神位置最关键。","sec":"一、三合局总论","t":"rule"},{"q":"寅午戌合成火局后，寅木与戌土的力量各有什么变化？","opts":["寅木与戌土都被火泄，失去本性","寅木泄力从火势，戌土被生而增强","寅木被火克而弱，戌土被火泄而弱","寅木增力旺，戌土被火克而弱"],"ans":1,"exp":"寅木生火泄力、从了火势；戌被局中旺火所生，越生越旺。","sec":"二、三合局中各神的力量变化","t":"calc"},{"q":"卯、未两字同现，属于哪一类合？","opts":["生地半合木局（长生+帝旺）","三合木局","墓地半合木局（帝旺+墓库）","拱局（长生+墓库）"],"ans":2,"exp":"生地半合是长生+帝旺（亥卯）；墓地半合是帝旺+墓库（卯未）；拱局是长生+墓库（亥未）。","sec":"三、半合局与拱局","t":"calc"},{"q":"拱局（如亥未、寅戌、巳丑、申辰）与半合局的区别是什么？","opts":["拱局的成局力量比三合局还大","拱局必须天干透出才算","拱局有中神，半合局没有","拱局没有中神，只是虚拱着中神"],"ans":3,"exp":"拱局是长生+墓库、无中神，虚拱中神；半合局含帝旺中神。","sec":"三、半合局与拱局","t":"diff"},{"q":"三合局中若中神与他支有六合关系，怎么论？","opts":["六合更紧密，先论六合，剩下的支论半三合","三合与六合同时成立，不分先后","中神被合绊，整个三合局作废并换象","三合更紧密，六合不论"],"ans":0,"exp":"六合能解三合；长生支或墓支有六合，也是先论六合，剩余字论半三合。","sec":"四、三合局的用法与注意事项","t":"rule"},{"q":"亥卯未三合木局中，杂有紧贴的酉冲卯，局怎样？","opts":["木局力量略减但仍成","三合木局完全不成","亥未仍成半合木局","卯未仍成半合木局"],"ans":1,"exp":"酉冲中神卯则三合完全不成；巳冲亥则卯未半合仍成；丑冲未则亥卯半合仍成。","sec":"四、三合局的用法与注意事项","t":"calc"},{"q":"寅午戌三合中，午火中神在盘中出现两次，怎么论？","opts":["仍成三合局，火力加倍","按中神双现合绊论","不成三合局，以中神入墓论","成半合局，不入墓"],"ans":2,"exp":"中神双现或多现，不成三合局，以中神入墓论。","sec":"四、三合局的用法与注意事项","t":"rule"},{"q":"「相穿」与「刑、冲」在开墓库上的区别是什么？","opts":["穿、刑、冲都能开墓","穿能开墓，刑冲只会破墓","只有冲能开墓，刑穿都不能","相穿不能开墓，只有刑、冲才能开墓"],"ans":3,"exp":"提示：穿只是坏，不能开库；墓库须刑或冲才开。","sec":"四、三合局的用法与注意事项","t":"rule"},{"q":"下列哪一组是盲派所说的暗合（有别于六合）？","opts":["午亥暗合","寅亥相合","卯戌相合","巳申相合"],"ans":0,"exp":"暗合只有寅丑、午亥、卯申三组；寅亥、卯戌、巳申都是六合。","sec":"五、暗合","t":"diff"},{"q":"暗合与六合在「合绊」上的论法区别是什么？","opts":["暗合与六合一样，合了就被绊住","暗合不论合绊只论相制；流年合旺支才算合动","暗合一律为合绊，大运流年合也是绊","暗合与六合都只论相制，不论合动"],"ans":1,"exp":"原局紧邻暗合与大运暗合命局不论合绊，只论相制做功；流年合原局和大运旺支则合动应事。","sec":"五、暗合","t":"diff"}]},{"n":11,"level":"初级","title":"刑、破、害、墓","qs":[{"q":"盲派论相刑，只认哪两组？","opts":["寅巳申、子卯刑","丑戌未、辰午酉亥自刑","子卯刑、辰午酉亥自刑","寅巳申、丑戌未"],"ans":3,"exp":"只论寅巳申、丑戌未两组三刑；子卯在盲派是相破，自刑弃而不用。","sec":"一、相刑：寅巳申与丑戌未","t":"rule"},{"q":"寅巳申三字，拆开来按什么论？","opts":["寅巳论穿，巳申论合，寅申论冲","寅巳论合，巳申论穿，寅申论冲","寅巳论冲，巳申论穿，寅申论合","寅巳论穿，巳申论冲，寅申论合"],"ans":0,"exp":"口诀：寅巳带穿，巳申带合，寅申带冲，全见时才论三刑，刑只是附带作用。","sec":"一、相刑：寅巳申与丑戌未","t":"diff"},{"q":"局中金水旺，出现丑与戌相刑，谁刑谁、坏的是什么？","opts":["戌刑丑，坏丑中之土","丑刑戌，坏戌中之火","丑刑戌，坏戌中之金","戌刑丑，坏丑中之金水"],"ans":1,"exp":"丑戌刑：局中金水旺则丑刑戌，能坏戌中之火；局中木火旺则戌刑丑，能坏丑中之金水。","sec":"一、相刑：寅巳申与丑戌未","t":"calc"},{"q":"未与戌相刑（燥土刑燥土），结果怎样？","opts":["火被刑去，戌中金得生","金越刑越旺，火被制","火越刑越旺，戌中的金被制","火越刑越弱，土气转旺"],"ans":2,"exp":"未戌刑把戌未中的火引出来，火越刑越旺，但戌中的金被刑坏、被制。","sec":"一、相刑：寅巳申与丑戌未","t":"rule"},{"q":"原局有丑未相冲在做功，大运来戌，一般怎么论？","opts":["丑未冲加戌，只论冲不变","戌冲开库，做功得吉","戌来生助，做功更强","凑成三刑，原局做功被坏"],"ans":3,"exp":"原来的刑冲做功为吉，第三者来介入构成三刑，三字皆坏，功就没有了；原局丑戌刑做功则怕未来。","sec":"一、相刑：寅巳申与丑戌未","t":"calc"},{"q":"丑戌未之间的刑，近刑和远刑的作用分别是什么？","opts":["近刑坏库中遁藏，远刑开库","近刑开库，远刑坏库中遁藏","近刑远刑都只坏库不开库","近刑远刑都是开库"],"ans":0,"exp":"丑戌未是墓库，近刑刑坏墓库中的遁藏，远刑则能开库，库中之物得以为用。","sec":"一、相刑：寅巳申与丑戌未","t":"diff"},{"q":"子、卯、午、酉中，哪一对不属于相破？","opts":["卯与午","子与酉","子与卯","午与酉"],"ans":1,"exp":"相破只有子卯、卯午、午酉三组，子与酉之间没有相破。","sec":"三、相破：子卯、卯午、午酉","t":"calc"},{"q":"相破与做功是什么关系？","opts":["破可做功，子卯破例外有制意","破只表象，三组破都不做功","破只表象不做功，午酉破例外有制意","破是做功的一种，破即是制"],"ans":2,"exp":"破是象不是做功；唯午酉破因午旺能克酉，有制的意思，也做功。","sec":"三、相破：子卯、卯午、午酉","t":"rule"},{"q":"财星在局中见破，主什么？","opts":["发财","冲动得财","合财","破财"],"ans":3,"exp":"破的含义是无情、破坏、破耗财产，财星有破就是破财。","sec":"三、相破：子卯、卯午、午酉","t":"rule"},{"q":"局中有申，又见丑，通常怎么论？","opts":["申为长生，见丑必入墓","申酉丑三合，只论合局","申丑相冲，不入墓","申入未墓，丑与申无关"],"ans":0,"exp":"寅申巳亥长生见各自墓库必入：寅入未、申入丑、巳入戌、亥入辰。","sec":"五、墓库的原则","t":"calc"},{"q":"辛丑一柱，辛是否算入墓？","opts":["不算，但要冲开丑才行","不算，天干坐墓不为入墓","算，辛见丑必入墓","算，金入丑墓力度最大"],"ans":1,"exp":"天干坐墓，如辛丑、壬辰，天干得强根不是入墓；日主坐墓也不为入墓。","sec":"五、墓库的原则","t":"calc"},{"q":"酉见丑，什么情况才算入墓？","opts":["只要见丑，必入墓","酉旺时见丑才入墓","中神双现，或单见又特别弱","只要酉丑同现，一律当半合局"],"ans":2,"exp":"子午卯酉四正见其墓当半合局看，不为入墓；只有中神双现，或单见又特别弱时才入。","sec":"五、墓库的原则","t":"diff"}]},{"n":12,"level":"初级","title":"冲、穿（一）相冲","qs":[{"q":"天干相冲的四组是哪些？戊己为什么不冲？","opts":["甲庚、乙辛、丙壬、丁癸；戊己居中宫无对立","甲庚、乙辛、丙壬、丁癸；戊己力量太弱","甲戊、乙己、丙壬、丁癸；戊己居中宫","甲庚、乙辛、丙壬、戊癸；戊己同属土"],"ans":0,"exp":"天干四冲是方向相对的甲庚、乙辛、丙壬、丁癸；戊己居中宫，没有方位上的对立，所以不冲。","sec":"一、天干四冲与地支六冲","t":"rule"},{"q":"天干合处逢冲、冲处逢合，盲派一般看作什么的应期？","opts":["官司的应期","结婚的应期","破财的应期","离婚的应期"],"ans":1,"exp":"天干相冲的作用之一：合处逢冲、冲处逢合，一般是结婚的应期。","sec":"一、天干四冲与地支六冲","t":"rule"},{"q":"地支六冲中，下列哪种说法符合既冲又克、一方有冲无克的规则？","opts":["寅木冲克申金，申对寅只冲不克","巳火冲克亥水，亥对巳只冲不克","亥水冲克巳火，巳对亥只冲不克","卯木冲克酉金，酉对卯只冲不克"],"ans":2,"exp":"子克午、酉克卯、申克寅、亥克巳：施克一方冲克对方，被冲方对它有冲无克。","sec":"一、天干四冲与地支六冲","t":"diff"},{"q":"辰戌冲、丑未冲，与子午冲这类冲相比，有什么不同？","opts":["只冲库不冲藏干，库门洞开","双方土性相同，冲而不动","必有一方被冲坏，另一方劳力","遁藏人元互相混战，土本气因冲变虚"],"ans":3,"exp":"辰戌、丑未是遁藏的人元互相混战，辰戌丑未这几个土的本气因冲而变虚。","sec":"一、天干四冲与地支六冲","t":"rule"},{"q":"地支排成子、午、丑，午夹在子丑之间，冲与合怎么论？","opts":["合必破，论冲不论合","贪合忘冲，论合不论冲","冲合兼论，子午冲与子丑合同时成立","子午冲被子丑合化解，论合不论冲"],"ans":0,"exp":"冲神夹在两合神中间，合必破，论冲不论合。","sec":"二、冲的四种作用","t":"calc"},{"q":"地支排成午、子、丑，冲神午在合神子丑之外且紧邻，冲与合怎么论？","opts":["合必破，论冲不论合","伤合，冲合兼论","冲被合化解，两者皆不论","贪合忘冲，论合不论冲"],"ans":1,"exp":"冲神在合神之外且紧邻是伤合，子午冲与子丑合同时成立；若隔开不紧邻则贪合忘冲，论合不论冲。","sec":"二、冲的四种作用","t":"calc"},{"q":"「旺神冲衰衰神拔，衰神冲旺旺神发」，后一句是什么意思？","opts":["衰者冲旺者，旺者被冲走离开","衰弱者冲旺者，旺者被冲坏","衰弱者冲旺者，不伤旺者反把它冲起来","旺者冲旺者，两败俱伤而空"],"ans":2,"exp":"失时衰弱者冲旺者，不仅伤不了旺者，反而把它冲起来，使之更旺；旺冲衰则衰者被拔除。","sec":"二、冲的四种作用","t":"rule"},{"q":"冲墓库时，近冲与隔冲、遥冲、运冲、岁冲有什么区别？","opts":["近冲与其余都是开库，力度不同","近冲开库引出为用；其余坏库中物","近冲坏库中物；运冲岁冲也坏库中物","近冲坏库中物；其余为开库引出为用"],"ans":3,"exp":"墓库相邻而冲，冲坏的是库里的遁藏之物；隔冲、遥冲、运冲、岁冲则为开库，库中之物得以引出为用。","sec":"二、冲的四种作用","t":"diff"},{"q":"原局出现夹冲（如两子夹冲一午），受冲的字会怎样？","opts":["不能被冲坏，像夹板走不了","被冲开库，库中物引出为用","被冲走离开，应期在运岁","必被冲坏，两冲一力量更强"],"ans":0,"exp":"原局的夹冲不能把受冲者冲坏或冲制：夹冲像夹板，被夹的走不了，既不会死也不会跑。","sec":"三、原局相冲的用法","t":"rule"},{"q":"盲派说冲的换象，条件和结果是什么？","opts":["小的冲倒大的，大的带小的性质","大的制去小的，小的带大的性质","大的制去小的，小的性质不变","两方势均力敌，各带对方性质"],"ans":1,"exp":"冲制时力量大的一方制去力量小的一方，被制的一方必带冲方的性质，如劫财被财制，当财看。","sec":"四、冲的换象","t":"rule"},{"q":"流年冲大运，正行天干运和正行地支运，结果有何不同？","opts":["天干运与地支运都是把大运冲走","天干运、地支运都是提前引动运支","天干运提前引动运支；地支运冲走大运","天干运冲走运支；地支运提前引动"],"ans":2,"exp":"正行天干运时，流年冲运支，运支被提前引动发生作用；正行地支运时，流年冲是冲去、冲走，反使大运不起作用。","sec":"五、大运、流年与冲","t":"diff"},{"q":"大运冲原局中相同的两个或三个字（如原局两寅逢申运），一般怎么论？","opts":["合冲相抵，不起作用","冲开库，库中物引出","冲坏，那个字被冲去","冲动，那个字发动起作用"],"ans":3,"exp":"大运冲原局相同的两个或三个字，一般是冲动（寅发动起作用），不是冲坏冲破。","sec":"五、大运、流年与冲","t":"rule"}]},{"n":13,"level":"初级","title":"冲、穿（二）相穿","qs":[{"q":"十二支六组相穿是（　）。","opts":["子丑、寅亥、卯戌、辰酉、巳申、午未","子未、丑午、寅巳、卯辰、申亥、酉戌","子午、丑未、寅申、卯酉、辰戌、巳亥","子未、丑午、寅亥、卯辰、申巳、酉戌"],"ans":1,"exp":"冲其合神者即为穿：子合丑而未冲丑，所以子未穿，其余依六合类推。","sec":"（一）六穿与\"冲其合神\"","t":"rule"},{"q":"午本要与未合，而丑来冲未，午与丑按盲派叫什么关系？","opts":["丑午相合，合神相会","丑午相刑，互相刑伤","丑午相穿，冲其合神","丑午相冲，正面对冲"],"ans":2,"exp":"午未合，丑冲未，冲掉了午的合神，午丑成相穿，相互为仇敌。","sec":"（一）六穿与\"冲其合神\"","t":"calc"},{"q":"穿与冲的区别，盲派的看法是（　）。","opts":["冲和穿都是正面来，只是力量大小不同","穿从正面来可跑，冲从侧面来躲不开","冲的杀伤力胜过穿，应事比穿更准","冲从正面来可跑，穿从侧面来躲不开，是仇敌"],"ans":3,"exp":"冲是正面来、敌不过可跑，有冲走冲动之意；穿是侧面来、防不胜防，杀伤力胜过冲，必应事，多应六亲。","sec":"（二）穿与冲的区别","t":"diff"},{"q":"「穿倒」与「穿偏」的判断依据区别是（　）。","opts":["穿倒要比较双方力量，穿偏不管力量只要有穿","穿倒不管力量只要有穿，穿偏要比较力量","穿倒与穿偏都要比较双方力量大小","穿倒看原局，穿偏看大运流年"],"ans":0,"exp":"穿倒看势，被穿一方立不住才倒；穿偏看象，只要有穿，正的就偏、偏的转正。","sec":"（一）穿倒与穿偏","t":"diff"},{"q":"六穿里「相克又穿」最严重的是哪一组？","opts":["子未、卯辰、申亥、寅巳","子未、卯辰、酉戌、丑午","子未、寅巳、酉戌、卯辰","寅巳、申亥、酉戌、丑午"],"ans":1,"exp":"申亥、寅巳是生中带穿，杀伤力小，只有克穿的四组最重。","sec":"（二）克穿重、生穿轻","t":"rule"},{"q":"口诀「吉神被穿主凶，凶神被穿为吉」之外，不用之神被穿应怎么论？","opts":["不用之神被穿，看大运再定吉凶","不用之神被穿也论凶","不用之神被穿也论吉","不用之神被穿不论吉凶"],"ans":2,"exp":"总原则：吉神被穿主凶，凶神被穿为吉，不用之神被穿也论吉。","sec":"（一）原局中的穿","t":"rule"},{"q":"日主坐下的配偶星，被穿时怎么看？","opts":["偏星正星被穿都主婚姻必坏","正星可以被穿无凶，偏星绝不能受穿","偏星正星被穿都无妨，只看大运","偏星可以被穿无凶，正星绝不能受穿"],"ans":3,"exp":"男命坐偏财、女命坐偏官的偏星可以被穿；坐正的配偶星绝对不能受穿。","sec":"（一）原局中的穿","t":"rule"},{"q":"日、时上的禄，对冲与穿的态度是（　）。","opts":["不怕冲，怕穿","冲穿都怕","不怕穿，怕冲","冲穿都不怕"],"ans":0,"exp":"日时上的禄不怕冲，怕穿；日主坐财则可合制不可穿制。","sec":"（一）原局中的穿","t":"rule"},{"q":"夫宫是戌而夫星是酉，酉戌相穿，按盲派应怎么断？","opts":["夫宫穿夫星为开库，主婚姻变好","夫宫穿坏夫星，严重克夫","夫星制夫宫，女管丈夫婚姻好","夫宫夫星相穿，穿而不制反主长寿"],"ans":1,"exp":"酉戌穿中戌为燥土伤食库，坏酉金，夫宫穿夫星就是严重克夫；穿是仇恨，不是制。","sec":"（六）酉戌穿","t":"rule"},{"q":"穿的字被流年合住，对穿的作用有什么影响？","opts":["合可解穿，但只解生穿，不解克穿","穿的字被合住，改为穿而变冲","合可解穿，穿的字被合住则不起作用","合不解穿，穿的力量反而加倍"],"ans":2,"exp":"提示：合可解穿，穿的字被流年合住、绊住，穿就不起作用；穿中结婚往往靠此。","sec":"三、穿的用法","t":"rule"},{"q":"卯辰穿属于克穿，对辰土而言应怎么理解？","opts":["卯辰穿为生穿，主动不主凶","卯辰穿能开辰库，与冲刑同样","卯辰穿开库，但只开一半","墓库被穿不为开库，不同于冲、刑"],"ans":3,"exp":"墓库被穿不为开墓库，如卯辰穿不是开辰库，这与冲、刑不同；卯克辰，是克穿。","sec":"（一）原局中的穿","t":"rule"}]},{"n":14,"level":"初级","title":"做功方式与制局通辨（上）：做功的六种方式","qs":[{"q":"按盲派做功层次，制用、化用、生泄用的高低顺序是？","opts":["制用高于生泄用，生泄用高于化用","化用高于制用，制用高于生泄用","制用高于化用，化用高于生泄用","生泄用高于化用，化用高于制用"],"ans":2,"exp":"口诀：反胜正，制胜化，化胜泄；制是取得占有，化是借力，生是耗自己之力。","sec":"九、做功方式与层次高低","t":"step"},{"q":"做功层次上，「用凶神做功」与「用吉神做功」，哪个效果更大？凶神、吉神各指什么？","opts":["吉神更大：吉为禄印官，凶为财杀劫","凶神更大：凶为杀劫食伤，吉为禄印官","吉神更大：吉为杀劫刃枭，凶为禄印官","凶神更大：凶为杀劫刃枭，吉为禄印官"],"ans":3,"exp":"凶神指杀、劫、刃、枭，吉神指禄、印、官；无论正向反向，用凶神做功效果更大。","sec":"九、做功方式与层次高低","t":"diff"},{"q":"制用结构不可去日主之根。下列日柱中，哪个被制不涉及寿命？","opts":["戊辰","乙卯","辛酉","甲寅"],"ans":0,"exp":"日主的根（连根）不能制，制了伤寿；乙卯、甲寅一类连根草，辛酉也麻烦，戊辰一类不连根，无所谓。","sec":"二、制用结构（去用结构）","t":"calc"},{"q":"化用结构成立，印与官杀、印与日主的位置各有什么要求？","opts":["印只须出现在年月，位置不拘","印须紧贴官杀，又须紧贴日主","印须紧贴官杀，可隔位生日主","印可隔位化官杀，须紧贴日主"],"ans":1,"exp":"印与官杀隔位则化不了，与日主隔位则生不了身；有官杀有印不等于化用。","sec":"三、化用结构","t":"rule"},{"q":"局中官杀俱旺而无制无化，大运走印星来化官杀，怎么论？","opts":["按制用论，印制官杀","按生用论，印生日主","按化用论，大运补上","仍属无用结构，大运无用"],"ans":2,"exp":"局中官杀俱旺无制化，如果大运有印来化官杀，也按化用论。","sec":"三、化用结构","t":"rule"},{"q":"伤食生财的结构，最怕什么？","opts":["生财的字被冲、被克、入禄","伤食被印制、被官杀克","财星被日主合、被比劫夺","生财的字被穿、被合、入墓"],"ans":3,"exp":"食伤生财最怕生财的字被穿、被合、入墓：做功的字坏了，象就坏了。","sec":"四、生用、泄用结构","t":"rule"},{"q":"日主合财，身旺而财弱，按盲派怎么论？","opts":["不穷，有钱花，一般人","合财可发大财","有财但不会大，不缺吃喝","必是穷人"],"ans":0,"exp":"日主合财看身强弱四档：旺旺发大财，弱旺必穷，旺弱不穷一般人，弱弱有财不大。","sec":"五、合用结构","t":"calc"},{"q":"日主合的是虚透之财，按盲派如何论？","opts":["当财看，身弱则穷","表示才华，不当财看","表示官职，不当财看","当财看，身旺必富"],"ans":1,"exp":"例外：日主合虚透之财，则此财表示才华，身旺合虚财也不表示穷。","sec":"五、合用结构","t":"rule"},{"q":"墓用结构里，做功的字入墓，对做功有什么影响？","opts":["入墓只影响内食神格","入墓则做功失效，必须开库","不影响做功，入墓与做功是两层意思","入墓后做功减半"],"ans":2,"exp":"墓指得到、控制、管理、拥有；入墓并不影响做功，库可开可不开。","sec":"六、墓用结构","t":"rule"},{"q":"体在主位制宾位的用，与用在主位、体在宾位，各叫什么做功？","opts":["前者化用，后者制用","前者反向做功，后者正向做功","两者都叫正向做功","前者正向做功，后者反向做功"],"ans":3,"exp":"体在主位、用在宾位为正向；用在主位、体在宾位等为反向，要求制得干净有力。","sec":"八、正向做功与反向做功","t":"diff"},{"q":"反向做功制宾位的字时，什么情形下不可制？","opts":["宾位的字是寿元星，制之伤寿","宾位的字是官星，制之失官","宾位的字是财星，制之破财","宾位的字是食神，制之无子"],"ans":0,"exp":"反向做功要看宾位有没有寿元星，寿元星在宾位，制之必伤寿；并且制得不干净不算。","sec":"八、正向做功与反向做功","t":"rule"},{"q":"复合结构里，制神与化神各喜虚透还是要实？","opts":["制的东西要实，化的东西喜虚透","制的东西喜虚透，化的东西要实","制与化的东西都要实","制与化的东西都喜虚透"],"ans":1,"exp":"制的东西虚透就跑了更好制；化的东西要实，虚的不能化。","sec":"七、复合结构","t":"rule"}]},{"n":15,"level":"初级","title":"做功方式与制局通辨（下）：制局配置与制法效率","qs":[{"q":"地支合制的效率，下列哪一项排在最高档？","opts":["子丑合","卯戌合","寅亥合","巳申合"],"ans":3,"exp":"合制效率：巳申最高，卯戌、卯申、午亥、巳酉次之，子丑、寅丑中，同党合制低，午未不为制。","sec":"（一）合制","t":"step"},{"q":"同样是「合」，午未合与寅亥合在制用上有何区别？","opts":["午未合不为制，寅亥合只制遁藏","两者都能把对方整个制死","午未合制效率高，寅亥合不制","午未合只制遁藏，寅亥合不为制"],"ans":0,"exp":"午未两字相生，仅闭未库，不算制；寅亥、辰酉、午戌为同党相合，只是遁藏被制（亥中壬灭寅中丙）。","sec":"（一）合制","t":"diff"},{"q":"冲刑制的效率排序，最高的是哪一类？","opts":["寅申冲、巳亥冲","丑未冲、辰戌冲、丑戌刑等库冲库刑","力量相当的任何冲","子午冲、卯酉冲"],"ans":1,"exp":"口诀：库冲库刑最高，寅申巳亥次之，子午卯酉再次，势均不制。","sec":"（二）冲制、刑制","t":"step"},{"q":"局中一个子与一个午相冲，双方党力相当，按盲派怎么论？","opts":["两败俱伤，必有大凶","午制子，算制用做功","能量互相耗散，不做功","子制午，算制用做功"],"ans":2,"exp":"冲刑制必须一方之党大于另一方之党才能制；势均则互耗，不做功。","sec":"（二）冲制、刑制","t":"rule"},{"q":"克制的一般效率如何？什么情况属例外而效率很高？","opts":["一般效率低；官杀克比劫才算例外","一般效率最高；围克效率更低","一般效率低；单克有势才算例外","一般效率低；围克制得干净"],"ans":3,"exp":"克制效率低，多为普通人；唯一例外是围克——包围制之，被制者无处可逃，常成贼捕，势中天干作用大。","sec":"（三）克制","t":"diff"},{"q":"地支六穿中，哪几组可以相制，且「穿而又克」效率最高？","opts":["酉戌、卯辰、子未、丑午","子未、丑午、寅巳、申亥","申亥、寅巳、酉戌、卯辰","酉戌、卯辰、申亥、丑午"],"ans":0,"exp":"申亥穿、寅巳穿是生穿，只表破坏之象，不能相制；酉戌、卯辰、子未、丑午可制，穿而又克效率最高。","sec":"（四）穿制","t":"rule"},{"q":"主位（日主）与财相穿，按盲派怎么论？","opts":["只影响婚姻，不影响财运","自己与财无缘，穿则无财之象","穿制得财，主发大财","只有女命主位穿财才无缘"],"ans":1,"exp":"穿可制印、官杀、伤食，唯独主位与财不能穿。男命一生与婚姻无缘但财运可以，女命则一生无财。","sec":"（四）穿制","t":"rule"},{"q":"被制者被制净制死的叫「贼捕」结构，这种结构大运喜见什么？","opts":["制者（捕）","生制者之印","被制之神（贼）","合住制者之神"],"ans":2,"exp":"制净者喜大运见被制之神（贼）；制不净者喜大运见制者（捕），制不净的官杀还要当财看。","sec":"一、制局的基本原则","t":"rule"},{"q":"日主的禄落在不同位置，哪一处的禄一定不能被制？","opts":["年支的禄","月支的禄","时支的禄（可冲不可穿）","日主坐支的禄（日主之根）"],"ans":3,"exp":"落在年、月的禄可制，时支的有时可制，坐支之禄是日主之根，一制就伤寿或反局。","sec":"（一）日主之根不可制","t":"rule"},{"q":"日主甲乙且为活木时，哪些位置的根不可制？","opts":["坐支、月支、时支之根","只有坐支之根","坐支和年支之根","年支、月支、时支之根"],"ans":0,"exp":"活木根不但坐支不能制，月支、时支的根也不能制；年上的根不当根论，大都可制。","sec":"（二）甲乙活木：根不可伤","t":"rule"},{"q":"六亲星居于对应的六亲宫（得正位）而被制，会怎样？","opts":["要看大运才定吉凶","伤及对应的六亲","只主本人破财","该六亲得力有福"],"ans":1,"exp":"例如子女星在子女宫被制，则子女有伤残之象；财居父母宫被合去伤父。","sec":"（三）六亲星得正位被制，伤六亲","t":"rule"},{"q":"歌唱类取财命局中，「嗓音好」的象是什么？","opts":["水主声音，土克水","金主声音，水生金","金主声音，火克金","木主声音，金克木"],"ans":2,"exp":"名人命局规律：金主声音，火克金主嗓音好；壬水为彩在门户，丁壬合是脸上添彩，主唱戏演员。","sec":"五、名人命局汇粹：体力与技艺取财","t":"xiang"}]},{"n":16,"level":"初级","title":"应期入门","qs":[{"q":"某件事在原局落在日柱，大限上大致应在哪个年龄段？","opts":["35—55 岁","1—18 岁","18—35 岁","55 岁以后"],"ans":0,"exp":"年柱1—18，月柱18—35，日柱35—55，时柱55岁以后；大限只是模糊概括。","sec":"二、大限应期","t":"calc"},{"q":"原局大限应凶（如克父），而对应的那步大运是吉运，该怎么断？","opts":["此运照样凶，吉运压不住","此运不凶，过了此运才凶","此运不凶，过运也不再凶","此运先吉后凶，运中即应"],"ans":1,"exp":"交脱诀：限应凶而逢吉大运，则过运应凶，不看应期。","sec":"二、大限应期","t":"rule"},{"q":"原局大限应凶，应期尚未走到吉运之前，凶应不应？","opts":["不应，凶要等吉运过后","半应，只应一半","照样应，未到吉运必见凶","不应，吉运提前化解了"],"ans":2,"exp":"限应凶、后逢吉大运，则未到吉运前凶照应；吉运里才是吉。","sec":"二、大限应期","t":"rule"},{"q":"按盲派，原局的字在运岁中「出现」（反客为主），有哪两种方式？","opts":["逢冲，或逢入墓","通禄，或逢三合","现原身，或逢六合","通禄，或现原身"],"ans":3,"exp":"原局之字在运岁见它的禄，或在运岁天干透出它的原身，就是该字到了。","sec":"三、反客为主（出现）","t":"rule"},{"q":"日主之禄在日柱之前的年、月，对应大运再见禄，是不是寿到？","opts":["不是，只日柱及以后的大限才怕见禄","不是，但见禄必有大灾","是，但只限男命","是，见禄即寿到"],"ans":0,"exp":"禄在日柱之前，对应运见禄不是寿到；晚年及时柱的禄，运岁再见才寿到。","sec":"三、反客为主（出现）","t":"rule"},{"q":"要用的字和要去的字，在大运虚透时各是什么结果？","opts":["要用之字虚透则吉；要去之字虚透则不吉","要用之字虚透则不吉；要去之字虚透则吉","两者虚透都吉，因虚主轻化","两者虚透都不吉，应期落空"],"ans":1,"exp":"要用的字怕虚透、喜见实；要去的字喜虚透、怕见实。","sec":"四、虚透与用忌的应期","t":"diff"},{"q":"原局是贼捕结构（被制之神制得干净），大运流年喜见哪一边？","opts":["贼、捕都不喜，要见别的字","贼、捕都喜，见即有应","喜见贼，不喜只见捕不见贼","喜见捕，不喜见贼"],"ans":2,"exp":"贼指被制之字，捕指制它的字；局成贼捕，运岁见贼为吉。","sec":"四、虚透与用忌的应期","t":"rule"},{"q":"原局不成贼捕、被制之神制得不干净，运岁喜见什么？","opts":["喜见被制之神的原神","喜见被制之神","喜见主制之神的克神","喜见主制之神"],"ans":3,"exp":"制不净则需运岁再来补制，所以喜见主制之神；成贼捕的才喜见贼。","sec":"四、虚透与用忌的应期","t":"rule"},{"q":"原局有戌，运岁天干透出丁火，按盲派应怎么看？","opts":["丁代表戌，等同戌到","丁代表午，与戌无关","丁与戌相克，主戌受伤","丁只主火气，不代表地支"],"ans":0,"exp":"地支遁藏的字在运岁天干出现，就是该地支的应期，作用等同于该地支。","sec":"五、遁藏透干与刑冲合穿墓的应期","t":"calc"},{"q":"「合者主到，冲者主动，墓者主收，穿者主伤」，下列对应哪组是对的？","opts":["冲主受伤，穿主动起来","冲主动起来，穿主受伤","合主动起来，墓主受伤","墓主动起来，穿主到位"],"ans":1,"exp":"口诀是合到、冲动、墓收、穿伤；作用到谁，谁就应事。","sec":"五、遁藏透干与刑冲合穿墓的应期","t":"diff"},{"q":"原局午未合、夫宫未被合住，运岁见丑，对婚姻应期怎么论？","opts":["丑与午相穿，主婚破","丑与未无关，不应事","丑冲开所合的未，是结婚应期","丑合住午，主婚不成"],"ans":2,"exp":"原局夫宫逢合、运岁逢冲刑，冲开所合主婚成；合与冲互为解、促。","sec":"六、婚姻应期","t":"calc"},{"q":"配偶星在年月和在日时，对婚期早晚各有什么提示？","opts":["年月日时都一样，只看大运","年月早婚，日时必不婚","在年月相对晚婚，在日时相对早婚","在年月相对早婚，在日时相对晚婚"],"ans":3,"exp":"配偶星位置靠前则早婚、靠后则晚婚；前提是配偶星必须与夫妻宫有关系。","sec":"六、婚姻应期","t":"rule"}]},{"n":17,"level":"初级","title":"基础问题","qs":[{"q":"按盲派粗略起运法，生日距节令8天，起几岁运？","opts":["1岁","3岁","4岁","2岁"],"ans":1,"exp":"天数差除以3：8÷3＝2余2，余2进1，得3岁。","sec":"起运岁数","t":"calc"},{"q":"盲派粗略起运法，起运岁数有什么上下限？","opts":["最小1岁，最大8岁","最小3岁，最大12岁","最小1岁，最大10岁","最小0岁，最大10岁"],"ans":2,"exp":"起运岁数最小1岁、最大10岁，4天以内都按1岁运，且按虚岁计。","sec":"起运岁数","t":"rule"},{"q":"盲派交运的时辰，按什么来定？","opts":["出生月令的五行","日主的五行","出生时辰的五行","年的纳音五行"],"ans":3,"exp":"交运时辰按年的纳音五行定：火命、土命、金命、木命、水命各有固定节气与时辰。","sec":"交运时间","t":"rule"},{"q":"年纳音为水命的人，交运时间是哪个？","opts":["冬至前三天亥时","处暑当日申时","大寒当日寅时","清明前三天午时"],"ans":0,"exp":"水命人冬至前三天亥时；火命清明前三天午时；金命处暑当日申时；木命大寒当日寅时；土命芒种后九天辰时。","sec":"交运时间","t":"calc"},{"q":"丙日早子时的时柱是戊子。按盲派，丙日夜子时的时柱是什么？","opts":["壬子","庚子","戊子","丙子"],"ans":1,"exp":"夜子时的纳干要从早子时数一圈后纳：戊子往后数满十二个时辰，得庚子（与乙日早子丙子→夜子戊子同法）。","sec":"二、子时","t":"calc"},{"q":"夜子时与早子时的区别，按盲派怎么讲？","opts":["早子时与夜子时按同一天算，时干完全相同","早子时是23至24点，夜子时是0至1点，二者纳干相同","早子时是0至1点，夜子时是23至24点，夜子时干要数一圈","夜子时按次日起时干，早子时按当日起时干"],"ans":2,"exp":"以24点换日，早子时为当日凌晨0—1点，夜子时为当日深夜23—24点；夜子时时干从早子时数一圈后纳。","sec":"二、子时","t":"diff"},{"q":"盲派说的「正用」与「反用」，区别是什么？","opts":["正用是日主制官杀；反用是官杀制日主","正用是原局作功；反用是大运作功","正用是宾位的体制主位的用；反用是体落主位、用落宾位","正用是主位的体制宾位的用；反用是用落主位、体落宾位"],"ans":3,"exp":"口诀：正用——主位的体，制宾位的用；反用——用的东西落在主位，体落在宾位。","sec":"三、如何看八字：宾主与正用、反用","t":"diff"},{"q":"功神、废神、忌神三者，哪个说法对？","opts":["能做功的是功神，不能做功的是废神，起坏作用的是忌神","旺的是功神，弱的是废神，克日主的是忌神","能做功的是用神，不做功的是忌神，起坏作用的是废神","能做功的是功神，不做功的是忌神，起坏作用的是废神"],"ans":0,"exp":"能做功的神叫功神，不能做功的叫废神，坏事的叫忌神；本体系所说用神实际就是功神。","sec":"基本概念","t":"diff"},{"q":"合制中，下列哪个效率最高？","opts":["寅亥合","巳申合","午戌合","卯戌合"],"ans":1,"exp":"巳申合效率最高，原神用神都能制死；卯戌、卯申、午亥、子丑、寅丑也较高；寅亥合、午戌合很低。","sec":"制用结构中效率高低","t":"step"},{"q":"克制中，效率最高与最低的分别是哪两种？","opts":["贴克最高，围克最低","天克地最高，围克最低","围克最高，贴克最低","围克最高，天克地最低"],"ans":2,"exp":"围克效率最高（如丙戌丙申围住申金），天克地也行但天干必须有势；贴克很低，特别费劲。","sec":"制用结构中效率高低","t":"step"},{"q":"冲制中，哪种冲的效率最高？","opts":["地支相冲，冲日支最好","四正位互冲，旺冲衰最好","天干相冲，隔位冲最好","库冲，挨住冲最好"],"ans":3,"exp":"冲制以库冲效率最高，挨住冲最好；挨不住冲效率也不行。","sec":"制用结构中效率高低","t":"rule"},{"q":"反局为什么叫最凶？它分哪两类？","opts":["原局反局与大运反局，出灾、破财、死亡","原局反局与流年反局，主官非、破财","日主反局与月令反局，主丧偶、破财","合局反局与冲局反局，主疾病、出灾"],"ans":0,"exp":"反局是日主（或日柱）所表意思与八字整体意思相反，分原局反局与大运反局；大运反局要出灾，比原局反局多见。","sec":"五、正局与反局入门","t":"diff"}]},{"n":18,"level":"初级","title":"婚姻与看寿入门","qs":[{"q":"女命夫妻宫占印，这个印算不算丈夫？","opts":["局中有官才算丈夫，无官则不算","不论有无官，印都算丈夫来论","局中有官则不算，无官才可当丈夫","印是中性的，一律不算丈夫看待"],"ans":2,"exp":"印是中性的东西：只要八字中有官，印就不作丈夫看，无官时印才可当丈夫看；夫妻宫印旺是妻管严。","sec":"先看夫妻宫占什么六亲","t":"diff"},{"q":"男命夫妻宫占七杀，局中又见财星，配偶星取哪个？","opts":["取食伤，食伤生财","财官并取，一妻一妾","取七杀，官杀即妻","取财星，财生官杀"],"ans":3,"exp":"男命占官杀，要看有没有财：有财，财生官杀，财为配偶星；无财，官杀才作配偶星。","sec":"先看夫妻宫占什么六亲","t":"calc"},{"q":"女命夫妻宫占伤官而制不住官，婚姻怎么断？","opts":["管不住老公，婚姻不好或老公外有说法","官被伤尽，克夫，终身难嫁出去","伤官生财，丈夫有钱，婚姻美满","伤官泄秀，丈夫能干，家庭和顺"],"ans":0,"exp":"伤官一定要制官，制住官才得官；制不住则管不住老公，一是婚姻不好，二是老公外面有说法。","sec":"先看夫妻宫占什么六亲","t":"rule"},{"q":"配偶星入配偶宫（得正位），若被冲克坏，主什么？","opts":["配偶远走他乡","配偶病灾或死亡","婚姻多次变动","配偶富贵但感情淡"],"ans":1,"exp":"配偶星入配偶宫是得正位，好坏都不宜将其冲克坏；若坏掉，易出现配偶病灾或死亡。","sec":"判断婚姻好坏的初级法则","t":"rule"},{"q":"男命婚外情的三个条件，哪组正确？","opts":["混杂官杀透干；财多无制；食伤见官杀同现","伤食有制；七杀入墓；财星被他神所合住","混杂财星透干；伤食无制；七杀为桃花入主","混杂财星透干；印旺无财；比劫来夺财星"],"ans":2,"exp":"男命：财星混杂（与妻宫有关）且透干；伤官食神无制（放纵）；七杀（官星亦然）为桃花入主位。","sec":"男命","t":"rule"},{"q":"女命禄入主与他神相合成桃花，外合与内合的区别是？","opts":["外合主离婚收场；内合主不离婚","外合、内合都是与生人外人乱搞","外合只与熟人搞；内合与生人外人乱搞","外合与生人外人乱搞；内合只与熟人搞"],"ans":3,"exp":"「女命淫，只因桃花绊禄」：桃花外合会与生人、外人乱搞；桃花内合只与熟人搞。","sec":"女命","t":"diff"},{"q":"多婚命有几个起坏作用的字，婚姻次序怎么排？","opts":["从年上往时上排，看第几个稳定","按生成数大小排","从日支起向两边排","从时上往年上排，看第几个稳定"],"ans":0,"exp":"多婚的次序是从年上往时上排，看到第几个才能稳定住。","sec":"三、几次婚姻","t":"step"},{"q":"夫妻宫双现（如子、寅），但夫妻星只有一个，怎么断？","opts":["主夫妻星被分夺，婚姻时刻不稳","不主婚姻不好，主有好几处家","一宫一婚，宫有两现即主婚姻两次","主一婚，但夫妻长期分居两地"],"ans":1,"exp":"夫宫双现不等于多婚：夫妻星只有一个，宫双现表示她有好几处家，老公对她特别好。","sec":"夫宫双现不等于多婚","t":"diff"},{"q":"女命行劫财运，官轻财轻与官重财重各怎么论？","opts":["官轻财轻不怕劫；官重财重必离婚","两种都不怕劫，劫一点才好","官轻财轻劫财星必离；官重财重不怕","两种都必离，劫财运一到即离"],"ans":2,"exp":"女命关财门：财是官的原神，官轻财轻行劫财运，劫了财星肯定离婚；官重财重不怕劫，劫一点才好。","sec":"女命关财门","t":"diff"},{"q":"配偶宫、星偏重杂出为重患必离，若又重见伏吟，如何论？","opts":["患更重，必离无疑","主再婚，婚姻稳定","主丧偶，不主离婚","转为轻患，可能离或婚前不顺、婚后分居"],"ans":3,"exp":"重见伏吟为轻患：可能会离，也可能婚前不顺或婚后分居。","sec":"患夫、患妻","t":"rule"},{"q":"去用结构中，下列哪个日柱是主位连根，不能被去？","opts":["壬申","丁亥","庚午","甲子"],"ans":0,"exp":"主位的、连根的不能去，去了人就短寿：壬申、乙亥、乙卯、甲寅之类；甲子无根，庚午、丁亥坐下不是自己的根。","sec":"通根、通源与流绝","t":"calc"},{"q":"日主之禄看寿，哪种说法对？","opts":["日柱之前的大限一见禄便是寿到","晚年见禄，运岁再见才寿到","晚年时柱见禄大吉，运岁再见更吉","时柱见禄即寿到，不论运岁如何"],"ans":1,"exp":"日柱之前的大限见禄不为寿到；晚年、时柱见禄，怕运岁再见禄；晚年见禄最怕被冲刑破穿入墓。","sec":"寿元星与禄","t":"rule"}]},{"n":19,"level":"初级","title":"补充答疑与零散断法","qs":[{"q":"日主之禄在日支（坐下）与在时上，被刑冲破穿制时后果有何不同？","opts":["两处之禄都不可坏，坏了都要损寿折福","坐下之禄可坏，时上之禄不可坏，坏则损寿","两处之禄都可坏，只是身体变差而已","坐下之禄不可坏，坏则损寿；时上之禄可坏，只伤身"],"ans":3,"exp":"日支之禄是日主的根，坏了伤寿；时上之禄坏了只是身体差，不至损寿。","sec":"一、禄的处置","t":"diff"},{"q":"年、月上的禄被制、被冲，对日主有没有影响？","opts":["无妨，年月之禄不代表日主自己","无妨，但须大运合来才解","有影响，年月禄坏主早年伤父母","有影响，禄在哪柱都是日主之根"],"ans":0,"exp":"禄在日、时才是日主自己；年、月上的禄被制被冲无妨。","sec":"一、禄的处置","t":"rule"},{"q":"时上有禄，要成「单禄」可坏，前面不能再有什么？","opts":["不能再有食伤泄日主","不能再有生日主的印或比劫","不能再有官杀克日主","不能再有财星合日主"],"ans":1,"exp":"时上禄是孤单的东西，前面再有生身之印或比劫就不是单禄，不可坏。","sec":"一、禄的处置","t":"rule"},{"q":"日主合年月上的官，与合时上的官，含义有何不同？","opts":["合年月官是被人管理；合时上官是管理控制","两者都是日主管理，只是官大官小不同","合年月官是管理控制；合时上官是被人管理","两者都是日主被管，只是远近不同"],"ans":2,"exp":"合年月官，日主管理这个官所代表的东西；合时上官，日主被别人管。","sec":"二、日主合官：年月管人，时上被管","t":"diff"},{"q":"日主合时上的官，官坐下的时支能不能被坏？","opts":["可以坏，只合官就够了","不能坏，但需要被合住","可以坏，坏了官才出来","不能坏，要用时支去制别的支"],"ans":3,"exp":"合到时上才有用，用的就是时支；合官必用时支，所以支不能坏。","sec":"二、日主合官：年月管人，时上被管","t":"rule"},{"q":"原局有破，大运或流年再来一个破（或其他作用），能不能解命中的破？","opts":["解不了，破只有坏处，运中破解不了命中破","能解，但须合来才解","解不了，但命中的破可转成做功","能解，以破解破"],"ans":0,"exp":"破不叫做功，只表象；暗合才是做功。运中来的破不能解命中的破。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"原局有穿，遇到合能不能化解？","opts":["能，但只限暗合","不能，合解不了穿","能，合能解一切穿","能，但只限六合"],"ans":1,"exp":"合解不了穿，穿什么也解不了，不能指望遇合来化解。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"日主与日支自合的地支，还能不能去制别的字？","opts":["不能，自合只主表象","不能，自合则地支被合住不起作用","能，自合并不妨碍它去制别的字","能，但只能制主位的字"],"ans":2,"exp":"日主与日支自合的地支能制，自合不妨碍其做功。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"夫妻宫被穿，哪一类对婚姻伤害更重？","opts":["申亥、寅巳这类生穿","生穿与克穿一样重","生穿更重，因为生而反穿","子未、卯辰这类克穿"],"ans":3,"exp":"夫妻宫生穿不要紧，克穿才厉害。","sec":"三、破、穿、自合的几条答疑","t":"diff"},{"q":"原局食神、官星落空亡，大运流年逢到所落之字，称什么？","opts":["填空，本派承认这一说","冲空，本派承认这一说","解空，运岁一合即解","补空，但本派不承认"],"ans":0,"exp":"空亡可由运、岁填空；食神落空亡短寿也有前提。","sec":"四、空亡、泄用与几条虚实补注","t":"rule"},{"q":"食神落空亡短寿，成立的前提是什么？","opts":["食神坐在时柱","水没有流绝","水旺而有根","食神被官杀所制"],"ans":1,"exp":"水有源头、流到时上归库（不流绝）的，食神落空亡也不短寿。","sec":"四、空亡、泄用与几条虚实补注","t":"rule"},{"q":"看学历的有无与高低，先看什么，再看什么？","opts":["先看印星，再看财星","先看食伤，再看印星","先看官星，再看印星","先看印星，再看官星"],"ans":2,"exp":"官星虚透看学历，先官星后印星。","sec":"四、空亡、泄用与几条虚实补注","t":"step"}]},{"n":46,"level":"中级","title":"天道、阴阳、五行、体用","qs":[{"q":"按盲派，阴阳是相对概念还是绝对概念？","opts":["相对：只有成对出现才有阴阳","相对：随比较对象而定阴阳","绝对：阳就是阳，阴就是阴","绝对：但阴阳可随大运互相换位"],"ans":2,"exp":"阴阳不是相对的矛盾统一，而是确定属性：热升动左男横为阳，寒降静右女竖为阴。","sec":"二、阴阳：天地之道","t":"rule"},{"q":"阴阳属性里，横与竖、动物与植物各属阴还是阳？","opts":["横属阳、植物属阳","横、动物属阴；竖、植物属阳","竖属阳、动物属阴","横、动物属阳；竖、植物属阴"],"ans":3,"exp":"动物横行、五官能动者横长属阳；植物竖长、耳鼻竖长不动属阴。","sec":"二、阴阳：天地之道","t":"diff"},{"q":"干支把阴阳符号化后，阴极与阳极分别落在哪两个支？","opts":["阳极为午，阴极为子","阳极为子，阴极为午","阳极为巳，阴极为亥","阳极为寅，阴极为申"],"ans":0,"exp":"阳到极点是午（夏至），阴到极点是子（冬至）；子午是阴阳的符号。","sec":"二、阴阳：天地之道","t":"rule"},{"q":"五行里土的位置与作用，按盲派怎么讲？","opts":["独占一季，与其他四行并列","寄于四季最后一月，承载四行，居中为中气","旺于冬季，主藏物","旺于夏季，主热长万物"],"ans":1,"exp":"土代表地球本身，寄于每季季月，秉四季余气，承载其他四行。","sec":"三、五行：阴阳的五种力量","t":"rule"},{"q":"「克」的来源，盲派怎么解释金克木、水克火？","opts":["五行相邻，一方吞噬另一方","按五季顺序，前一季克后一季","阴阳之克：秋杀克春生，寒克热","按五行物质性质，金能砍木、水能灭火"],"ans":2,"exp":"生来自五季时序接续，克来自阴阳之克；四极之克加土后成隔位之克。","sec":"四、五行生克","t":"rule"},{"q":"木无金克与木生火太过，各自的弊病是什么？","opts":["木无金克会枯死；木生火太旺则成灾","木无金克无法生火；木生火太旺则水干","木无金克不成栋梁；木生火太旺则土焦","木无金克不成栋梁；木生火太旺则灰飞烟灭"],"ans":3,"exp":"只克不生与只生不克都有害：木需金克成材；火过旺则木灰飞烟灭。","sec":"四、五行生克","t":"diff"},{"q":"五行里哪几行属形，哪几行属气？","opts":["金木土为形，水火为气","金木水为形，火土为气","金土火为形，木水为气","木火为形，金水为气"],"ans":0,"exp":"形是实的、气是虚的：金木有形可拿，土归形，水火无形为气。","sec":"五、形与气","t":"diff"},{"q":"形与气转化，哪些组合算形化气、哪些算气化形？","opts":["土生金、金生水为形化气；水生木、木生火为气化形","金生水、木生火为形化气；水生木、火生土为气化形","木生火、火生土为形化气；金生水、水生木为气化形","金生水、水生木为形化气；木生火、火生土为气化形"],"ans":1,"exp":"金木为形，水火为气；形化气＝金生水、木生火；气化形＝水生木、火生土；土生金是形化形。","sec":"五、形与气","t":"rule"},{"q":"形化气、气化形、形化形中，按盲派哪种没有贵重之象？","opts":["金生水（形化气），没有形，不显贵重","水生木（气化形），没有形，不显贵重","土生金（形化形），没有气，不显贵重","木生火（形化气），没有形，不显贵重"],"ans":2,"exp":"只有形化气的组合才显其贵重；形化形（土生金）没有气。","sec":"五、形与气","t":"rule"},{"q":"按盲派体阴用阳，癸水日主与甲木日主，谁贵者更多、原因何在？","opts":["甲木贵者多：至阳，可用之字多","癸水贵者多：至阴，不喜之字多","两者一样多，贵贱与阴阳无关","癸水贵者多：至阴，可用之字多"],"ans":3,"exp":"十干以甲为贵、癸为贱，但癸至阴可用甲、可用戊，成格易；甲至阳可用之字少，难成贵格。","sec":"六、体与用","t":"calc"},{"q":"体与用三种关系中，「体静用动」的例子是哪一组？","opts":["身体是体，拳是用","天有四季，人用三季","菜刀可切菜也可作凶器","老子之阴为体，孔子之阳为用"],"ans":0,"exp":"体静，用动才显：身体为体、拳为用，眼为体、视为用；菜刀是体无定用，天四季人用三是体全用缺。","sec":"六、体与用","t":"diff"},{"q":"命理里干支怎样才能「取出象」、看出它的用？","opts":["查本字的五行属性就够了","干支在命局中动了、与别支发生关系","干支在命局中静止不动、保持本体","干支出现在日柱上就能取象"],"ans":1,"exp":"体没有用是无意义的，干支动了才从变化中知道它的用，象就是这样取出来的。","sec":"六、体与用","t":"rule"}]},{"n":47,"level":"中级","title":"十神与宫位","qs":[{"q":"按盲派，为什么取日主旺衰没有意义？","opts":["日干衰旺随大运变化，难以定论","日干是用，旺衰要看月令根气","日干旺衰只表身体，不表能力","日干是体，十为体、只用其九"],"ans":3,"exp":"日干代表「我」，是体不用；把体放到用的位置是没理解命理本质，日主旺衰也不代表能力、身体。","sec":"一、十干之位","t":"rule"},{"q":"乙庚合与丁壬合，哪一方沾光、为什么？","opts":["乙、丁沾光，阴合阳是上升","庚、壬沾光，位低合位高上升","庚、壬沾光，阳合阴是上升","乙、丁沾光，位高者必占便宜"],"ans":0,"exp":"阴喜合阳则上升层次，阳合阴则降低层次；辨合得好不好既看位次也看阴阳。","sec":"二、十干之性","t":"diff"},{"q":"丁壬合、戊癸合，各自常见的类象是什么？","opts":["丁壬多启蒙演说；戊癸多金融理财","丁壬多写作文章；戊癸多启蒙演说","丁壬多金融理财；戊癸多写作文章","丁壬多戴帽子；戊癸多镀镜光亮"],"ans":1,"exp":"丁壬是笔墨之合，多有写作文章之象；戊癸是化彩之合，多为启蒙、演说之象。乙庚才多类象金融。","sec":"三、天干五合","t":"xiang"},{"q":"日主为乙，天干见庚，按盲派这个庚是什么关系？","opts":["正官，必克日主","七杀，必克日主","正官，必与日主相合","七杀，必与日主相合"],"ans":2,"exp":"阴日主正官必合身（乙见庚，必乙庚相合）；阳日主正财必合身（甲见己）。","sec":"四、十神释义","t":"calc"},{"q":"日主为甲，地支见子、亥、午、巳，依次标注十神，哪组正确？","opts":["枭、印、食、伤","印、枭、食、伤","枭、印、伤、食","印、枭、伤、食"],"ans":3,"exp":"地支先取本气：子阴水为印，亥阳水为枭，午阴火为伤，巳阳火为食。同性为偏、异性为正，我生同性为食、异性为伤。","sec":"四、十神释义","t":"calc"},{"q":"伤官合杀、伤官合印、食神合印、食神合官，按盲派哪个多数不喜？","opts":["食神合官","伤官合杀","伤官合印","食神合印"],"ans":0,"exp":"食神是体，合官是自己合到麻烦、引鬼上身；伤官是用、是工具，合杀吉。","sec":"六、配与十神的六亲","t":"rule"},{"q":"按盲派，阳官与阴官、阴杀与阳杀，作用有什么不同？","opts":["阴官阳官都克身，只是力度不同","阳官合身主约束；阴官克身有害无益","阴杀合身不克害；阳杀克身主杀伐","阳官克身主约束；阴官合身有害无益"],"ans":1,"exp":"官杀分阴阳：阳官合身主约束，阴官克身有害无益；阴杀克害，阳杀不克害。","sec":"五、十神的社会学内涵","t":"diff"},{"q":"按盲派，男命和女命各以什么十神看子女？","opts":["女命看官杀；男命看伤食","男女都看伤食，官杀为辅","女命看伤食；男命看官杀","女命看印；男命看财"],"ans":2,"exp":"女命以伤官食神为子女，男命以官杀为子女；不论男女，财星也可代表孩子。","sec":"六、配与十神的六亲","t":"rule"},{"q":"按盲派，母亲、父亲分别取哪个十神？","opts":["母取正印；父取偏财","母取食神；父取正印","母取正印；父取财星","母取食神；父取财星"],"ans":3,"exp":"母亲取食神（养育给予），父亲取财星（养命之源）；印的本意是保护，不称父母。","sec":"六、配与十神的六亲","t":"rule"},{"q":"按盲派，正财一定代表正妻、偏财一定代表妾吗？","opts":["不一定，正妻要看夫妻宫","要看财星是否合日主而定","一定，正偏分妻妾","男命如此，女命不论"],"ans":0,"exp":"并非正财是正妻、偏财是妾，正妻要看夫妻宫；财星落在比肩劫财下，再怎么讲都是别人的老婆。","sec":"六、配与十神的六亲","t":"diff"},{"q":"按盲派，里外与宾主的划分是什么？","opts":["年时为里、月日为外；年月为宾、日时为主","月日为里、年时为外；年月为宾、日时为主","年月为里、日时为外；年日为宾、月时为主","月日为里、年时为外；日月为宾、年时为主"],"ans":1,"exp":"年月一家为宾，日时一家为主；月日为里，年时为外，外边包里边。","sec":"七、四柱宫位","t":"rule"},{"q":"为什么配偶宫坏必离婚，而子女宫坏不一定克子女？","opts":["配偶宫为日主根，孩子宫离日主远","配偶宫看十神，子女宫只看星","配偶不回家不成婚，孩子远走正常","配偶宫为里，子女宫为外不影响"],"ans":2,"exp":"配偶不回家就不算婚姻；孩子不回家很正常。所以子女宫坏多看孩子远离，宫与星俱坏才克子女。","sec":"七、四柱宫位","t":"rule"}]},{"n":48,"level":"中级","title":"十天干象义","qs":[{"q":"按盲派，十天干里阴日干共同怕见什么、最喜见什么？","opts":["怕七杀，喜见甲","怕伤官，喜见丙","怕偏印，喜见甲","怕七杀，喜见庚"],"ans":0,"exp":"阴日干多怕七杀，几乎都喜见甲，其中最喜甲的是癸。","sec":"通用要点","t":"rule"},{"q":"甲、丙、戊、庚、壬这些阳干，更宜占体还是占用？","opts":["只有逢旺地才宜占用","宜占用，占体不一定好","宜占体，占用易受克","体用皆宜，阴阳无别"],"ans":1,"exp":"阳干高贵而用处少，占体不一定好，宜占用；阴干卑而可用之字多。","sec":"通用要点","t":"diff"},{"q":"甲日见辛与乙日见辛，处理上有何不同？","opts":["两者都可以用丙去合住辛","甲可用丙合辛，乙没有办法","乙可丙合丁制，甲没办法","两者都可以用丁来克制辛"],"ans":2,"exp":"丙是甲之体不可制，丁制则生争斗；乙见辛可用丙合之、丁制之保全。","sec":"二、乙","t":"diff"},{"q":"甲日见己合，一般怎么看？","opts":["合土化象，甲木转旺有力","合则财来就我，主大吉","合后甲得己土所生，主贵","贪恋己财而失贵性，不喜"],"ans":3,"exp":"甲己合是甲贪恋己之财色、失其贵性，合象低头，一般不喜合己。","sec":"一、甲","t":"rule"},{"q":"丙日见下列哪个时柱的丙，属于“丙不落地”、反易成贵格？","opts":["丙申","丙戌","丙寅","丙午"],"ans":0,"exp":"丙子、丙申、丙辰是丙不落地，代表天上之日，不落地反易成贵格。","sec":"三、丙","t":"calc"},{"q":"丙日见甲木，数量上怎么论吉凶？","opts":["越多越旺，三个最贵","一个最好，两个坏格，三个破格","一个破格，两个最好","两个最好，一个太弱"],"ans":1,"exp":"甲生助丙，但多则森林蔽日：一个最好，两个坏格，三个破格。","sec":"三、丙","t":"rule"},{"q":"丙和丁在天干中数量上的喜忌有何不同？","opts":["丙丁都是越多越好","丙丁都是一个最好","丙一个就好，丁多反喜","丙多反喜，丁一个就好"],"ans":2,"exp":"丙为太阳一个就好；丁为星星，星罗棋布，多则反喜，丁多为吉。","sec":"四、丁","t":"diff"},{"q":"丁日见甲、见乙，各怎么论？","opts":["甲乙两者都忌见","甲乙两者都喜见","甲最恨，乙极喜","甲极喜，乙最恨"],"ans":3,"exp":"甲高贵为阳，生丁无条件，是丁最大的贵人；乙仅因是阴就成仇人，丁见乙总有不好的事。","sec":"四、丁","t":"rule"},{"q":"戊土独透天干，职业上常见什么象？","opts":["容易当老师","容易做会计","容易从军","容易经商"],"ans":0,"exp":"戊为高台、讲台，一阳统全阴，别人听他讲看他演；戊土独透者容易当老师。","sec":"五、戊","t":"xiang"},{"q":"戊日见庚（食神）时，要注意哪一点？","opts":["食神与比肩同见则夺食","食神与偏印不可同见，枭神夺食","食神最忌与官星同见","食神必须见财才有用"],"ans":1,"exp":"戊日见庚是食神，喜，但食神与偏印不可同见（枭神夺食）；最怕官星乙来合。","sec":"五、戊","t":"rule"},{"q":"庚日见丙、见丁，各怎么论？","opts":["怕丙煅炼，喜丁点化","丙丁都喜，火越旺越好","极喜丙煅炼，怕见丁","丙丁都怕，只喜水来柔化"],"ans":2,"exp":"庚日极喜丙煅炼成器；丁像气割枪打洞使铁板作废，不喜见丁。","sec":"七、庚","t":"rule"},{"q":"癸见壬，与壬见癸，为什么不同？","opts":["壬见癸得助，癸见壬被克","癸见壬被夺，壬见癸被生","两者都是同类相并，皆吉","癸并入大河放大，壬见癸变小"],"ans":3,"exp":"水可混而并流，小溪并大河放大自己，所以癸特喜壬劫透干；壬见癸则大变小，不喜。","sec":"十、癸","t":"diff"}]},{"n":49,"level":"中级","title":"干支关系与五行生死","qs":[{"q":"按盲派，天干与地支发生克的关系时，一般怎么论？","opts":["天干地支都不能互克，只看合冲","天干能克地支，地支不能克天干","地支力重，地支能克天干","天干地支互克，谁强谁胜"],"ans":1,"exp":"位比气重要，天干如君如夫，地支如臣如妻，只有上下相合的少数几柱才例外。","sec":"一、干支关系","t":"rule"},{"q":"盲派论五行强弱，用的是哪组概念？","opts":["日主得月令为旺、失令为衰","天干通根多为强、通根少为弱","天干得地气为实、不得为虚","地支藏干多为实、藏干少为虚"],"ans":2,"exp":"本派只讲虚实不讲衰旺：天干能得地气者为实，不得者为虚，如甲寅乙卯为实，甲申乙酉为虚。","sec":"一、干支关系","t":"diff"},{"q":"干支一体的柱子，代表人时有什么要求？","opts":["一体者必比异体好，不必顾忌","可被合化，合化后更有力","必须被冲动，才能显出灵动","不可被坏，坏则不利身体"],"ans":3,"exp":"一体如整体的人，坏了就伤身；所以一体不一定比异体好，日主天干不落地的命没有这层担忧。","sec":"一、干支关系","t":"rule"},{"q":"丙寅、壬申、甲辰、丙午四柱，哪一柱属于「地支生天干，且地支中又藏旺气天干」这类干支一体？","opts":["丙寅","丙午","甲辰","三柱皆是"],"ans":0,"exp":"丙寅（寅生丙，寅中藏丙）与壬申属此类；丙午属通禄一体，甲辰属有克而成整体。题中丙寅是唯一属此类的一柱。","sec":"一、干支关系","t":"calc"},{"q":"金的绝地和水的死地分别是哪个地支？","opts":["金绝于申，水死于子","金绝于寅，水死于卯","金绝于卯，水死于寅","金绝于子，水死于申"],"ans":1,"exp":"寅申巳亥为绝地：火生寅则寅是金绝地；子午卯酉为死地：水旺子，死于卯。","sec":"二、五行生死","t":"calc"},{"q":"「气怕死，形怕绝」中，哪两种五行是「气」、怕什么？","opts":["金木为气，怕死","金木为气，怕绝","水火为气，怕死","水火为气，怕绝"],"ans":2,"exp":"水火为气，怕死（火怕酉、水怕卯）；金木为形，怕绝（金绝寅、木绝申）。","sec":"二、五行生死","t":"rule"},{"q":"庚子、甲午两柱本是金木「死」地，按盲派怎么论？","opts":["形怕绝，死地等于绝地，主凶","金木被死地所克，主凶","金木死而无根，必须有救方吉","形化气、形归气，不主凶反主吉"],"ans":3,"exp":"形不怕死，只有气怕死；死是生气消失而形还在，所以庚子、甲午不凶反吉。","sec":"二、五行生死","t":"calc"},{"q":"水火遇绝地和金木遇绝地，按盲派区别在哪？","opts":["水火气绝有情，既济；金木形绝无情，交战","水火绝则亡，金木绝则可用","水火金木遇绝都一样，都主死亡","水火绝无情相克，金木绝有情相生"],"ans":0,"exp":"水火为气，绝而交融（水火既济），不怕绝；金木为形，绝则无情交战。","sec":"二、五行生死","t":"diff"},{"q":"辰戌与丑未，哪个说法符合盲派？","opts":["辰戌为形墓必须开，丑未为气库不必开","辰戌为气库不必开，丑未为形墓必须开","四库都必须冲开才能用","四库都不必开，入墓即可用"],"ans":1,"exp":"辰戌是水火之库，气主动如阳宅，不开也能用；丑未是金木之墓，形主静如阴宅，用必须开。","sec":"二、五行生死","t":"diff"},{"q":"盲派说地上土和天上土的墓，分别在哪？","opts":["天土墓于未，地土墓于丑","天土墓于辰，地土墓于戌","天土墓于戌，地土墓于辰","天土墓于丑，地土墓于未"],"ans":2,"exp":"天上土同火长生于寅，墓于戌；地上土同水长生于申，墓于辰。戌为天门，辰为地户。","sec":"三、土的生死","t":"rule"},{"q":"十二地支中，辰在哪个字面前最容易被制？","opts":["丑","戌","卯","子"],"ans":3,"exp":"辰是地户，几乎无所畏惧，只有戌能对抗；但子见辰能消解之，小能克大。题目问的是「最怕」，是子。","sec":"三、土的生死","t":"diff"},{"q":"四帝旺（子午卯酉）的地支性格，哪条正确？","opts":["气专，爱钻牛角、固执不通融","气专，圆滑随和、善于变通","气聚，沉着有谋、能聚财","气散，宽容大度、交往多"],"ans":0,"exp":"子午卯酉气专，贪荣忘生，专一固执不讲情面，中医主枢；寅申巳亥气散主开，辰戌丑未气聚主合。","sec":"四、地支三类性格","t":"xiang"}]},{"n":50,"level":"中级","title":"地支作用","qs":[{"q":"子午卯酉四帝旺支，藏干情况是怎样的？","opts":["只有子藏两气，其余各藏一气","四支各只藏一气，没有例外","只有午藏两气，其余各藏一气","子午卯酉各藏两气"],"ans":2,"exp":"帝旺支藏气俱阴、只藏本气旺气；因火土同生同旺，午也是土的旺气点，所以只有午藏丁己两气。","sec":"一、地支遁藏与刃","t":"rule"},{"q":"下列四个日柱，哪一个是「自坐刃」？","opts":["辛酉","乙卯","甲寅","壬子"],"ans":3,"exp":"只有阳日干有刃，水火错配所以壬子、丙午自坐刃；甲寅是坐禄不是刃，乙卯、辛酉是阴干，无刃。","sec":"一、地支遁藏与刃","t":"calc"},{"q":"天干没有别的辛，只有一个辛丑日柱，辛按盲派怎么论？","opts":["本坐库不为入墓，不论入墓","辛入丑墓，须看大运","辛入丑墓，凶小","辛入丑墓，凶大"],"ans":0,"exp":"辛丑、壬辰是坐墓，不为入墓；天干多辛相连通于辛丑，才是多而墓之。","sec":"二、墓库的入与出","t":"calc"},{"q":"下列六合组合中，哪一组属于克合？","opts":["寅亥","卯戌","辰酉","午未"],"ans":1,"exp":"寅亥、辰酉、午未是生合；克合是卯戌、巳申、子丑，其中卯戌合卯控制戌，可做功。","sec":"三、地支之合","t":"diff"},{"q":"盲派所讲的三个暗合是哪三个？","opts":["子亥、卯申、寅丑","午亥、卯戌、寅丑","午亥、卯申、寅丑","午未、卯申、寅亥"],"ans":2,"exp":"暗合是午亥、卯申、寅丑：午中丁己合亥中壬甲，寅中甲丙合丑中己辛，卯中乙合申中庚（合绝）。","sec":"三、地支之合","t":"rule"},{"q":"寅申相冲与子午相冲，结果的性质有何不同？","opts":["寅申木必胜金；子午水火强者胜","两者都是强者胜，没有区别","寅申强者胜；子午水必胜火","寅申金必胜木；子午水火强者胜"],"ans":3,"exp":"金木相冲是形争，一旦相冲一定金胜木；水火相冲是气的相冲、水火既济，一方强另一方败。","sec":"四、地支六冲","t":"diff"},{"q":"冲会让字动起来，动对体和用分别如何？","opts":["体不喜多动，用喜动","体用都不喜动","体喜动，用不喜动","体用都喜动"],"ans":0,"exp":"体不喜多动，动则劳碌辛苦；用喜动，动则功成名就。所以体不可克，用冲克无妨。","sec":"四、地支六冲","t":"rule"},{"q":"六穿里哪一个力量最大、哪一个力量最小？","opts":["卯辰最大，酉戌最小","寅巳最大，申亥最小","子未最大，丑午最小","申亥最大，寅巳最小"],"ans":1,"exp":"阳穿阳力大、阴穿阴力小：寅巳两阳相穿拼出你死我活，申亥是冷暴力、最弱。","sec":"五、地支六穿","t":"diff"},{"q":"原局已有寅、巳两字，第三个字申分别由大运和流年带来，怎么论三刑？","opts":["大运来申只是引动，流年来申构成三刑","大运、流年来申都构成三刑","大运来申构成三刑，流年来申只是引动","大运、流年来申都不成三刑"],"ans":2,"exp":"寅巳申三者须同时出现才构成刑；原局两个，大运来第三个也构成三刑，流年来第三个只是引动。","sec":"七、地支刑与破","t":"calc"},{"q":"丑戌刑与未戌刑，能否做功？","opts":["未戌刑能做功，丑戌刑只开库","两者都能做功","两者都不能做功，只开库","丑戌刑能做功，未戌刑只开库"],"ans":3,"exp":"丑戌刑一阴一阳，力大者能坏另一方，可做功；未戌刑不以做功论，只是开库。","sec":"七、地支刑与破","t":"diff"},{"q":"三种破的力量大小，从大到小依次是？","opts":["卯午破、子卯破、子酉破","卯午破、子酉破、子卯破","子酉破、子卯破、卯午破","子卯破、卯午破、子酉破"],"ans":0,"exp":"卯午俱阳，阳见阳破得最凶；子卯其次；子酉阴见阴称相隔，几乎不破，意同申亥穿。","sec":"七、地支刑与破","t":"step"},{"q":"入阳墓与入阴墓，以及阳墓阴墓开不开，怎么区别？","opts":["入阳墓凶大；阴墓不开也可用，阳墓必须开","入阴墓凶大；阳墓不开也可用，阴墓必须开","入阴墓凶大；阳墓阴墓都必须开","入阳墓凶大；阳墓阴墓都不开也可用"],"ans":1,"exp":"辰戌阳墓为气墓、丑未阴墓为形墓；入阳墓如住院，入阴墓可能人就没了，阴墓一定要开。","sec":"八、地支之墓：入、出与开库","t":"diff"}]},{"n":51,"level":"中级","title":"十二地支象义","qs":[{"q":"下列哪一组象属于丑？","opts":["堤坝、港口、化工","高堂、门楼、舞台","镜子、珠宝、寺院","牢狱、下水道、坟墓"],"ans":3,"exp":"丑是阴中之至阴，主黑暗隐蔽：牢狱、地下室、下水道、坟墓；镜子珠宝寺院是酉，堤坝港口化工是辰，高堂门楼是寅。","sec":"二、丑","t":"xiang"},{"q":"寅亥相合，身上易出现什么毛病？","opts":["风湿痰气类的病","肺咳喘类的病","肾结石类的病","心脏类的病"],"ans":0,"exp":"寅主风、亥主湿，亥水灭寅中之阳，湿性粘腻侵入人体要害，风湿病就是这么得的。","sec":"三、寅","t":"diff"},{"q":"卯辰相穿，对两字各是什么结果？","opts":["两字都受损，穿则双坏","利辰不利卯，损卯而成就辰","利卯不利辰，损辰而成就卯","两字都得利，穿则双成"],"ans":1,"exp":"辰是堤坝，卯是加固坝基的木桩，一根根穿进去坝才坚固：是辰好了，卯是被穿坏的。","sec":"四、卯","t":"rule"},{"q":"卯酉相冲，谁受伤？","opts":["强者胜，要看哪边有党","卯胜酉，酉受伤，酉不能为体","酉胜卯，卯受伤，卯不能为体","双方同伤，体用都无碍"],"ans":2,"exp":"金木交战必定酉胜卯，卯受伤；体被酉冲肢体必受伤，所以卯不能为体。","sec":"四、卯","t":"diff"},{"q":"十二支中，辰最怕哪两个字？","opts":["丑和未","戌和卯","酉和子","戌和子"],"ans":3,"exp":"辰怕戌冲（堤坝崩塌）、怕子（化掉消解如坚冰融化）；卯穿辰反使辰更坚，辰喜卯穿。","sec":"五、辰","t":"rule"},{"q":"巳与酉半合、巳与申相合，巳的火性各怎样？","opts":["巳酉合从金而化，巳申合火性不变","巳酉合、巳申合火性都不变","巳酉合、巳申合都从金而化","巳酉合火性不变，巳申合从金而化"],"ans":0,"exp":"巳善变，见酉丑从金而化、不再显火性；巳申相合时巳火不会变其火性。","sec":"六、巳","t":"diff"},{"q":"午亥暗合，多数表现为哪种特点？","opts":["心脏有疾，身体易伤","智商高，数理能力强","文笔好，善写文章","喜热闹，爱出入夜场"],"ans":1,"exp":"午亥是水火之合，火喜得水而既济，多数合而吉且见功，午亥之合多数智商奇高、数理能力强。","sec":"七、午","t":"xiang"},{"q":"未与辰相见，同时再见哪个字，未就不入辰墓？","opts":["卯或寅","午或戌","子或丑","酉或亥"],"ans":2,"exp":"单见未入辰墓；一见子或丑，未就不可入辰墓，辰只收丑或拱子。","sec":"八、未","t":"calc"},{"q":"申的类象中，哪类机构是只收不放？","opts":["银行、典当行","钟鼓楼、音乐厅","酒店、饮食业","税务、公安等执法处罚机关"],"ans":3,"exp":"银行是收了再放，取象寅申冲、卯申合；只收不放的是税务、公安一切执法处罚机关。","sec":"九、申","t":"diff"},{"q":"酉被戌穿，酉当用神时，常见哪两种可能？","opts":["动枪弹的职业，或运动员","艺人，或美容师","医生，或会计","教师，或律师"],"ans":0,"exp":"酉被戌穿时酉不可为体；酉当用被穿，可能是动枪弹的职业，或是运动员（速度与激情）。","sec":"十、酉","t":"rule"},{"q":"申酉戌与诉讼，哪个字最像讲道理争讼的地方？","opts":["三者都不讲道理","戌，唯一可吵架争讼","申，执法先收押","酉，律师讲条文"],"ans":1,"exp":"申酉管法律之收，先关起来不讲道理；戌是唯一可以讲道理、吵架、争讼的地方，公检法中唯戌是阳性。","sec":"十一、戌","t":"diff"},{"q":"亥与子同是水，哪个更能灌溉生木？","opts":["子是流动活水，能生木；亥静而不生木","两者生木力量相同","亥是湖泉静水，能生木；子流动，生木差","两者都不生木，只能生金"],"ans":2,"exp":"亥为湖水泉水，安静，能灌溉庄稼而生木；子是流动之水，静不下来，不能生禾木。","sec":"十二、亥","t":"diff"}]},{"n":52,"level":"中级","title":"干支虚实与自合","qs":[{"q":"壬子、戊辰、丙午、己丑四柱中，哪一柱不称干支通禄？","opts":["戊辰","己丑和戊辰都称通禄","壬子","丙午"],"ans":0,"exp":"通禄八柱是甲寅、乙卯、庚申、辛酉、壬子、癸亥、丁巳、丙午；戊辰、戊戌、己丑、己未之土不称通禄。","sec":"一、干支的五类配置","t":"calc"},{"q":"癸酉、丁卯、甲子、庚辰、庚戌、辛未，这六柱按盲派属于哪一类？","opts":["干支通禄，连体不可坏","干支假生，地支可以被坏","干支托根，支坏则干坏","干支相克，称天干虚透"],"ans":1,"exp":"假生六柱看似生实则非真生，地支是可以坏的，有些组合地支被坏才好，如癸酉。","sec":"一、干支的五类配置","t":"calc"},{"q":"戊辰、戊戌、己丑、己未这四柱，对刑冲的态度分别是什么？","opts":["戊辰戊戌刑冲反吉；己丑己未不喜刑冲","四柱都不喜刑冲，冲则库破","戊辰戊戌不喜刑冲；己丑己未刑冲反吉","四柱都喜刑冲，开库见财"],"ans":2,"exp":"戊辰戊戌为阳库不喜刑冲；己丑己未为阴库，须刑冲反吉。","sec":"一、干支的五类配置","t":"rule"},{"q":"按盲派，天干虚透的官杀、财星、印星，分别主什么？","opts":["官杀主名气；财主钱财；印主学历文凭","官杀主权力；财主才气；印主保护靠山","官杀主才气；财主名气；印主放大包装","官杀主名气；财主才气；印主放大包装"],"ans":3,"exp":"财星虚透为才气，官杀虚透为名气，印星虚透为放大、包装、身份、荣誉。","sec":"二、虚实的应用","t":"rule"},{"q":"原局年上有子，时上见癸未，按盲派是哪个干代表子？若子为妻代表什么？","opts":["癸代表子；妻离开了自己","壬代表子；妻生育得子","癸代表子；妻与自己合在一起","壬代表子；妻离开了自己"],"ans":0,"exp":"子水在天干虚是癸代表子，不是壬；若子表示妻子，柱中见癸未，代表妻子跑了离开了。","sec":"二、虚实的应用","t":"calc"},{"q":"原局年上有寅，时上见甲申，属于实化虚的哪一种？","opts":["所藏旺气的虚","本气的实化虚","墓气的虚","干支自合"],"ans":1,"exp":"本气之支在别处以天干形式出现：年上寅，时上甲申，寅虚在时上。丙申才是藏气（旺气）虚。","sec":"二、虚实的应用","t":"calc"},{"q":"原局有未字，又见乙酉柱，按盲派是怎么回事？","opts":["本气虚，未虚在乙酉上","需冲开未库，乙木才能出墓","墓气虚，未中乙木虚而出墓","藏气虚，未中丁火透出"],"ans":2,"exp":"墓气的虚：墓中之气以天干出现，不用冲就能出墓；未中乙木可从墓中出来。","sec":"二、虚实的应用","t":"calc"},{"q":"流年发生实变虚的情况，按盲派应期上怎么看？","opts":["只对妻星有影响，对其余无事","原局无此变化才有大事","必有大事，人离或财散","不会有大事发生；大运逢之才同看"],"ans":3,"exp":"大运同看原局的虚实变化，如乙酉运妻跑；但流年发生实变虚不会有大事。","sec":"二、虚实的应用","t":"rule"},{"q":"六十甲子中，哪两柱是地支克到天干？","opts":["丁亥、辛巳","戊子、壬午","己亥、癸巳","甲申、乙酉"],"ans":0,"exp":"丁亥亥本气壬合丁而克之，辛巳巳本气丙合辛而克之；戊子、壬午、己亥、癸巳仍是天干克地支。","sec":"三、干支自合","t":"rule"},{"q":"己亥、癸巳的支中藏甲、戊能合己、癸，它们是谁克谁？","opts":["天干地支互不相克，只合","仍是天干克地支，本气受克","地支克天干，与丁亥同理","地支克天干，藏干合克"],"ans":1,"exp":"己亥、癸巳看似亥中有甲、巳中有戊，但仍是天干克地支，因地支本气受天干所克；唯丁亥、辛巳是本气合克天干。","sec":"三、干支自合","t":"diff"},{"q":"干支自合柱的婚姻，按盲派为什么多不幸？","opts":["自合之支无力，必被日主所克","合得太紧，夫妻无话可说","理想过高，自合之支不可被合冲刑破","自合是孤阴孤阳，缺少气交"],"ans":2,"exp":"自合者心有完美理想，现实不能实现；自合之支不能被坏，一有风吹草动就离婚，所以离婚率高或单身多。","sec":"三、干支自合","t":"rule"},{"q":"戊子、己亥与壬午、癸巳，自合柱的取象分别是什么？","opts":["戊子己亥如井盖；壬午癸巳投海投火","戊子己亥水火既济；壬午癸巳如井盖","戊子己亥天地反晦；壬午癸巳水火既济","戊子己亥如井盖；壬午癸巳水火既济"],"ans":3,"exp":"戊子、己亥如井盖将水盖在里边；壬午、癸巳阴阳气交，水火既济；丁亥、辛巳则是天地反晦自毁之象。","sec":"三、干支自合","t":"xiang"}]},{"n":53,"level":"中级","title":"正局与反局","qs":[{"q":"按盲派，大运反局的特点是什么？","opts":["凶只应在当年一年","凶只在这步大运，过运则吉","凶在原局，一生不变","凶在大运，过运仍留后患"],"ans":1,"exp":"口诀：反在哪一类，凶在哪一类。原局反局原局凶，大运反局该步大运凶，流年反局该年凶。","sec":"一、基本概念","t":"rule"},{"q":"日主与日支同时做功，两者意思不一致，按盲派怎么论？","opts":["论反局，以日支之功为主","不分正反，看大运定","论反局，以日主之功为主","论正局，取日主之意"],"ans":2,"exp":"日主日支同做功时比较意思，一致为正、不一致为反，但以日主之功为主，不以日支为主。","sec":"二、如何判定原局的正反","t":"rule"},{"q":"日主合年月上的官，与日主合时上的官，意思有何区别？","opts":["两者都是我管人，只是远近不同","两者都是我被管，只是轻重不同","合年月官是我被管；合时官是我管人","合年月官是我管人；合时官是我被管"],"ans":3,"exp":"时柱是主位、主头脑：合时官等于官控制了我的头脑；合年月官是我去管理控制别人，一般不构成问题。","sec":"二、如何判定原局的正反","t":"diff"},{"q":"己丑日、甲戌时（己合时干甲官），丑刑戌，且局中有金水之势。怎么论？","opts":["反局，用的时支戌被日支刑坏","正局，己合甲官是我管人","正局，丑刑戌是制劫财为功","不反，刑戌只是小损"],"ans":0,"exp":"日合时官被官控制，必须用甲坐下的戌（劫财是体），体不可坏；丑刑坏戌即反局。","sec":"二、如何判定原局的正反","t":"calc"},{"q":"己丑日，甲戌在月柱（己合月上甲官），丑刑戌。是否构成反局？","opts":["构成，只要丑刑戌就反","不构成，日合月官是我管人","不构成，但月支戌必须不坏","构成，与甲戌在时柱相同"],"ans":1,"exp":"同一组合，官在月上是我管理控制别人，不要求用戌；官在时上才必须用时支。","sec":"二、如何判定原局的正反","t":"calc"},{"q":"戊土生申，戊申一柱与辛金因戊相连成连体金，这个金是用。此时局中巳申合，怎么论？","opts":["正局，合住申金护住了用神","正局，巳申合是制金为功","反局，连体之用被合坏","不反，只有冲才坏连体"],"ans":2,"exp":"连体不可坏，坏则反局、严重者伤寿；若被制的字与日主不连体（不受生、通根不相连），可制，仍为正局。","sec":"三、连体不可坏","t":"diff"},{"q":"地支依次为巳申未丑，年月巳申合、日时未丑冲，巳未同为火土党、申丑同为金水党。怎么论？","opts":["两党左右排列，不反","两党内外排列，不反","干合支冲，不算反局","两党交叉间隔，冲合反局"],"ans":3,"exp":"巳申未丑按党排成ABAB交叉，一合一冲、两种做法相反，才是冲合反局；内外、左右排列不反。","sec":"四、冲合反局","t":"calc"},{"q":"原局乙庚天干相合，同时丑未地支相冲，算冲合反局吗？","opts":["不算，必须是地支与地支冲合","要看大运有无合冲再定","算，只要日时一方有冲","算，一合一冲做法相反"],"ans":0,"exp":"冲合反局必须地支与地支，干合支冲不算；两党交叉排列才反。","sec":"四、冲合反局","t":"diff"},{"q":"原局靠地支相冲做功，大运地支来合住被冲的字，怎么论？","opts":["天干无合则无妨","冲被合住，岁运冲合反局","合冲相抵，原局不变","合助冲势，更吉"],"ans":1,"exp":"原局冲做功怕岁运来合，合做功怕岁运来冲；如原局申入丑墓冲未，走卯运卯申合则反，走寅运寅申冲仍不反。","sec":"四、冲合反局","t":"rule"},{"q":"原局没有明确的制（冲或合），岁运用相反的方式来破，怎么论？","opts":["照样反局，凶更重","只在大运反局","不怕，不构成反局","只在流年反局"],"ans":2,"exp":"岁运冲合反局的前提是原局有明确的制；原局没有明确的制，则不怕。","sec":"四、冲合反局","t":"rule"},{"q":"流年乙酉「乙到」，原局地支有卯、未、辰，应期先代表哪一个？","opts":["先应辰，再未，最后卯","先应未，再卯，最后辰","先应原局天干，再论地支","先应卯，再未，最后辰"],"ans":3,"exp":"流年应期代表顺序：先地支后天干；地支先本气（卯），再墓气（未），最后余气（辰）。","sec":"五、大运反局","t":"step"}]},{"n":54,"level":"中级","title":"应期","qs":[{"q":"按盲派大限，日柱（日支）管多大年龄段？","opts":["35–50 岁","55 岁以后","35–55 岁","18–35 岁"],"ans":2,"exp":"年柱1–18、月柱18–35、日柱35–55、时柱55岁以后；先用大限定出事的年龄范围。","sec":"一、大限应期","t":"rule"},{"q":"月柱大限（18–35 岁）应凶，此时走的大运是吉运，应期怎么论？","opts":["此运应吉，过运应凶","此运照样应凶，吉运无用","吉运压住凶，永不应凶","此运不应，过运则凶"],"ans":3,"exp":"交脱诀：大限与大运都凶才应凶，一吉一凶互相抵消，事情推到过运才应。","sec":"2. 大限与大运的关系","t":"calc"},{"q":"大限应凶，大运吉，和大限应凶、后面才有吉运，两种情形分别怎么论？","opts":["前者过运才凶，后者未到吉运就先凶","两者都是过运才凶","前者此运不凶永不应，后者先凶","前者此运即凶，后者过运才凶"],"ans":0,"exp":"当运逢吉则此运不应、过运凶；若吉运在后面，则吉运未到之前就已应凶。","sec":"2. 大限与大运的关系","t":"diff"},{"q":"庚、辛、癸三个天干的禄（原身）依次是哪三个地支？","opts":["巳、午、子","申、酉、子","申、酉、亥","酉、申、亥"],"ans":1,"exp":"禄表：庚禄申、辛禄酉、壬禄亥、癸禄子；丙戊禄巳，丁己禄午。","sec":"二、禄与原身应期","t":"calc"},{"q":"局中有戊土，流年出现巳，按禄与原身应期怎么论？","opts":["戊被巳生，只论生不论应","巳为戊的墓，论墓者主收","见禄代表原身，戊的应期到了","巳只是普通地支，与戊无关"],"ans":2,"exp":"丙戊禄在巳，见禄代表原身，这一年要发生与戊有关的事。","sec":"二、禄与原身应期","t":"calc"},{"q":"辰戌丑未四库，在禄与原身应期里怎么论？","opts":["辰为乙的原身","辰戌丑未都是土的禄","丑未为金木的原身","四库没有原身"],"ans":3,"exp":"原身只在寅卯巳午申酉亥子上，辰戌丑未四库没有原身，不能这样取应。","sec":"二、禄与原身应期","t":"rule"},{"q":"原局有戌，大运或流年的天干出现丁，应期怎么论？","opts":["丁代表戌，丁的作用相当于戌","丁入戌墓，论墓者主收","丁生戌，论生不论代","丁只代表丁本身"],"ans":0,"exp":"遁藏透干：地支中有遁藏的天干，流年或大运天干出现这个遁藏之干，就是该地支的应期。","sec":"三、遁藏透干应期","t":"calc"},{"q":"原局有辰，流年天干见乙，乙可代表哪个地支？","opts":["丑","辰","未","卯"],"ans":1,"exp":"辰中遁藏乙、癸，所以乙、癸透干可代辰；寅遁藏丙、甲（戊也行）。","sec":"三、遁藏透干应期","t":"calc"},{"q":"原局本来有合，流年要以什么作用为应？","opts":["穿","合","冲","墓"],"ans":2,"exp":"口诀：原局有合以冲为应，原局有冲以合为应。","sec":"四、岁运作用应期","t":"diff"},{"q":"流年冲大运，怎样分「冲去」和「冲起」？","opts":["旺神为冲起，弱神为冲去","吉运为冲去，凶运为冲起","当运为冲起，不当运为冲去","当运为冲去，不当运为冲起"],"ans":3,"exp":"流年冲大运，看当运不当运：当运为冲去，不当运为冲起。","sec":"四、岁运作用应期","t":"diff"},{"q":"局中本弱的字，被流年旺神来冲，应的是什么？","opts":["冲而破，不是动意","冲而合，必定转吉","冲而动，必应喜事","冲而起，被冲者得力"],"ans":0,"exp":"局中本弱，旺神来冲是冲而破；局中本旺，逢流年冲才是动的应期。","sec":"四、岁运作用应期","t":"diff"},{"q":"走天干大运时，体与用怎么分？","opts":["天干地支都是用","地支为体、天干为用","天干为体、地支为用","天干地支都是体"],"ans":1,"exp":"走天干运，地支为体、天干为用；走地支运，天干为体、地支为用。用＝动态起作用，体＝静态被控制。","sec":"五、大运体用的应期","t":"rule"}]},{"n":55,"level":"中级","title":"干支类象与神煞类象","qs":[{"q":"珠宝、玉器、钻石、乐器，这组类象属于哪个天干？","opts":["己","癸","庚","辛"],"ans":3,"exp":"辛为月、金子、珠宝、玉器、钻石、乐器，形致密；庚是顽铁、铁器、利器、五金，形棱角。","sec":"一、十天干类象","t":"xiang"},{"q":"辛酉日主见丑，与辛丑日主，按盲派有何不同？","opts":["辛酉见丑阴见阴又入墓，是黑社会；辛丑浊中见清不是","两者都不是，丑酉与犯罪无关","两者都是黑社会，丑酉都主犯罪","辛丑见丑阴见阴又入墓，是黑社会；辛酉不是"],"ans":0,"exp":"多数丑酉与犯罪、黑社会有关；辛酉见丑是阴见阴又入墓，辛丑日主则是浊中见清，人性是好的。","sec":"二、十二地支类象","t":"diff"},{"q":"阳木遇火、阴木遇火，各主什么行业象？","opts":["阳木遇火为家具，阴木遇火为冶炼","阳木遇火为家具，阴木遇火为纺织","阳木遇火为纺织，阴木遇火为家具","阳木遇火为冶炼，阴木遇火为家具"],"ans":1,"exp":"甲木分死活，死木遇火为家具；阴木（乙）遇火为纺织、服装。火克金才是冶炼。","sec":"三、六十干支类象","t":"rule"},{"q":"禄神配印与不配印，主什么不同？","opts":["禄配印为辛苦，禄不配印为享受","禄配印不配印都享受","禄配印为享受，禄不配印为辛苦","禄配印不配印都辛苦"],"ans":2,"exp":"禄印相随表享受（偏懒）；禄不配印则要自己亲为做事，主辛苦。","sec":"1. 禄神","t":"diff"},{"q":"女命禄合到什么才算「禄绊桃花」？","opts":["只有合到食神才算，其余都不算","合到印或夫妻宫才算；合到官杀、财不算","合到什么都算桃花，没有例外","合到伤官、官杀或财；合到印或夫妻宫不算"],"ans":3,"exp":"女人的禄合到伤官、官杀、财为禄绊桃花，禄逢三合也是桃花；合到夫妻宫不为桃花，合到印不算桃花。","sec":"1. 禄神","t":"rule"},{"q":"甲、丙、庚、辛日主，哪一个没有羊刃？","opts":["辛","庚","丙","甲"],"ans":0,"exp":"只有阳干有羊刃（甲刃卯、丙刃午、庚刃酉），阴干如辛没有羊刃。","sec":"2. 羊刃","t":"calc"},{"q":"羊刃有制与无制，分别用正还是用偏？","opts":["有制用偏，如匪徒；无制用正，如军警","有制用正，如军警；无制用偏，如匪徒","有制无制都用正，只看刃的强弱","有制无制都用偏，只看刃的强弱"],"ans":1,"exp":"羊刃喜制服：制之得用正，可做军人、警察、执法人员、外科大夫、运动员；无制则用偏，可能是匪徒、赌徒。","sec":"2. 羊刃","t":"rule"},{"q":"墓库按所收藏的十神取象，伤官、食神库是什么象？","opts":["军团、营地","银行","寺庙、学校","权力中心、组织部门"],"ans":2,"exp":"羊刃库为军团营地，伤官食神库为寺庙学校，财库为银行，官杀库为权力中心、组织部门。","sec":"3. 墓库","t":"xiang"},{"q":"日支为卯，盲派的驿马在哪几个字？","opts":["申、子、辰","寅、午、戌","亥、卯、未","巳、酉、丑"],"ans":3,"exp":"盲派驿马：亥卯未见巳酉丑为马；申子辰见寅午戌、寅午戌见申子辰、巳酉丑见亥卯未，以年日为主查。","sec":"4. 驿马","t":"calc"},{"q":"日柱为壬申，按六甲空亡，空的是哪两个字？","opts":["戌、亥","午、未","辰、巳","申、酉"],"ans":0,"exp":"壬申在甲子旬（甲子到癸酉十日），这十天中无戌亥二字，所以戌亥逢空。","sec":"5. 空亡","t":"calc"},{"q":"关于空亡对吉凶的影响，下列哪条对？","opts":["凶星空亡全无凶，吉神空亡福加倍","凶星空亡凶减半，吉神空亡福不全","凶星吉神空亡都不受影响","凶星空亡凶加倍，吉神空亡福更足"],"ans":1,"exp":"空亡是有其气无其形、有其名无其实：凶星空亡凶减半，吉神空亡福不全。","sec":"5. 空亡","t":"rule"}]},{"n":56,"level":"中级","title":"宫位类象与十神类象","qs":[{"q":"按盲派，丈母娘到哪里找？","opts":["年上，与妻宫有关联的印、伤食","日支，与妻宫同柱的印星","月上，与妻宫有关联的财星","时上，与妻宫有关联的官杀"],"ans":0,"exp":"年上表外戚，和妻宫发生关联的印、伤食都是丈母娘；若与妻宫无关，出现伤则可能是奶奶。","sec":"1. 六亲与人物","t":"rule"},{"q":"按盲派，买车、车祸应主要看哪个宫位？","opts":["月支（月柱）","时支（时柱）","年支（年柱）","日支（日柱）"],"ans":1,"exp":"时为门户，出门的代步工具车子在时柱上看，买车、车祸均看时支。","sec":"1. 六亲与人物","t":"rule"},{"q":"天干与地支在表里上各代表什么？","opts":["天干表过去，地支表未来","天干表内心与家人，地支表外在表象","天干表外在表象，地支表内心与家人","天干表家里事，地支表外人交往"],"ans":2,"exp":"天干代表外表、性格表象及与外人交往；地支代表内心世界、与家人关系和隐蔽的心志。","sec":"8. 表里类象","t":"diff"},{"q":"某人命中出现的字落在年柱，按盲派身体类象，最可能对应哪个部位？","opts":["躯干、脊、肩、背","胸部、五脏、心脑","头、面、手、眼、口","腿、足、四肢"],"ans":3,"exp":"年柱离日柱最远，代表腿足四肢；月柱为躯干，日支为五脏心脑，时柱为头面手窍。","sec":"5. 身体类象","t":"calc"},{"q":"按盲派，正偏财分别表示什么？","opts":["表示人对钱财的心性，不是来源正偏","正财是男命妻子，偏财是男命情人","表示钱财的来源是正当还是偏门","正财表工资，偏财表一切横财"],"ans":0,"exp":"正偏财不表示财的来源，而表示人对钱财的心性；来源要看比劫做功与否。","sec":"3. 财","t":"rule"},{"q":"七杀在盲派里怎么区分吉凶？","opts":["见印则吉，见财则凶","有制化显吉的一面，无制化显凶","身旺则吉，身弱则凶","透干则吉，藏支则凶"],"ans":1,"exp":"七杀为凶神，有制化则显吉的一面，无制化则显凶的一面（匪徒、病人）。","sec":"2. 官杀","t":"rule"},{"q":"伤官与食神在情感上有什么区别？","opts":["伤专一用情，食玩乐不专一","伤食都专一，只是强弱有别","伤偏玩乐不专一，食正专一用情","伤食都不专一，只是对象不同"],"ans":2,"exp":"伤偏、食正：伤想象丰富不受约束、感情不专一；食专一专注用情，是付出型。","sec":"5. 食伤","t":"diff"},{"q":"按盲派的基本原则，男命、女命看子女分别怎么取？","opts":["男女都以食伤看子女，伤为儿食为女","男命食为儿伤为女；女命官为儿杀为女","男命官为儿杀为女；女命食为儿伤为女","男命杀为儿官为女；女命伤为儿食为女"],"ans":3,"exp":"基本原则男命以杀为儿、官为女，女命以伤为儿、食为女；通变要看财。","sec":"1. 子女","t":"rule"},{"q":"看儿女时，宫位先后次序怎么排？","opts":["日支、时支、时干、月支……年干","时干、时支、日支、月支……年干","年干、年支、月干、月支……日支","日支、月支、年支，最后看时柱"],"ans":0,"exp":"从日支开始，再时支、时干，再月支、月干，最后年支、年干。","sec":"1. 子女","t":"rule"},{"q":"按盲派，看六亲中的父母，怎样取星？","opts":["印为父，比劫为母","财官杀为父，食伤禄为母","财官杀为母，食伤禄为父","财为母，官杀为父"],"ans":1,"exp":"正偏财为父，官杀也为父；食、伤、禄为母；印是父母星，两个都表示。","sec":"2. 父母","t":"rule"},{"q":"劫财在盲派里怎么论吉凶？","opts":["见印则助，见官则争","身弱则吉，身旺则凶","有功用助我得财，无功用破财","必凶，只会夺财"],"ans":2,"exp":"劫为凶神，有功用可助我得财，无功用反致我破财遭灾。","sec":"4. 比劫","t":"rule"},{"q":"盲派看左右，阴阳怎么对应？","opts":["阳为右，阴为左","天干为左，地支为右","年月为左，日时为右","阳为左，阴为右"],"ans":3,"exp":"阳为左、阴为右；如丙阳比劫在年为腿，表左腿残疾。","sec":"3. 左右","t":"rule"}]},{"n":57,"level":"中级","title":"象的应用","qs":[{"q":"按盲派的共象原则，一个字的象至少要几类象指向同一事物才能确立？","opts":["一类，只看干支象即可","两类，如干支象加宫位象","四类，须含神煞","三类，干支、宫位、十神须齐"],"ans":1,"exp":"只要有两类象表述同一事物，即可确立；如丁在时上，丁象与时宫位都有眼睛。","sec":"二、共象原则","t":"rule"},{"q":"伤官、食神出现在年上与时上，分别多表什么人？","opts":["年上表学生，时上表母亲","年上表小孩，时上表女性长辈","年上表女性长辈，时上表小孩","年时都只表子女"],"ans":2,"exp":"伤食既可表小孩也可表女性长辈：在年上表女性长辈，在时上表小孩。","sec":"二、共象原则","t":"rule"},{"q":"原局相合时互用对方的象：食神合印与伤官合印各表什么？","opts":["两者都表学术，只是强弱不同","食神合印为官位，伤官合印为权力","食神合印为技艺，伤官合印为学术","食神合印为学术，伤官合印为技艺"],"ans":3,"exp":"食神合印＝思想性的学问即学术；伤官合印＝技能、技艺；劫财合财＝劫取而得的财。","sec":"三、合象原则","t":"diff"},{"q":"按盲派，原局的劫财合财，取财手段是什么性质？","opts":["劫取而得，不是合法劳动所得","靠薪水收入稳定而得","靠继承家产而得","靠合作经营平分而得"],"ans":0,"exp":"劫财合财＝劫取而得到的财，取财手段是“劫”。","sec":"三、合象原则","t":"rule"},{"q":"阴木生火、阳木生火、辰配子，化象各是什么？","opts":["阴木生火家具装潢，阳木生火纺织服装，辰配子化工","阴木生火纺织服装，阳木生火家具装潢，辰配子化工","阴木生火纺织服装，阳木生火化工，辰配子家具装潢","阴木生火化工，阳木生火服装，辰配子纺织"],"ans":1,"exp":"阴木生火＝丝线加工物：织物、服装；阳木生火＝家具、装潢；辰配子＝化工、制药、提纯。","sec":"四、化象原则","t":"diff"},{"q":"按盲派墓象原则，墓库的含义怎么定？","opts":["按墓库本身五行定，与所墓之神无关","一律只表钱财仓库、收藏之物","按所墓之神定，如七杀入羊刃墓为军队","按库所在宫位定，与所墓之神无关"],"ans":2,"exp":"墓是收藏控制，含义根据所墓之神确定；七杀入羊刃墓表军队，食伤库表学校、工厂。","sec":"五、墓象原则","t":"rule"},{"q":"“财带官帽”与“官带财帽”各表示什么？","opts":["财带官帽为管财的官，官带财帽为公家之财","两者都表公家之财","两者都表管财的官","财带官帽为公家之财，官带财帽为管财的官"],"ans":3,"exp":"一柱以干统支：财带官帽＝公家之财；官带财帽＝管理财的官，官统财。","sec":"七、带象原则","t":"diff"},{"q":"“印带财帽”按盲派是什么象？","opts":["薪水，上班领工资","经营性的房产","公家之财","权力，掌管实权"],"ans":0,"exp":"印为单位，财来自印中，所以印带财帽＝薪水；印带官帽才是权力。","sec":"七、带象原则","t":"rule"},{"q":"吃西瓜理论里，皮和肉分别对应什么？","opts":["年干为皮，年支为肉；吃皮丢肉富","年干为皮，年支为肉；吃肉丢皮富","月干为皮，月支为肉；吃肉丢皮富","年支为皮，年干为肉；吃肉丢皮富"],"ans":1,"exp":"年干为西瓜皮、年支为西瓜肉；吃肉丢皮富、吃皮丢肉穷、皮肉同吃也富。","sec":"七、带象原则","t":"rule"},{"q":"借象原则里，可以互借其象的有哪两种关系？","opts":["同五行阴阳相同、地支三合","墓库相冲、天干通根","天干通禄神、同五行阴阳不同","天干五合、地支六合"],"ans":2,"exp":"丙与巳一家可互借其象；同五行而阴阳不同如寅与卯，也可互借。","sec":"八、借象原则","t":"rule"},{"q":"夫妻宫的副宫有哪两种情况？","opts":["日干通禄的字，或日支所藏的字","时支的字，或月支同五行的字","与夫妻宫相合的字，或相冲的字","从夫妻宫引出的字，或与夫妻宫同五行的字"],"ans":3,"exp":"副宫：夫妻宫引出的字（或夫妻宫从某字引出），以及与夫妻宫同五行的字；多个宫星可断多次婚姻。","sec":"2. 夫妻宫的副宫","t":"rule"}]},{"n":58,"level":"中级","title":"财命专辑","qs":[{"q":"盲派以禄当财，成立条件是什么？","opts":["命中有印，且印被财破","命中有财，且财与禄相生","命中占禄，无伤食泄禄，或八字无财","命中有官杀，且官杀制禄"],"ans":2,"exp":"禄当财的条件是占禄而无伤食泄禄，或八字无财；禄是现成之福，辛苦求财。","sec":"一、总纲：哪些神可以当财","t":"rule"},{"q":"以禄当财的八字，最怕见到什么？","opts":["比肩帮禄、印星护禄","财星合禄、财星制禄","印星生禄、官杀合禄","劫财分禄、伤食泄禄、穿禄"],"ans":3,"exp":"禄最怕劫财（分禄）、伤食（泄禄）、穿禄；印生禄、禄合财、禄制财则吉。","sec":"二、禄神当财","t":"rule"},{"q":"库遇到刑、冲、穿，按盲派怎么区分开库与不开库？","opts":["冲、刑才是开库，穿是推倒墓本身","冲、穿才是开库，刑是推倒墓本身","冲、刑、穿都是开库","穿、刑才是开库，冲是推倒墓本身"],"ans":0,"exp":"穿不是开库，穿是推倒墓本身；冲、刑才是打开库。","sec":"一、总纲：哪些神可以当财","t":"diff"},{"q":"八字有财星时，伤食当财与无财时有什么不同？","opts":["有财则伤食转为官杀，当官看","有财则伤食是财之原神，作投资之财","有财则伤食不再当财，只作废神","有财则伤食要制财，才算有功"],"ans":1,"exp":"八字无财星时伤食直接当财；有财时伤食是财之原神，为投资之财。","sec":"一、总纲：哪些神可以当财","t":"diff"},{"q":"伤官当财与食神当财，取财特点有什么不同？","opts":["伤官为体力之财；食神为权力之财","伤官为思想、脑力之财；食神为谋为、经营之财","伤官为谋为、经营之财；食神为思想、脑力之财","伤官为现成之财；食神为风险之财"],"ans":2,"exp":"伤官＝谋为、经营之财；食神＝思想、脑力之财；天干食表思想，地支食表企业。","sec":"一、总纲：哪些神可以当财","t":"diff"},{"q":"官杀统财成立，要满足哪三个限制？","opts":["官（杀）或财只有一个、财官相冲、大运也算","官（杀）与财各有两个、财官相连、只论原局","官杀与财相邻、日主身强、只论大运","官（杀）或财只有一个、财官相连、只论原局"],"ans":3,"exp":"「少」指只有一个，且财官必须相连（财生官）；只论原局，大运出现不算。","sec":"1. 官杀与财互统","t":"rule"},{"q":"原局财星很多、官星只有一个，且财生官相连，按盲派怎么论？","opts":["官统财，官与财都当财富看","财统官，官星当官看","财官两无功，只能论工薪","财多身弱，须印星化财"],"ans":0,"exp":"财多官少，官统财；官（杀）多财少则财统官杀；统了之后官与财都当财富，不再当官看。","sec":"1. 官杀与财互统","t":"calc"},{"q":"「过河拆桥」是什么结构？大运与流年哪个算？","opts":["主位官生宾位财，财被弄住；大运流年都算","主位财生宾位官，官被弄住；大运算，流年不算","宾位财生主位官，官被弄住；流年算，大运不算","主位财生宾位官，官被弄住；流年算，大运不算"],"ans":1,"exp":"日支的财生宾位的官，这个官再被宾位另一字合、制、坏；大运来坏算，流年坏不算。","sec":"3. 过河拆桥（发大财的少见结构）","t":"rule"},{"q":"风险取财（炒股、博彩）的做功之神是什么？","opts":["伤官、食神","财星、禄","比肩、劫财","印、官杀"],"ans":2,"exp":"风险取财主要靠比肩、劫财做功，如劫制财、劫去印、比劫抗杀；智力取财是伤食，体力取财是比劫禄。","sec":"2. 风险取财","t":"step"},{"q":"按盲派，博彩赌博时，哪些日子赢、哪些日子输？","opts":["财、伤食之日赢，比劫、官杀之日输","印、比劫之日赢，财、官杀之日输","比劫、财之日赢，官杀、伤食之日输","比劫、官杀之日赢，财、伤食之日输"],"ans":3,"exp":"赢钱之神是比劫、官杀，输钱之神是伤食、财。","sec":"2. 风险取财","t":"rule"},{"q":"体育运动员、歌星、影星这类名人体力取财，共同特点不含下列哪项？","opts":["财星旺相且身弱","比劫做功效率高","一般有伤食配合","丙丁火做功或七杀虚透于干"],"ans":0,"exp":"名人类三个特点：比劫做功效率高；有伤食配合（技术、艺术）；有丙丁火做功或七杀虚透（名气）。","sec":"4. 体力取财","t":"diff"}]},{"n":59,"level":"中级","title":"官命看法","qs":[{"q":"按盲派，官命成立的核心要素是什么？","opts":["日主身旺，官杀受日主承载","印星旺而官杀轻，印能生官","官星透干通根，且不被合","官杀与印俱全且有根，有做功"],"ans":3,"exp":"盲派看官命不看日主旺衰，只看官杀、印是否有根并做功，功要落在主位。","sec":"一、官命的核心与总则","t":"rule"},{"q":"官杀只是天干虚透、地支无根，按盲派怎么看？","opts":["只当名气，大运落实时易当官","只能当小官，大运无关","照样当官，透干即有权","只主虚名，一生不能当官"],"ans":0,"exp":"官杀必须有根；虚透只是名气，但大运把它落实时也易当官。","sec":"一、官命的核心与总则","t":"rule"},{"q":"官杀、印、伤食做功的字都落在宾位、没有主位的字参与，容易出现什么走向？","opts":["容易走向做官后丢官","容易走向发财而非当官","容易走向当官但职位虚","容易走向灾病而非功名"],"ans":1,"exp":"做功必须有主位的字参与；功落在其他位置，容易走向发财，做不好也转向取财。","sec":"一、官命的核心与总则","t":"rule"},{"q":"官杀与劫刃相配做功，其中「羊刃＋七杀」做功主什么部门？","opts":["纪检或文官系统","检察、法院、法律","执法、实权、军队","带思想文化性的行业"],"ans":2,"exp":"羊刃＋七杀＝执法、实权、军队；申酉做功才偏检法，伤官＋官杀偏纪检，别混。","sec":"一、官命的核心与总则","t":"diff"},{"q":"局中申、酉、丑、寅几个字做功成官命，一般论作哪个部门？","opts":["文化宣传","检察、法院","纪检","公安"],"ans":3,"exp":"申、酉做功偏检察法院法律；再加丑、寅四字齐做功，则论公安。","sec":"一、官命的核心与总则","t":"calc"},{"q":"同样是羊刃（卯）与伤官并见，伤官把羊刃泄掉，主什么？","opts":["主文笔、文官，不带枪","主执法，伤官助刃带枪","主军队，泄刃反增杀气","主做生意，转而取财"],"ans":0,"exp":"刃杀做功是执法军队；伤官泄了羊刃，则转为文笔、文官，刃空亡也不带枪。","sec":"二、制用做功当官","t":"diff"},{"q":"制用、化用做官，哪种效率高、官职大？","opts":["化用官大，制用易因不净反局","制用效率高；化用效率低、级别不大","化用效率高，生化顺畅官更大","两者效率相同，只看有无根"],"ans":1,"exp":"印化官杀只是化走，效率低，级别不大；制用把对方制干净，效率高。","sec":"三、生用化用做功当官","t":"diff"},{"q":"盲派说做功要「制干净」，下列哪种情形才算制到位？","opts":["官杀与印同时有根，即算制","两字相冲，冲动即算制","真正制住对方，不是对抗不分胜负","两字相合，合住即算制"],"ans":2,"exp":"制一定要真正制住对方，对抗不分胜负不算；时上申与卯是合，不叫制。","sec":"一、官命的核心与总则","t":"rule"},{"q":"印戴官帽、以印为用做官，大运或流年把官帽合走，会怎样？","opts":["官帽被摘，主发财不主丢官","官帽被摘，但只主官小","官帽合来更稳，反而升官","官帽被摘，丢官"],"ans":3,"exp":"印为用时怕大运坏印；官帽可摘，合走即丢官。","sec":"三、生用化用做功当官","t":"rule"},{"q":"「官戴财帽子」与「财戴官帽子」，各以什么为主、多是什么职业？","opts":["官戴财帽以财为主，国企经营者；财戴官帽以官为主，管财的官","官戴财帽主私企老板；财戴官帽主国企经营者","两者都以官为主，区别只在官职大小","官戴财帽以官为主，行政官员；财戴官帽以财为主，企业经营者"],"ans":0,"exp":"戴什么帽子就以什么为主：官戴财帽看财象，做企业；财戴官帽看官象，做管财的官。","sec":"五、管财的官与做企业的官","t":"diff"},{"q":"官命里「连体之字」被大运流年坏了，会怎样？","opts":["解局，官运更通","反局，丢官或出事","只主破财，官位不动","只主合绊，官位不动"],"ans":1,"exp":"连体之字不能坏，如辛庚、丙戌，坏了即反局，丢官或出事。","sec":"六、根与虚的要求（总结）","t":"rule"}]},{"n":60,"level":"中级","title":"婚姻专辑","qs":[{"q":"好婚姻里「宫制星」指夫妻宫的字制去夫妻星。男命、女命各怎么制才算好？","opts":["男命比劫制财，女命伤官制官","男命食伤制财，女命比劫制官","男命印星制财，女命食神制官","男命官杀制财，女命印星制官"],"ans":0,"exp":"宫制星为好婚姻：男命比劫制财、女命伤官制官；但制不住反为坏婚姻。","sec":"一、好婚姻与差婚姻的组合","t":"rule"},{"q":"夫妻宫位合了什么字之外，合其他的星婚姻都不好？","opts":["正偏财与官杀","正偏印与禄","比肩劫财与印","食神伤官与比肩"],"ans":1,"exp":"原文：夫妻宫位合了正偏印与禄之外，合其他的星都婚姻不好。","sec":"一、好婚姻与差婚姻的组合","t":"rule"},{"q":"夫妻宫字对夫妻星「穿」与「冲」，结果有何不同？","opts":["穿冲都只是吵架，不一定离婚","冲必离婚或配偶死亡，穿则可以","穿必离婚或配偶死亡，冲则可以","穿冲都必离婚，只是时间不同"],"ans":2,"exp":"多婚第一条：夫妻宫穿夫妻星，必离婚或配偶死亡；冲可以（冲才是管住）。","sec":"二、多婚的命理","t":"diff"},{"q":"男命正财、女命正官得正位，遇到制它的字，按多婚规则怎么论？","opts":["正星可以制，偏星受制婚姻易出问题","正偏星受制都无妨，有宫就稳","正偏星都不可制，制则必离","偏星可以制，正星受制婚姻易出问题"],"ans":3,"exp":"正星得正位不能制；偏星（偏财、七杀）可以制。","sec":"二、多婚的命理","t":"rule"},{"q":"因夫妻星多现而离婚，婚姻次数按什么数？","opts":["夫妻星有几个就几次","坏宫之字有几个就几次","夫妻宫现几次就几次","坏星之字有几个就几次"],"ans":0,"exp":"因宫被坏离婚，坏宫之物有几个就几次；因星多现离婚，星有几个就几次。","sec":"二、多婚的命理","t":"rule"},{"q":"女命夫宫坐七杀，处正位；月上另有官星拱入夫宫，坐偏位。哪个是正夫？","opts":["官星是正夫，七杀是偏夫","七杀是正夫，官星是偏夫","两者都是正夫","月上官星是正夫，七杀为情人"],"ans":1,"exp":"坐正位的是正夫，坐偏位的是偏夫，不以星的正偏来定。","sec":"二、多婚的命理","t":"calc"},{"q":"夫妻宫占夫妻星之墓，无刑冲克破也易独身，如何开库？","opts":["只能靠大运六合，刑冲反凶","只能靠地支刑冲，天干无用","天干钥匙或地支代开，如己丑、戊辰","只能靠天干合，不能刑冲"],"ans":2,"exp":"开库天干钥匙、地支代开都可（如己未、己丑、戊辰、戊戌）。","sec":"三、独身的命理","t":"rule"},{"q":"「水中捞月」的三个条件是什么？","opts":["正星坐宫、日主与时支自合、天干偏星干扰","偏星坐宫、日主与日支自冲、天干正星干扰","正星坐宫、日主与日支自合、天干比劫干扰","正星坐宫、日主与日支自合、天干偏星干扰"],"ans":3,"exp":"符合者眼界高、理想主义，遇到的对象总不如意，独身。","sec":"三、独身的命理","t":"rule"},{"q":"下列日柱中，哪个是「自合坐正星」的水中捞月日柱？","opts":["丁亥","己巳","丁巳","壬子"],"ans":0,"exp":"自合坐正星的日柱：丁亥、己亥、戊子、辛巳、壬午、癸巳（甲午不一定）。","sec":"三、独身的命理","t":"calc"},{"q":"结婚应期里，天干配偶星逢太岁相合，要想定为应期还须什么前提？","opts":["配偶星必须入墓，逢合开库","配偶星有根得旺，不能无根虚浮","配偶星必须无根，逢合才动","配偶星必须被冲，再逢合"],"ans":1,"exp":"配偶星无根虚浮，逢合即制即坏，不能定为应期。","sec":"四、结婚应期","t":"rule"},{"q":"夫宫亥与夫星寅原本相合、被牵绊，结婚应期该看哪年？","opts":["子年或卯年，再合亥寅","午年或戌年，半合寅木","巳年或申年，冲开亥寅之合","亥年或寅年，伏吟加强合力"],"ans":2,"exp":"宫或星原有合被牵绊，应在冲其合的年份，冲合中任一方都行；巳冲亥、申冲寅。","sec":"四、结婚应期","t":"calc"},{"q":"盲派看结婚应期，太岁管什么？","opts":["太岁为杀则婚姻必差","应期与婚姻好坏都管","只管婚姻好坏，不管应期","只管结婚应期，不管婚姻好坏"],"ans":3,"exp":"太岁管应期，不管婚姻好坏；婚姻质量看八字与大运配合。","sec":"四、结婚应期","t":"rule"}]},{"n":61,"level":"中级","title":"学历与牢狱","qs":[{"q":"按盲派，判断学历的「学历之神」和「破坏学历之神」分别是哪些？","opts":["官杀、印、伤官；破坏的是财、食神、比劫","官杀、印、食神；破坏的是财、伤官、比劫","印、食神、财；破坏的是官杀、比劫","印、财、食神；破坏的是官杀、伤官、劫"],"ans":1,"exp":"学历之神是官杀、印、食神；破坏者是财、伤官（无制）、比劫。","sec":"一、学历：判断的神","t":"rule"},{"q":"盲派看学历，印星必须满足什么条件才表示有学历？","opts":["必须有根，无根则文化浅","必须旺相，弱则文化浅","必须做功，不做功是懒惰不好学","必须透干，藏支不表学历"],"ans":2,"exp":"印是学业、本事，必须做功才表示学历；不做功＝懒惰不好学、笨、不开化。","sec":"一、学历：判断的神","t":"rule"},{"q":"伤官对学历的影响，哪种配置才学有所成？","opts":["伤官配财，财生官杀","伤官旺而无制，聪明自成","伤官配比劫，聚众成势","伤官配印做功，或配官杀做功"],"ans":3,"exp":"伤官聪明但不守规矩；配印、配官杀做功学有所成；伤官配财、配比劫则不学习，伤官无制学历难高。","sec":"一、学历：判断的神","t":"diff"},{"q":"按盲派的文理象法，数学、化学、法律各取什么字？","opts":["数学取戌亥庚申；化学申子辰；法律申酉加丑","数学取戌亥庚申；化学申酉加丑；法律申子辰","数学取申子辰；化学戌亥庚申；法律寅卯配火","数学取寅卯配火；化学申子辰；法律申酉加丑"],"ans":0,"exp":"戌主数学、亥为数字，庚申亦属数学；化学为申子辰结合；法律为申酉金加丑。寅卯配火主中文。","sec":"一、学历：判断的神","t":"xiang"},{"q":"盲派判断学历的步骤，正确顺序是什么？","opts":["先看破坏之神，再看印官杀食神，后看大运","先看印官杀食神做功，再看破坏之神，后看大运","先看大运配合，再看印官杀食神，后看破坏之神","先看日主旺衰，再看印官杀食神，后看大运"],"ans":1,"exp":"先看印与官杀、食神哪个做功，再看财、比劫、伤官有没有坏印，最后看大运是否配合。","sec":"一、学历：判断的神","t":"step"},{"q":"按盲派，「阴制阳」的牢狱信号里，阴的地支是哪几个？","opts":["辰、戌、丑","子、丑、亥","亥、丑、辰","亥、子、未"],"ans":2,"exp":"亥水、丑土、辰土是十二支中阴的地支，有牢狱象；阳性的有用之物被这些坏了可能牢狱，阳制阴不为牢狱。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"盲派说比劫与伤官同见，会出现什么犯罪倾向？","opts":["暗中策划，必由官星指认","只主口舌是非，不犯法","单打独斗，偷盗为主","结伙拉帮，再与官杀对抗必牢狱"],"ans":3,"exp":"劫财伤官组合主结伙违法（拉帮结派），再与官杀对抗必牢狱，是黑道的一种组合。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"伤食与官杀，哪种关系才是犯罪结构？","opts":["对抗，制去了就不是","相生，伤食生官杀","制服，制得越干净越凶","相合，伤食合官杀"],"ans":0,"exp":"犯罪是伤食与官杀对抗，注意是对抗而不是制；制去了就不是。","sec":"三、牢狱之灾的看法","t":"diff"},{"q":"伤官与官杀不和的犯罪结构，在什么年份才应牢狱之灾？","opts":["大运交脱之年","官星出现之年","日主逢冲之年","比劫出现之年"],"ans":1,"exp":"食伤得旺自以为是，但必须官出现之年才产生牢狱之灾，官星不出现时不会意识到官的厉害。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"盲派说牢狱的核心机制「反局」，是原局的什么变成了什么？","opts":["原局的生，被运岁变成克","原局的合，被运岁冲开","原局的冲、制，被运岁变成合","原局的刑，被运岁变成合"],"ans":2,"exp":"原局本是制（冲、制）的结构，大运流年把它变成合（冲制不喜合，合则反）就是反局，大部分主牢狱。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"按盲派，辰运入狱，哪种情形算出狱？","opts":["辰戌冲，开辰库","辰辰自刑，辰库被穿","辰丑相破，辰库被晦","辰酉合，闭辰库"],"ans":3,"exp":"牢狱为库者冲穿坏库为出狱；辰运入狱则辰酉合闭辰库亦为出狱。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"盲派看出狱，哪个情形可以判断出狱？","opts":["日主得禄之年，或合出冲出日主","日主入墓之年","官星被克去之年","印星得旺之年"],"ans":0,"exp":"日主得禄之年，或日主被合出、冲出之年出狱；牢狱为库者冲穿坏库、辰库被酉合闭也出狱。","sec":"三、牢狱之灾的看法","t":"rule"}]},{"n":62,"level":"中级","title":"实战演示","qs":[{"q":"盲派读八字，天干与地支各代表什么？读盘的先后怎么做？","opts":["天干为形，地支为象；先看地支再用天干落实","天干地支都是象，先看月令再看其他字","天干为象，地支为形；先看天干再用地支落实","天干为用，地支为体；先看日支再看年柱来"],"ans":2,"exp":"「在天成象，在地成形」：四个天干为象、四个地支为形；看天干定性质，用地支落实。","sec":"一、修为的两个来源","t":"diff"},{"q":"论大运时「原局是车，大运是路」，原局不好而大运好，结果如何？","opts":["好运可延续一生，不会随运消退的","只在原局应期的流年里才能够好起来","不会好，原局不好大运好也没有用","也能在该运中好，但运过即完"],"ans":3,"exp":"原局不好、大运好，可以在此运中好，但运一过就完，这种情形不多见。","sec":"六、流年应期的三条规则与长篇示范","t":"diff"},{"q":"流年既有原局应期、又有大运应期时，怎样取舍？","opts":["原局应期优先；已发生作用则以大运为主","大运应期优先于原局应期，不分先后","两者同等重要，需要同时一起来论","只看流年干支，不再分原局和大运了"],"ans":0,"exp":"规则：流年的原局应期优于大运应期；若原局应期已发生了作用，则以大运为主。","sec":"六、流年应期的三条规则与长篇示范","t":"diff"},{"q":"天干透出的字，「实」与「虚」遇合，结果有什么不同？","opts":["实的一合被合走而坏功；虚的一合固定即制","实的一合即固定为制；虚的一合走而坏功","实的合走后成化；虚的合住后反而成制","虚实都一样，合了就一律按照合绊来论"],"ans":1,"exp":"实则合了固定住＝制；虚则被合走＝坏功。朱镕基造与袁世凯造的差别就在虚实。","sec":"二、实战步骤（提炼）","t":"diff"},{"q":"阴制阳与阳制阴，各主什么象？","opts":["阴制阳与阳制阴，一概都只主牢狱象","阴制阳主枪象；阳制阴（亥丑辰）主牢狱象","阴制阳（亥丑辰）主牢狱象；阳制阴主枪象","阴制阳主文职之象；阳制阴主武职之象"],"ans":2,"exp":"阴实阳虚，阴制阳（亥丑辰）为牢狱象，阳制阴为枪象。","sec":"二、实战步骤（提炼）","t":"diff"},{"q":"戊日主与己日主，各偏重什么，要开哪些库？","opts":["戊气胜形开丑未库；己偏形开戌辰库","戊己都偏重形，都需要去开辰戌库","戊己都气胜形，都需要去开丑未库","戊偏形开戌辰库；己气胜形开丑未库"],"ans":3,"exp":"戊偏形、要找气，开戌、辰库；己气胜形、要找形，开丑、未库。","sec":"四、十干日主的用法特点","t":"calc"},{"q":"甲木与乙木，哪个相对难伺候？乙木喜见什么？","opts":["甲难伺候怕金；乙好伺候，喜金克成器","甲好伺候，喜火来泄；乙难伺候，喜水生","乙难伺候怕金；甲好伺候，喜金来克","甲乙都怕金，一见金克就一定会坏"],"ans":0,"exp":"甲为阳指气，最难伺候；乙为阴指形，相对好伺候，喜金克与金火组合。","sec":"四、十干日主的用法特点","t":"diff"},{"q":"盲派所说「余气」（如丑中癸）有什么含义？能否当丈夫？","opts":["经冲才出的气；可当夫星，主二婚或多婚","量小、最后、别人退下的；不当夫，作桃花","量大、最先、本人所有的；可以当夫星","很弱的原神；可作夫星，只是比较晚婚"],"ans":1,"exp":"余气＝量很小、最后一个、中途剩下或别人退下的，不足以构成丈夫，只作桃花看。","sec":"八、命术轶闻中的分析思路","t":"rule"},{"q":"盲派看学历，主要看原局里的什么？对伤官有什么要求？","opts":["看官杀、比劫；伤官有无制服都行","只看印星；食伤一概不看，不论有无制","看食、印；伤官须有制服（庚除外）","看财星、劫财；伤官越旺学历越高"],"ans":2,"exp":"看学历看食、印；伤官必须有制服（庚除外）；有制的财也可当学历看。","sec":"七、婚姻、桃花、学历示范","t":"rule"},{"q":"盲派中「黑道」命格有哪两种典型组合？","opts":["财官相生；食神制杀","印星制伤官；比劫帮身","劫伤组合；伤食制住官杀","劫伤组合；伤食与官杀对抗"],"ans":3,"exp":"黑道的两种组合：比劫遇伤官、以及伤食与官杀对抗（不是制）。","sec":"八、命术轶闻中的分析思路","t":"rule"},{"q":"拱与六合，在象上有什么区别？","opts":["拱主合伙，不抢占；六合有强占之象","拱与六合都是强占之象","拱与六合都只主合伙，没有区别","拱有强占之象；六合主合伙"],"ans":0,"exp":"拱＝合伙（桃花也叫打伙计），拱不是抢占；六合有强占之象。","sec":"七、婚姻、桃花、学历示范","t":"diff"},{"q":"盲派看男命桃花，核心是哪两者发生作用？","opts":["比劫与财发生作用","伤食与财发生作用就是桃花","印星与食伤发生作用","官杀与印星发生作用"],"ans":1,"exp":"男命伤食与财发生作用就是桃花，如伤官为桃花；比劫、官杀不是此例。","sec":"七、婚姻、桃花、学历示范","t":"rule"}]},{"n":84,"level":"高级","title":"天干五合与地支六合的深论","qs":[{"q":"天干相合的两个字，强弱不同时，信息怎么互换？","opts":["强方代表弱方的信息，弱方顺从强方","弱方代表强方的信息，强方顺从弱方并受其制","双方信息各占一半，不分强弱也不分主从","双方各守本性，互不借用也互不影响"],"ans":0,"exp":"合在一起的两字任何一方都能代表对方；强的一方制弱的一方，强方就代表弱方的信息，弱方顺从强方的信息。","sec":"一、天干五合：双方互为代表","t":"rule"},{"q":"丁火日主见丙辛相合，这笔财按盲派怎么论？","opts":["比肩合财，父母给的遗产","劫财合财，非劳动所得，炒股期货赌博类","劫财合财，辛苦劳动所得，薪水类","劫财合财，合伙经营所得，分红类"],"ans":1,"exp":"丙辛合是劫财合财，财是被劫财合过来的，不是劳动所得，而是靠非常手段获利：炒股、期货、赌博一类。","sec":"一、天干五合：双方互为代表","t":"calc"},{"q":"食神合印与伤官合印，各偏向什么？","opts":["两者都偏学术研究，没有区别","食神合印偏技术艺术，伤官合印偏学术研究","食神合印偏学术研究，伤官合印偏技术艺术","食神合印偏权力，伤官合印偏财富"],"ans":2,"exp":"食神合印是带有思想性的文化，偏学术研究；伤官合印偏技术、艺术方面的成就。","sec":"一、天干五合：双方互为代表","t":"diff"},{"q":"合杀而杀被制，伤官合杀与食神合杀的结局有何不同？","opts":["两者都是发财，只是财有多少之分","两者都是当官，只是官有大小之分","食神合杀能当大官，伤官合杀只是发财","伤官合杀变权力能当大官，食神合杀是发财"],"ans":3,"exp":"伤官也代表杀，杀被制而伤官合杀，伤官变成权力，能当大官；换成食神合杀被制，则不是当官而是发财。","sec":"一、天干五合：双方互为代表","t":"diff"},{"q":"食神合印这类天干合落在宾位，与日主本人的事业什么关系？","opts":["无关，只是自己的精神享受","直接决定日主的事业成败与高低","主六亲，决定父母的状况好坏","主财运，决定日主能否发财"],"ans":0,"exp":"合在宾位时与日主本人的事业无关，只是自我精神享受；合到主位才与日主直接相关。","sec":"一、天干五合：双方互为代表","t":"rule"},{"q":"地支六合，不论在命局、大运还是流年，一律怎么论？","opts":["以合化论，双方合成另一种五行","以合绊论，双方都失去一定的作用","以合绊论，只有较弱的一方失性","命局合绊论，大运流年合化论而不绊"],"ans":1,"exp":"地支六合比天干简单：不管命局、大运、流年的合，都以合绊论，合住的双方都丧失原性。","sec":"二、地支六合","t":"rule"},{"q":"午未相合，失性的要点是什么？","opts":["熄了寅中丙火，印星灭","闭金库，午火合入土中","闭木库，午火被晦","闭水库，坏乙木"],"ans":2,"exp":"午未合闭木库、午火被晦；子丑合闭金库；辰酉合闭水库、坏乙木；寅亥合熄寅中丙火。","sec":"二、地支六合","t":"calc"},{"q":"大运与流年相合，大运的合什么时候起作用？","opts":["入大运就起作用，与流年无关","只有大运合原局时才起作用","流年合大运不起作用，只看原局","大运静止，须流年去合才起作用"],"ans":3,"exp":"大运是静止的，只有流年去合它才起作用；流年合入命局，对原局是绊、对流年是留（得到），实际是一种应期。","sec":"三、流年合大运","t":"rule"},{"q":"盲派说的「反局」是指什么？","opts":["违背原局组合意象的合冲，主凶","凡大运流年合冲原局的字，都主凶","违背原局组合意象的合冲，多转为吉","原局内部既有合又有冲的结构，主凶"],"ans":0,"exp":"凡是违背原局组合意象的合冲叫反局，主凶：如原局是巳制酉，辰酉合保护了酉，巳制不住它。","sec":"四、反局","t":"rule"},{"q":"日主坐财库，冲开财库后，怎样的情形最好？","opts":["冲开库后再用合把库闭上守住","冲开财库，并能制住库中之财及其原神","冲开财库，库中之财不受制任其流出","不冲库，让库闭着守住财"],"ans":1,"exp":"见财库一定要冲，冲开能发；冲开财库最好还能制住库中之财和它的原神，这是最大的财之一。","sec":"四、反局","t":"step"}]},{"n":85,"level":"高级","title":"三合、六冲、相穿、三刑、相破的深论","qs":[{"q":"合的四种用法里，「合留」「合绊」各指什么？","opts":["合留：一方克去另一方；合绊：一方被合去","合留：流年合住八字中的字；合绊：力量相当的两字相合","合留：力量相当的两字相合；合绊：流年合住八字中的字","合留：一方被合去；合绊：一方克去另一方"],"ans":1,"exp":"合留是流年合住八字中的字，婚姻应期的核心；合绊是力量相当者相合；合制是一方被合去，合伤是一方克去另一方。","sec":"一、合的四种用法","t":"diff"},{"q":"婚姻应期上，只合到配偶星与连配偶宫也合动，分别论什么？","opts":["只合星是结婚，宫也合动是生子","星宫都合只是谈对象，要冲才结婚","只合星是谈对象，宫也合动才是结婚","只合星就结婚，宫合是离婚"],"ans":2,"exp":"口诀：星合谈对象，宫合成夫妻；合住即是留住。","sec":"一、合的四种用法","t":"rule"},{"q":"地支六合中，哪一合效率最高、能量最大？","opts":["午未合，火土相生","寅亥合，亥水克寅中丙火","卯戌合，卯木克戌土","巳申合，巳火制申金"],"ans":3,"exp":"巳申合是巳火制申金，效率最高；午未合最差，意义不大，只闭墓库。","sec":"二、地支六合各合的作用与暗合","t":"rule"},{"q":"午亥、卯申、寅丑这三组合，盲派称作什么，性质如何？","opts":["暗合，一方强一方弱的换象","暗合，双方互相化气成新五行","三合，中神最重要","六合，两方力量对等"],"ans":0,"exp":"午亥、卯申、寅丑近似六合，叫暗合，是一方力强、另一方力弱的换象，也是一种做功方式。","sec":"二、地支六合各合的作用与暗合","t":"diff"},{"q":"地支有寅、午、午、戌四字，能不能成寅午戌火局？","opts":["不成，寅午戌被午冲散","不成，中神午双现入墓","成火局，午戌合为主","成火局，午多更旺"],"ans":1,"exp":"三合局中神为尊，中神多现或双现不成合局，而是入墓。","sec":"三、三合局","t":"calc"},{"q":"冲到墓库时，近冲、隔冲、遥冲分别是什么结果？","opts":["近冲开库，隔冲伤，遥冲坏库","近冲伤，隔冲开库，遥冲冲去","近冲坏库中之物，隔冲伤，遥冲动、开","近冲遥冲都开库，隔冲才坏库"],"ans":2,"exp":"近冲库，冲坏库中之物；隔冲库，伤；遥冲库，冲动、冲开。","sec":"四、六冲","t":"rule"},{"q":"子、午、子三字，两子夹一午，一般怎么论？","opts":["二冲一，午必被冲去","两子互相对冲，各自消耗","子水旺，午火被制死","夹冲，一般不为冲坏"],"ans":3,"exp":"夹冲：两个冲一个，一般不为冲坏；若再见帮手（如巳、未、戌）才冲坏。成势的冲才可能冲伤冲去。","sec":"四、六冲","t":"calc"},{"q":"子未、丑午、寅巳、申亥四组穿，哪两组力量较小？","opts":["寅巳、申亥","子未、申亥","丑午、寅巳","子未、丑午"],"ans":0,"exp":"克泄穿最厉害：子未、丑午、卯辰、酉戌；寅巳、申亥是生穿，力小，只有穿动、穿倒、不和之象。","sec":"六、相穿","t":"diff"},{"q":"正印被穿倒、七杀被穿倒，分别当什么看？","opts":["正印当食神，七杀当正官","正印当偏印，七杀当正官","正印当偏印，七杀当食神","偏印当正印，七杀当劫财"],"ans":1,"exp":"穿倒是正的穿成偏的、偏的穿成正的：穿倒正印当偏印看，穿倒七杀当正官看。","sec":"六、相穿","t":"calc"},{"q":"遇到丑、戌、未等库，用什么才能开库？","opts":["穿或合，冲开不了库","冲、刑、穿都能开库","冲或刑，穿开不了库","只有合能开库"],"ans":2,"exp":"穿库开不了库，只有冲库、刑库才能开；穿的结论是穿倒或凶灾。","sec":"六、相穿","t":"rule"},{"q":"子卯、卯午相破的核心是什么？","opts":["一方被合去，另一方得生","双方都衰弱，无力相生","一方克泄另一方，穿倒对方","双方帝旺，旺而不生"],"ans":3,"exp":"破本是相生关系，但双方各自帝旺，旺而不生，不履行职责；还有破坏、破产、捣乱的一层意思。","sec":"八、相破","t":"diff"}]},{"n":86,"level":"高级","title":"体用宾主与看盘总纲","qs":[{"q":"盲派按位置分宾主，下列哪项归「主」？","opts":["日主以外的干支","年柱与月柱","日主与日支","岁运"],"ans":2,"exp":"日主、日支是主位，有时时柱也算主；年月柱是先天定的祖上父母，岁运是外来的东西，都属宾。","sec":"一、宾主：按位置分","t":"diff"},{"q":"按十神分体用，哪一组是「体」？","opts":["印、官、杀","财、官、杀","食神、伤官、财","比肩、禄、印、劫财"],"ans":3,"exp":"体是我的本钱、工具：比肩、禄、印、劫财；用是我追求的目的：财、官、杀；食伤中性。","sec":"二、体用：按十神分","t":"rule"},{"q":"食神与伤官在体用上怎么归属？","opts":["中性，食神偏体、伤官偏用","食神偏用、伤官偏体","都是体","都是用"],"ans":0,"exp":"食伤是中性，食神偏体、伤官偏用，可当体也可当用。","sec":"二、体用：按十神分","t":"diff"},{"q":"功神与废神的区别是什么？","opts":["功神生日主，废神克日主","功神产生效率，废神不产生效率","功神是体，废神是用","功神是旺字，废神是弱字"],"ans":1,"exp":"用体取用叫做功，做功的字是功神；消耗能量却无效率或效率极低的是废神。","sec":"二、体用：按十神分","t":"diff"},{"q":"盘中是杀印相生，印化官杀，这属于做功五种结构里的哪一种？","opts":["生用","合用","化用","制用"],"ans":2,"exp":"以印化官杀为化用，多是当官的；制用是比肩去财、伤官去官等，生用是食伤生财。","sec":"三、做功的五种结构","t":"calc"},{"q":"盘中是食神、伤官生财，按做功五种结构属于哪一种？结果怎样？","opts":["墓用，利用墓库收藏财","化用，多是当官的","制用，能去官杀而当官","生用，靠劳动创造财富，一般不发大财"],"ans":3,"exp":"食伤生财、食伤泄秀属生用，靠劳动创造财富，一般不发大财。","sec":"三、做功的五种结构","t":"calc"},{"q":"在八字类型中，A类「去用结构」去哪个字要特别慎重？","opts":["去禄，因为禄是自身","去财，因为财是妻星","去官，因为官是权力","去印，因为印是母星"],"ans":0,"exp":"去用结构占约四成，去干净吉、去不净凶；禄为自身，去禄要特别慎重。","sec":"四、八字的八个类型（按做功结构分比例）","t":"diff"},{"q":"一个八字没有功神、找不到做功之神，盲派认为是什么层次？","opts":["富贵八字，成气成势","差八字，找不到做功之神","普通八字，有工作有饭吃","特殊八字，靠大运发"],"ans":1,"exp":"差八字没有功神，废神越多越差；功神越多层次越高，废神越多层次越低。","sec":"五、八字的层次","t":"rule"},{"q":"盲派看盘入手，最先看哪里？","opts":["大运，先看现行大运好坏","年柱，先看祖上是否有根","主位，先看日柱、时柱","月令，先看用神是否得令"],"ans":2,"exp":"先从主位入手：主位的东西可用、力量大，八字好；主位的字不可用，八字差。","sec":"六、看盘入手顺序","t":"step"},{"q":"「杀」落在主位，按盲派要求是什么？","opts":["一定要被合走才吉","只要日主旺相就吉","有杀就吉，无用也吉","一定要用才吉，无用则凶"],"ans":3,"exp":"体在主位一定要有用；杀在主位一定要用才吉，无用则凶；财在主位本身就有用。","sec":"六、看盘入手顺序","t":"rule"},{"q":"禄在年上与禄在月上起作用，分别主什么？","opts":["年上受苦无成，月上侍候别人","年上主祖业丰厚，月上主兄弟","年上主远方发财，月上主得官","年上侍候别人，月上受苦无成"],"ans":0,"exp":"禄在年上为受苦、没有成就；禄或劫财在月上起作用，一般为侍候别人。","sec":"六、看盘入手顺序","t":"diff"},{"q":"盲派说解灾的绝招是什么？","opts":["找生助日主的人","找八字中制你忌神的人","找与日主相合的人","找日支所冲的人"],"ans":1,"exp":"解灾的绝招：找八字中制你忌神的人，如周命制毛命的病，是毛的得力助手。","sec":"六、看盘入手顺序","t":"rule"}]},{"n":87,"level":"高级","title":"能量效率与正用反用","qs":[{"q":"制、化、泄生三种体现方式，按格局高低排序是（　）。","opts":["泄生最高，化次之，制最低","制与化相同，泄生最低","化最高，制次之，泄生最低","制最高，化次之，泄生最低"],"ans":3,"exp":"制是直接干掉对方，格局最高；以印化杀次之；泄生怎么生也生不出上亿，效率最低。","sec":"一、制、化、泄的总排序","t":"step"},{"q":"大人物多是哪类人，为什么？","opts":["凶神有制化的人，凶神灵活善变、不择手段","凶神无制的人，凶神力量大无拘束","吉神为用的人，吉神正派受人拥戴","吉神有制化的人，吉神稳定不易出错"],"ans":0,"exp":"杀伤劫枭为用档次高，灵活适应强；财官印食为用太正派，受约束，成就反低。","sec":"一、制、化、泄的总排序","t":"diff"},{"q":"合制的能量由高到低，最前面的两组是（　）。","opts":["子丑第一，巳申第二","巳申第一，巳酉第二","巳酉第一，子丑第二","巳申第一，卯戌第二"],"ans":1,"exp":"合制次序：巳申＞巳酉＞子丑＞卯戌＞卯申、午亥、寅亥、寅丑、午戌。","sec":"1. 合制：把原神和用神全部制住","t":"step"},{"q":"戊子、丙戌、辛巳、丁亥四个柱，合制效率高的两个是（　）。","opts":["辛巳与丙戌，各取其一","戊子与丁亥，各取其一","戊子与丙戌，干克支","辛巳与丁亥，支制干"],"ans":2,"exp":"干克支效率高，支制干效率低：戊子、丙戌高，辛巳、丁亥低。","sec":"1. 合制：把原神和用神全部制住","t":"calc"},{"q":"子午、卯酉、寅申、巳亥之冲，什么情形才有制的意义？","opts":["一对一力量相当的冲就有意义","只要冲到日主的字就有意义","冲到墓库才算，其他都无意义","形成势力，如二冲一或旺冲衰"],"ans":3,"exp":"冲须成势才能冲伤冲去对方成制；一对一差不多的冲只是冲动、对抗，只有消耗。","sec":"3. 冲制","t":"rule"},{"q":"丑未、辰戌冲库为什么能量最高？","opts":["财官临库不冲不发，冲得干净制得彻底","库本身旺，冲则助旺","库一冲即开，不论制得干不干净","冲库开出的都是吉神，不必制"],"ans":0,"exp":"财官临库不冲不发；但库不用则无用，只有冲得干净、制得彻底才有用。","sec":"3. 冲制","t":"diff"},{"q":"穿制的口诀「体穿用，用坏；用穿体，我得」，意思是（　）。","opts":["体穿用、用穿体，都是得到","主位体穿宾位用则得不到，宾位用穿主位体则得到","主位体穿宾位用则得到，宾位用穿主位体则得不到","体穿用、用穿体，都是得不到"],"ans":1,"exp":"主位的体穿宾位的用，用坏了没缘分；宾位的用穿主位的体，反而得到。","sec":"4. 穿制（子未、酉戌、卯辰、丑午）","t":"rule"},{"q":"正用与反用的区别是（　）。","opts":["正用力大异常，反用规矩力小","正用主位用制宾位体，反用主位体制宾位用","正用主位体制宾位用，反用主位用制宾位体","正用反用只看大运，不看主宾位"],"ans":2,"exp":"正用规矩力小；反用阴阳错位异于常人，组合好则才华智慧大、力大。","sec":"1. 定义","t":"diff"},{"q":"一个八字中宾位的东西被制，要有官运或成就，还需要什么条件？","opts":["被制之字必须在年柱","被制之字必须是库","被制之字必须是印星","被制的宾位之字必须与日主发生关系"],"ans":3,"exp":"如子水印与日主没有关系，被制也无官；庚金生子水生甲木，才是副处级官。","sec":"四、宾位的东西被制，且一定要和日主发生关系","t":"rule"}]},{"n":88,"level":"高级","title":"正局反局进阶","qs":[{"q":"正局与反局的定义是（　）。","opts":["日柱做功意象与原局势一致为正，相反为反","日主旺为正局，日主弱为反局","日支与八字五行平衡为正，偏枯为反","日柱做功意象与原局势一致为反，相反为正"],"ans":0,"exp":"正局：日柱做功表达的意象与原局一致（八字无势而日主能做功也称正局）；反局：意象与原局势力相反，主凶。","sec":"一、定义与三层","t":"rule"},{"q":"原局反局、大运反局、流年反局，凶的范围分别是（　）。","opts":["原局不凶、该运凶、该年凶，运过则吉","原局凶、该运凶、该年凶，运过则吉","都只主一生凶，不分运年","原局凶、该运凶、该年凶，运过仍凶"],"ans":1,"exp":"原局反局则原局凶，大运反局该运凶，过了大运则吉，流年反局该年凶。","sec":"一、定义与三层","t":"diff"},{"q":"盲派看日主表述的意象，「日干合什么」代表（　）。","opts":["日干合什么，就是原局势力所在","日干合什么，就是被日支制去的东西","日干合什么，就是它的本意想得到什么","日干合什么，就是它最排斥的东西"],"ans":2,"exp":"日干合的是日主需要的、想得到的；冲则是日主最排斥的。","sec":"日主表述意象的方式","t":"rule"},{"q":"日主之功与日支之功意思不一致时，以谁为主？","opts":["以日支之功为主，不以日主为主","以月令之功为主","两者各占一半，谁旺听谁","以日主之功为主，不以日支为主"],"ans":3,"exp":"日主与日支同时做功看是否一致，不一致为反局；以日主之功为主。","sec":"2. 日主之功与日支之功相反","t":"rule"},{"q":"日主合的官落在哪个位置，不属于反局？","opts":["合年月上的官，表示自己管理别人","合时柱的官，表示自己管理别人","合年月上的官，表示被别人管理","合时柱的官，官坐支只要不冲就不反局"],"ans":0,"exp":"日主合时柱官，要看官坐下之支做什么；合年月官是自己管理别人，不为反局。","sec":"2. 日主之功与日支之功相反","t":"diff"},{"q":"两党冲合并见，什么情况是反局，什么情况不是？","opts":["内外相反是反局，间隔组合不反","间隔相反是反局，内外组合不反","有冲合并见就是反局，无例外","冲合并见皆不反，只看大运来断"],"ans":1,"exp":"年月合日时冲、或年月冲日时合是间隔，两种做功方式相反则乱；金水在内木火在外，用里制外则意思清楚，不反。","sec":"三、冲合反局（两党相反）","t":"diff"},{"q":"大运反局的判断条件是（　）。","opts":["运冲到了日支即为反局","运的五行与原局五行相同","运与原局势力对抗，而又无法被原局所制","运生旺了原局的用神"],"ans":2,"exp":"行运行到与原局势力相对抗、又无法被原局所制的大运，该运凶，过了大运则吉。","sec":"四、大运、流年反局","t":"rule"},{"q":"反局的现象特征，一般是（　）。","opts":["大部分主离婚，财反局主婚姻不顺","大部分主破财，财反局主牢狱","大部分主疾病，财反局则大富","大部分主牢狱，财反局则一辈子受穷"],"ans":3,"exp":"大部分反局结构都主牢狱；比劫抗杀、官杀对抗、与官方意向矛盾都是对抗法律的组合；财反局受穷。","sec":"五、反局的现象特征与综合判断","t":"rule"},{"q":"日主主位有印比时，最怕什么？","opts":["被财官破，破必有灾","被日支合住，合必有灾","被印比再生，生必有灾","被食伤泄，泄必有灾"],"ans":0,"exp":"主位有印比是自己，要去得财官，所以主位印比最怕被财官破，破必有灾。","sec":"日主表述意象的方式","t":"rule"},{"q":"反局的判法，下面哪种说法对？","opts":["日支合去伤官，日支被合制，就是反局","看日支表达的追求与八字的势是否对抗","日支的追求与日主一致，也是反局","只要日支做功方向与八字的势对抗就是反局"],"ans":1,"exp":"并非日支与八字的势对抗，而是日支表达的追求与八字的势对抗；如日支午亥合去伤官，日支也是被午合制，是正局。","sec":"1. 日支做功方向与八字的势对抗","t":"diff"}]},{"n":89,"level":"高级","title":"大运流年与应期","qs":[{"q":"按盲派，月柱管人生哪个年龄段？","opts":["35–55 岁","18–35 岁","1–18 岁","55 岁以后"],"ans":1,"exp":"年柱 1–18 岁，月柱 18–35 岁，日柱 35–55 岁，时柱 55 岁以后；年月为早，日时为晚。","sec":"1. 柱的年龄段","t":"rule"},{"q":"交脱诀：大限（柱的年龄段）应凶，而大运逢吉，如何断？","opts":["吉运抵消，终身不凶","此运即凶，过运转吉","此运不凶，过运则凶","吉运中也凶，过运亦吉"],"ans":2,"exp":"交脱诀：大限应凶、大运应吉，此运不克，过运则凶；大限应吉、大运应凶，此运不吉，过运则吉。","sec":"2. 交脱诀（大限与大运的凶吉叠加）","t":"rule"},{"q":"大运干支各管几年？","opts":["运支前五年，运干后五年","运干运支每年轮流管","运干管十年，运支只作象","运干前五年，运支后五年"],"ans":3,"exp":"运干管前五年，运支管后五年。","sec":"3. 大运的体用","t":"rule"},{"q":"走天干运时，运中地支（体）的作用是怎样的？","opts":["本不参与作用，被流年冲合引动才提前参与","与天干一样全程参与作用","完全不参与，流年也引动不了","只在后五年参与，与流年无关"],"ans":0,"exp":"走天干运时地支是体、是象，不参加作用；逢流年冲合引动，地支就提前参与作用。","sec":"3. 大运的体用","t":"diff"},{"q":"「反客为主」指什么，有哪两种方式？","opts":["运中见八字之字到，生旺与墓绝","运中见八字之字到，通禄与现原身","运中冲去八字之字，冲刑与穿害","运中见八字所无之字，通禄与化象"],"ans":1,"exp":"大运中出现八字中的字就是该字到了，方式是通禄（禄神出现）与现原身（遁藏之字透干）。","sec":"二、反客为主","t":"rule"},{"q":"原局地支有戌，大运或流年天干出现丁，应论什么？","opts":["丁克戌，戌被制","丁生戌，戌得力","丁代表戌的信息，等于戌到","丁与戌无关，只论丁本身"],"ans":2,"exp":"戌中遁藏丁，地支遁藏之字在大运流年天干出现，也是该字的应期。","sec":"二、反客为主","t":"calc"},{"q":"口诀「合者主到，冲者主动，墓者主收，穿者主伤」，下列对应正确的是？","opts":["合主到，冲主伤，墓主动，穿主收","合主收，冲主动，墓主到，穿主伤","合主动，冲主到，墓主收，穿主伤","合主到，冲主动，墓主收，穿主伤"],"ans":3,"exp":"流年大运与原局冲合刑穿墓都是应期：合为到、冲为动、墓为收藏、穿为伤。","sec":"3. 冲合刑穿墓","t":"rule"},{"q":"原局有合、流年来冲；与原局有冲、流年来合，分别怎么用？","opts":["原局有合以冲为应，有冲以合为应","原局有合以冲为应，有冲仍以冲为应","原局有合以穿为应，有冲以墓为应","原局有合以合为应，有冲以冲为应"],"ans":0,"exp":"口诀：原局有合以冲为应，原局有冲以合为应。","sec":"3. 冲合刑穿墓","t":"rule"},{"q":"流年冲大运，当运与不当运有何区别？","opts":["两者都是引动，只是轻重不同","不当运为引动，当运为冲去离开","不当运为冲去，当运为引动","不当运不起作用，当运为大凶"],"ans":1,"exp":"流年冲大运：不当运为引动大运，当运为冲去，是暂时离开之意，不一定凶。","sec":"4. 流年与大运之间","t":"diff"},{"q":"流年穿大运，按盲派怎么看？","opts":["大运被穿则该运全废","穿动大运则引出吉事","无所谓，最怕命局中的字被穿","与穿命局同样凶"],"ans":2,"exp":"大运是外来的，流年穿大运无所谓；最怕的是命局中的被穿。","sec":"4. 流年与大运之间","t":"rule"}]},{"n":90,"level":"高级","title":"干支象义与干支配置","qs":[{"q":"按盲派干为君、支为臣，天干与地支的克制关系是什么？","opts":["干支都不能互克，只论生合","支可克干，干不克支；干支相合时才论干克支","干可克支，支不克干；干支相合时才论支克干","干支互相可克，以旺者为胜"],"ans":2,"exp":"天干可以克地支，地支不可以克天干；干支相合的情况下才论地支克天干，如辛巳、癸巳、丁亥、己亥。","sec":"1. 干为君，支为臣","t":"rule"},{"q":"甲辰、甲戌两柱，甲木能否克住地支？","opts":["能克住戌土，不能克住辰土","辰土、戌土都能克住","辰土、戌土都克不住","能克辰土，不能克住戌土而甲木被坏"],"ans":3,"exp":"天干克地支，如甲辰甲木能克辰土；甲戌甲木不能克住戌土，则甲木被坏。","sec":"1. 干为君，支为臣","t":"calc"},{"q":"丁丑、乙亥、壬申、庚辰四柱，哪一柱是干生支、成「带象」？","opts":["丁丑","壬申","庚辰","乙亥"],"ans":0,"exp":"干生支（甲午、癸卯、壬寅、丁丑、丙戌等）象一致，叫带象；乙亥、壬申、庚辰是支生干，不算。","sec":"2. 干生支与带象","t":"calc"},{"q":"天干财虚透（不坐根），按盲派主什么？","opts":["主官职权力","不主钱财，主才华、会来事、能说会道","主文凭学历","主钱财丰厚，也主才华"],"ans":1,"exp":"财虚透不主钱财，主才华才气、会来事、能说会道，以吉论；实了才表财运。","sec":"十神虚透的含义","t":"rule"},{"q":"印星虚透，用与忌的文凭情况有何不同？","opts":["印不论用忌，虚透都有文凭","印不论用忌，虚透都没文凭","印为用虚透没文凭；印为忌虚透有文凭","印为用虚透有文凭；印为忌虚透没文凭"],"ans":2,"exp":"印分用忌：为用，虚透没文凭；为忌虚透有文凭（或为忌去印也有文凭）。","sec":"十神虚透的含义","t":"diff"},{"q":"口诀「财官临库不冲不发」，下面哪项是配套的说法？","opts":["合库为吉，为用不合则不能用","冲库为凶，为用不冲反而可用","穿库为吉，为用不穿则不能用","冲库为吉，为用不冲则不能用"],"ans":3,"exp":"戊辰、戊戌、己未、己丑通根，财官临库不冲不发，冲库为吉，为用不冲则不能用。","sec":"二、干支虚实","t":"rule"},{"q":"甲寅、甲午、甲申、甲戌四柱，哪一柱天干为「实」（得根）？","opts":["甲寅","甲戌","甲午","甲申"],"ans":0,"exp":"甲木实：甲寅、甲辰、甲子；甲午、甲申、甲戌为虚。","sec":"二、干支虚实","t":"calc"},{"q":"盲派说「虚为应期」，是指什么？","opts":["岁运的虚字，才能做功","原局的虚字，在岁运见到时应事","原局的实字，在岁运见到时应事","大运只看虚，不看实"],"ans":1,"exp":"口诀：实为用怕虚，虚为用怕实；虚为应期；大运见了实，有制化论吉。","sec":"二、干支虚实","t":"rule"},{"q":"丁未、癸丑这类干支关系，盲派叫什么？与丙戊、丁己有何区别？","opts":["藤萝系；丙戊、丁己是原身关系","一个字一个象；丙戊、丁己是半个象","半禄关系；丙戊、丁己是半通禄（一家）","半通禄（一家）；丙戊、丁己是半禄关系"],"ans":2,"exp":"半禄关系：丁未、癸丑；半通禄（一家）：丙戊、丁己；一个字一个象：丙巳、戊巳、丁午、己午。","sec":"三、干支互通：原神、禄、半禄","t":"diff"},{"q":"甲乙木共根叫藤萝系甲，其中甲木见哪个字为根？","opts":["寅","午","卯","亥"],"ans":3,"exp":"藤萝系甲：甲木见亥为根，乙木见寅为根。","sec":"三、干支互通：原神、禄、半禄","t":"rule"},{"q":"象的三种运用里，食神合印，食神表思想、印代表文章，合起来为思想文化，属于哪一种？","opts":["合象","共象","带象","借象"],"ans":0,"exp":"合象是天干五合、地支六合后两个字互相定义；共象是干支象与十神象配合，带象是干带支或支带干。","sec":"六、象的三种运用","t":"diff"},{"q":"盲派学科对应中，酉金（有时也有申金）对应哪一科？","opts":["数学","物理","语文","化学"],"ans":1,"exp":"戌亥为数学；丙丁火为语文；戌未为化学；酉金为物理，申金有时也是。","sec":"五、十二支之象","t":"rule"}]},{"n":91,"level":"高级","title":"宫位、十神、神煞类象深化","qs":[{"q":"月柱与日柱相合、相冲，分别主什么？","opts":["相合相冲都主离开老家","相合主搬家，相冲主不动","相合离开老家，相冲离不开祖籍","相合离不开祖籍，相冲离开老家"],"ans":3,"exp":"月为祖籍、家乡，日为现在的居所；月日相合离不开祖籍，月日相冲肯定离开老家。","sec":"一、四柱宫位总表","t":"rule"},{"q":"看外界对你的评价与看你内心世界，各看天干还是地支？","opts":["外界评价看天干，内心世界看地支","两者都看地支","两者都看天干","外界评价看地支，内心世界看天干"],"ans":0,"exp":"天干表外，地支表内：天干看外界评价，地支看家庭内部关系、内心世界。","sec":"宫位的用法","t":"rule"},{"q":"日支被流年地支穿了一下，通常应什么事？","opts":["祖籍老家的亲戚出事","犯小人，且是关系最密切的人","晚辈下属犯小人","远方来的小人，关系疏远"],"ans":1,"exp":"日支为与自己最近的人，日支来穿一下就是犯小人，并且是与自己关系最密切的人。","sec":"宫位的用法","t":"calc"},{"q":"官杀在盲派里代表什么，不代表什么？","opts":["代表官司刑伤，不代表职务","代表丈夫情人，不代表权力","代表职务权力，不代表官非桃色","代表职务权力，也直接代表官非"],"ans":2,"exp":"官杀代表职务、地位、权力，不代表官非、官司、盗贼、疾病、桃色，那些要靠组合判断。","sec":"官杀","t":"rule"},{"q":"官杀制化得不好时，一般按什么看？","opts":["当食伤看","当比劫看","当印看","当财看"],"ans":3,"exp":"官杀共象之一：官杀制化不好当财看。","sec":"官杀","t":"rule"},{"q":"「正官为夫、偏官为情人」这种说法，盲派怎么看？","opts":["不对，要看宫位，七杀得正位以夫看","对，正官永远是夫","不对，要看有无印星","对，偏官永远是情人"],"ans":0,"exp":"要看宫位：七杀得正位以夫看，正官得宾位为桃花。","sec":"官杀","t":"diff"},{"q":"十神中哪一个与其他十神不同，是越旺越好？","opts":["正财","食神","正印","正官"],"ans":1,"exp":"食神不怕旺，越旺越好，出现在哪都好，只怕被克；其他十神太重多为毛病。","sec":"食伤","t":"rule"},{"q":"盲派说八字里的禄，是什么？有什么忌讳？","opts":["财星在地支，不可被合","印星在地支，不可被穿","比肩在地支，不可被刑冲","比肩在地支，最喜被刑冲"],"ans":2,"exp":"禄是比肩在地支的体现，表示亲历亲为；八字见禄不能被刑冲，禄冲、刑、破、穿、墓都不好。","sec":"禄","t":"rule"},{"q":"羊刃的天干范围是怎样的？","opts":["只有甲丙庚壬四干有刃，阴干也可借用","阴干有刃，阳干无刃","阴阳干都有刃","阳干有刃，阴干无刃"],"ans":3,"exp":"阳干见阴的劫财为羊刃，所以阳干有刃、阴干无刃；羊刃一定要制服。","sec":"羊刃","t":"rule"},{"q":"盲派说墓库象，财星入墓、伤食入墓分别象什么？","opts":["财墓为银行，伤食墓为学校或庙宇","财墓为学校，伤食墓为权力中心","财墓为权力中心，伤食墓为军团","财墓为军团，伤食墓为银行"],"ans":0,"exp":"羊刃墓为军团，伤食墓为学校或庙宇，伤杀墓为权力中心（组织部），财墓为银行。","sec":"墓库","t":"xiang"},{"q":"六亲落在空亡上，什么情况下有毛病？","opts":["旺衰都有毛病","衰则有毛病，旺则没事","旺则有毛病，衰则没事","旺衰都没事"],"ans":1,"exp":"旺喜空，衰不喜空；六亲临空亡，衰有毛病，旺没事。","sec":"空亡","t":"rule"},{"q":"出生时辰为子或午，兄弟姐妹的数量一般如何断？","opts":["独一个，多则差三岁以外","两三个，多则五个","一个，多则两个","两个，月旺四个"],"ans":2,"exp":"子午一个多则两个；卯酉两个月旺四个；寅申巳亥二三个多则五个；辰戌丑未独一个。","sec":"四、宫位的应用：兄弟姐妹与面形","t":"calc"}]},{"n":92,"level":"高级","title":"财命的高级断法","qs":[{"q":"局中财星没有原神，按盲派本体系口径先怎么看？","opts":["先当忌神看，必须去掉；去不了才用","先当闲神看，不管不问","先看旺衰，身旺才取财","先当用神看，有财就用"],"ans":0,"exp":"财官无原神或不成气势，先当忌神看；去不了就要用；用也用不上是贱命。","sec":"一、有财与发财的基本判断","t":"rule"},{"q":"天干虚透的财与地支有根的实财，哪个算财？","opts":["虚财、实财都算财","实财为财，虚财不为财","虚财为财，但须被合住","虚财为财，实财反主辛劳"],"ans":1,"exp":"虚财不为财，实财才为财；但财虚被比劫克合主大富，是另一层意思。","sec":"一、有财与发财的基本判断","t":"diff"},{"q":"时上见财与刃头财，分别主什么？","opts":["时上财主风险之财，刃头财主财进财出","两者都主辛苦求财，毫无区别","时上财主财进财出，刃头财主风险之财","时上财主稳定积累，刃头财主祖业之财"],"ans":2,"exp":"时上见财为门户财，财进财出；财在羊刃头上是风险之财。","sec":"一、有财与发财的基本判断","t":"diff"},{"q":"财入库而无刑冲，能不能发财？","opts":["能，财入库就是积累","能，大运合库也算发","能，库里财会自行出来","不能，财临库不冲不发"],"ans":3,"exp":"财临库不冲不发；而且要冲得干净、制得彻底才有用。","sec":"一、有财与发财的基本判断","t":"rule"},{"q":"下列哪一种结构是发大财的一种？","opts":["主位有财，生到宾位的官，再被宾位之物制住","宾位有财，生到主位的印，再被宾位之物制住","主位有官，生到宾位的财，再被主位之物制住","主位有财，生到宾位的食伤，再被主位之物制住"],"ans":0,"exp":"主位财生宾位官，再被宾位的东西制住这个官，是发大财的结构之一。","sec":"一、有财与发财的基本判断","t":"rule"},{"q":"财星虚透，又被比劫克合，一般断什么？","opts":["主破财","主大富","主婚姻有变","主平常，不富不贫"],"ans":1,"exp":"财做忌神、财星虚弱被比劫制则主富有，财星虚透遭比劫克合者主大富。","sec":"三、伤官当财、劫财去财","t":"rule"},{"q":"用劫财去财取得的财，取财方式多是什么？","opts":["技术手艺，凭本事吃饭","勤劳经营，稳扎稳打","股票、赌博、中介，非勤劳、非正当","继承祖业，守成不变"],"ans":2,"exp":"劫财制财者多为做股票、赌博、中介、不择手段、不劳而获，八字无印尤其如此。","sec":"三、伤官当财、劫财去财","t":"rule"},{"q":"局中官杀被制，但制得不干净，该按什么看？","opts":["官杀当印看","官杀当食伤看","官杀当比劫看","官杀当财看"],"ans":3,"exp":"杀制不净当财看，官杀无制、官入墓、官多财少也当财看。","sec":"三、伤官当财、劫财去财","t":"calc"},{"q":"伤官在盲派里当财看，是什么性质的财？","opts":["谋为之财，野心、投机、风险，故财大","辛苦的禄财，来源于出体力","稳定的正财，来源于工资薪水","祖上的遗财，来源于家业"],"ans":0,"exp":"伤官是所苦心追求的东西，是谋为之财，带野心投机风险，所以财大。","sec":"三、伤官当财、劫财去财","t":"diff"},{"q":"官戴财帽与财戴官帽，各以什么为主？","opts":["官戴财帽以官为主；财戴官帽以财为主","官戴财帽以财为主；财戴官帽以官为主","两者都以官为主，只分大小","两者都以财为主，只分公私"],"ans":1,"exp":"戴什么帽子以什么为主；官戴财帽又没有用官去官的是私企。","sec":"四、财库的冲刑与制财、取财方式","t":"diff"},{"q":"以智力取财的命，典型的结构是什么？","opts":["七杀带印，靠权势取财","财星带官，靠官位取财","伤官带比肩，是自己的才智，能生财","劫财带禄，靠出体力取财"],"ans":2,"exp":"伤官星带比肩，说明是自己的才智，伤官生财，所以靠智力取财。","sec":"五、以智力取财（伤官星带比肩）与其他","t":"rule"}]},{"n":93,"level":"高级","title":"官命、职业与学历的高级断法","qs":[{"q":"按盲派，官杀与印在官命里各主什么？","opts":["官杀主钱财，印主职务","官杀主职务，印主权柄","官杀主权柄，印主职务","官杀主名声，印主学历"],"ans":1,"exp":"看官贵着重看官杀与印：官杀主职务，印主权柄；官杀及印不管作忌神还是用神都必须有根。","sec":"1. 官命的核心与根","t":"rule"},{"q":"主位的印或财做功，什么结构才可能是当官有权？","opts":["印或财在年干，去主位的字","印或财在月令，克日主","印或财在日支，去宾位的字","印或财在时干，合日主"],"ans":2,"exp":"印或财必须在日支（主位），去宾位的字才可能为权力；其他位置多是做生意的。","sec":"1. 官命的核心与根","t":"rule"},{"q":"羊刃合杀，在职业上主什么？","opts":["管文教，学校、媒体","管医药，医院、卫生","管财务，银行、国企","掌兵权，公安、军队"],"ans":3,"exp":"羊刃主枪，合杀即掌兵权，为公安、军队一类。","sec":"2. 官的职业分类（总表）","t":"rule"},{"q":"伤官合杀与劫财羊刃制官，各对应什么机构？","opts":["伤官合杀为检察反贪，劫财羊刃制官为纪检","伤官合杀为纪检，劫财羊刃制官为检察反贪","两者都是检察院、法院","伤官合杀为公安，劫财羊刃制官为军队"],"ans":0,"exp":"伤官合杀＝制贪官的（检察机关）；劫财羊刃制官＝纪检委。","sec":"2. 官的职业分类（总表）","t":"diff"},{"q":"伤官泄羊刃，一般表示从事什么？","opts":["管钱财，经营买卖","主笔主文，耍笔杆子","做技术，医药研发","掌兵权，带枪执法"],"ans":1,"exp":"伤官泄羊刃主笔主文；如政法委处长不带枪，是文官。","sec":"二、公检法与军队","t":"rule"},{"q":"杀的四种状态，按官命论由什么对应什么才对？","opts":["制化为贵气，制尽为名气，虚为当官，制不好当财","制化当官，制尽贵气，虚为当财，制不好名气","制化为贵气，制尽当官，虚为名气，制不好当财","制尽为贵气，制化当官，虚为名气，制不好当财"],"ans":2,"exp":"杀有制化为贵气，杀制尽为当官，杀虚为名气，杀制不好当财看。","sec":"3. 官的位置与大小","t":"step"},{"q":"制用与化用相比，做官的效率如何？","opts":["化用效率高，制用级别不大","制用化用效率相同","制用只能做武职，化用才是文职","制用效率高，化杀生身级别不大"],"ans":3,"exp":"化用不如制用效率高，化杀生身级别不大；以库取权最大。","sec":"3. 官的位置与大小","t":"diff"},{"q":"按盲派，老师与校长的结构区别是什么？","opts":["印拱食伤库为老师，印上戴官帽为校长","官杀制伤官为老师，印生官为校长","印拱食伤库为校长，印上戴官帽为老师","食伤生财为老师，财戴官帽为校长"],"ans":0,"exp":"印有用拱了食神库、伤官库一般做老师；印上戴官帽，则为校长。","sec":"三、文教类：老师的看法","t":"rule"},{"q":"财戴官帽用官去官与不用官去官，分别是什么？","opts":["用官去官为私企，不用官去官为国企","用官去官为国企，不用官去官为私企","两者都是国企，只是官职大小不同","两者都是私企，只是用印不同"],"ans":1,"exp":"财戴官帽用官去官是国企；不用官去官是私企；官戴财帽则以财为主。","sec":"四、国企与私企：官的帽子","t":"diff"},{"q":"按盲派，印星虚透与学历是什么关系？","opts":["印虚透一律有文凭","印虚透与学历无关，只看财","印为用虚透无文凭，为忌虚透有文凭","印为用虚透有文凭，为忌虚透无"],"ans":2,"exp":"印星虚透，用神虚透没文凭；印为忌虚透有文凭，或为忌去印也有文凭。","sec":"五、学历的判断","t":"rule"},{"q":"财星对学习一般是什么作用？除印太重要财克印之外","opts":["印弱时才忌，印旺时更不利","无关，学历只看食伤","最喜，财生官印助学业","最忌，心乱学不进去"],"ans":3,"exp":"财为欲望之星，一般学习最忌；只有印星太重要财克印时，反有学习上进的意思。","sec":"五、学历的判断","t":"rule"}]},{"n":94,"level":"高级","title":"婚姻宫、副宫、配偶星与结婚应期","qs":[{"q":"盲派定义「结婚」，同居关系须满足什么条件才算？","opts":["领了结婚证并办过婚礼才算","只要有同居事实就算结婚","以结婚为目的、同居满半年","同居满一年以上才算结婚"],"ans":2,"exp":"以婚姻为目的、共同生活超半年算结婚；婚前同居很短的不算，但若最终结为夫妻，之前同居也算应期的一部分。","sec":"一、结婚的定义与看婚姻的三个件","t":"rule"},{"q":"副宫同柱所配之字就是配偶星，若这个字是印或比劫，婚姻怎么断？","opts":["主早婚，且夫妻感情好","婚姻平稳，无需另看别处","主配偶有才华，婚姻吉","婚姻不好"],"ans":3,"exp":"配偶星有多少算多少；所配若是印、比劫，婚姻不好。","sec":"一、结婚的定义与看婚姻的三个件","t":"rule"},{"q":"盲派看婚姻，「宫」与「星」的关系，怎样才算成「婚姻组合」？","opts":["宫星有关联（合生拱同柱入库）才成","宫星必须相冲才能成婚姻组合","只要命中有配偶星就成婚姻组合","宫星必须同在天干才能成组合"],"ans":0,"exp":"宫是位、星是人；宫星无关联则只是虚的对象。","sec":"一、结婚的定义与看婚姻的三个件","t":"diff"},{"q":"婚姻的虚实长短，天干与地支、原局与大运各怎么看？","opts":["天干实为长，地支虚为短，运婚过运仍在","天干虚为短或桃花，地支实为长，运婚过运无","天干地支皆为长，运婚过运仍在","天干虚为长，地支实为短，运婚过运仍在"],"ans":1,"exp":"天干虚、主短或桃花运；地支实、主长；因大运而成的婚姻，过运则无。","sec":"一、结婚的定义与看婚姻的三个件","t":"diff"},{"q":"夫星与夫宫在原局本已相合住，要引动它成为结婚应期，用什么方式？","opts":["用克去伤它","用刑去拆开","用冲去引动","再用一个合去加固"],"ans":2,"exp":"合动是应期的第一法；原局已合住的，须用冲来引动。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"原局有刑克、隔住婚姻的字，应期怎么应？为何伤官运也可能结婚？","opts":["阻碍字强旺的流年才能够结婚","有阻碍字就一生都不能结婚","伤官运不能结婚，只能等官运来","坏掉阻碍字为应期，伤官运也可结"],"ans":3,"exp":"坏阻碍应：阻碍字被坏掉即为应期，所以伤官运也可因去阻碍而结。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"大运带来不利婚姻的信息（如刑坏夫宫之运），结婚应期怎么取？","opts":["过运后第一个合适的流年完婚","该运内即使不合适也会勉强结","仍在该大运的合适流年结婚","要等到下一个十年大运的中间"],"ans":0,"exp":"不利婚姻的大运要过运后第一个合适流年才完婚，运中不再讲流年。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"按应期干支对应表，流年出现天干「庚」，等于动了八字中的哪个地支？","opts":["戌","申","酉","亥"],"ans":1,"exp":"对应表：庚对应申；酉对应辛。","sec":"二、结婚应期的五条规则","t":"calc"},{"q":"流年逢寅、卯，通过合局、墓气到位，可以引动八字中的哪个库？","opts":["戌","丑","未","辰"],"ans":2,"exp":"申酉引丑，亥子引辰，寅卯引未，巳午引戌，金引丑、水引辰、木引未、火引戌。","sec":"二、结婚应期的五条规则","t":"calc"},{"q":"女命伤官本伤夫，却有哪两种情形，伤官运或伤官年反而应结婚？","opts":["印星多而重；印星入他星之墓中","官杀不透干；官杀入日支之库中","比劫多而重；财星入他星之墓中","官杀多而混杂；官杀入他星之墓"],"ans":3,"exp":"官杀多、混杂，或官杀入墓于他星，均可应伤官，但婚姻多不太好。","sec":"三、基本应期命例","t":"rule"},{"q":"同一颗夫星既能被流年冲动、又能被合动时，取哪一种引法？","opts":["看引动后是生助还是反伤，取生助","取与日主相合的那一种引法来用","一律取冲，因为冲的力量更大","一律取合，因为合更像是婚姻象"],"ans":0,"exp":"如丙寅年寅冲申却生旺伤官反克官，不取；取巳申合动。看引动后是生助还是反伤。","sec":"三、基本应期命例","t":"diff"}]},{"n":95,"level":"高级","title":"恋爱同居、破身与淫乱卖身命","qs":[{"q":"按盲派，女命以什么为身体？破身的时间怎么定？","opts":["以食伤为身体，食伤一现就破身","以夫星为身体，夫星入库才破身","以印为身体，印被合之时即破身","以禄为身体，禄被破时破身"],"ans":3,"exp":"女命以禄为身体，禄被破的时间就是破身的时间。","sec":"2. 女命：禄为身体，破禄即破身","t":"rule"},{"q":"女命破禄的两种方式是什么？","opts":["食伤间泄气式冲破，或官杀冲禄","官杀合禄，或食伤合印","比劫夺财，或印被财克","伏吟禄神，或禄神入墓库"],"ans":0,"exp":"破禄有两种：泄气式的破（子破卯、卯破午之类），以及官杀冲禄。","sec":"2. 女命：禄为身体，破禄即破身","t":"diff"},{"q":"早恋的基本信号，女命与男命各看什么？","opts":["女命印旺，男命官杀重","女命见禄无印，男命比劫重","男女都看食伤旺","女命比劫重，男命见禄无印"],"ans":1,"exp":"女命见禄无印易破身；男命比劫重易早恋；财（男）或官杀（女）在年月也主早恋。","sec":"1. 总纲","t":"diff"},{"q":"天干虚透的婚前对象，若坐在比劫地支上，最终怎样？","opts":["会成为合作伙伴","会成为自己的配偶","会成为别人的老公（老婆）","会成为同居对象但不分手"],"ans":2,"exp":"天干虚透的对象多为婚前对象；其坐比劫地支，最终是别人的人。","sec":"1. 总纲","t":"rule"},{"q":"婚前对象要发展到同居，需要什么条件？","opts":["这个对象坐在日主之禄上","这个对象在年柱","这个对象与印星相合","这个对象与夫妻宫有关联"],"ans":3,"exp":"这类对象与夫妻宫有关联，才会发展到同居。","sec":"1. 总纲","t":"rule"},{"q":"女命的日柱（或其他柱）干支一气，如丁未，表示什么？","opts":["没有过别人，纯洁","身体不好","桃花旺盛","多次婚姻"],"ans":0,"exp":"干支一气表示没有过别人；两个字联成一体（如两个巳合申）则婚前多个同居对象。","sec":"3. 其他提示","t":"rule"},{"q":"女命巳（禄）遇申，成巳申合，按盲派怎么论？","opts":["巳为食申为伤，食伤相合","巳为身体申为财，以身换财","巳为财申为身体，以财养身","巳为官申为印，官印相生"],"ans":1,"exp":"禄神遇合易失身；巳为禄身体、申为财，合则以身换财。","sec":"2. 女命：禄为身体，破禄即破身","t":"calc"},{"q":"女命官杀入墓、墓不开，表示什么？","opts":["男人少而专一，婚姻很稳定","丈夫有钱，主夫荣妻又贵","男人多，来的都是别人的","丈夫早亡，终身无夫无婚"],"ans":2,"exp":"夫宫（官杀）入墓不开：男人多，而且来的都是别人的男人。","sec":"1. 总则","t":"rule"},{"q":"淫乱命中，丑落在时上是什么象？","opts":["财库，积蓄钱财所在之处","阳中之阳，男性象征，公开之事","门户，主出外远行之事","阴中之阴，女性器官，偷偷之事"],"ans":3,"exp":"阴中之阴（丑）落时上表示女性器官、偷偷干的事；被刑冲穿就开始做功。","sec":"1. 总则","t":"xiang"},{"q":"女命禄或禄加伤食逢冲穿，并用来取财，按盲派是什么象？","opts":["以身体取财，卖淫之意","以权力取财，当官之象","以才艺取财，艺人之象","以经营取财，生意人之象"],"ans":0,"exp":"禄神，或禄加伤食神，逢冲穿有性爱之意，以此做功取财，就是卖淫之意。","sec":"1. 总则","t":"rule"},{"q":"同是禄伤相连的女命，歌唱家与卖身命的分野是什么？","opts":["禄神是否坐在日支","夫宫是否单一稳定","伤官是否透出天干","是否有印星来制伤官"],"ans":1,"exp":"夫宫只有一个且夫星夫宫相拱稳定的，是歌唱家；夫宫多现的，是卖身命。","sec":"2. 女命卖身命例","t":"diff"}]},{"n":96,"level":"高级","title":"男命多婚组合","qs":[{"q":"男命多婚，婚姻顺次按柱怎么排？","opts":["年柱为早，时柱为晚，依次排第","月柱为头婚，其余不分先后","日柱为头婚，年时柱依次再婚","时柱为早，年柱为晚，依次排第"],"ans":0,"exp":"婚姻顺次：年柱为早，时柱为晚，依次排第。","sec":"一、多婚的顺次与总原则","t":"step"},{"q":"盲派看婚姻，天干与地支的配偶，长短如何分？","opts":["天干实者为长；地支虚者为短或主桃花","天干虚者为短或主桃花；地支实者为长","天干虚者为长；地支实者为短","天干地支不分长短，只看宫位"],"ans":1,"exp":"天干虚者为短，或主桃花运；地支实者为长。大运因而成的婚姻，过运则无。","sec":"一、多婚的顺次与总原则","t":"diff"},{"q":"盲派看男命婚姻，配偶星怎么认定？","opts":["先看月令，月令所藏的财即配偶星，只算一个","先看日干，日干所合之字即配偶星，只算一个","先看副宫，副宫同柱所配之字即配偶星，有多少算多少","先看时柱，时柱的财即配偶星，按早晚论"],"ans":2,"exp":"先看副宫，再看副宫同柱所配之字，这个字就是配偶星，有多少算多少；若为印、比劫，则婚姻不好。","sec":"一、多婚的顺次与总原则","t":"rule"},{"q":"男命妻宫不多现，但妻宫被合坏或刑坏，按盲派怎么论？","opts":["晚婚但白头到老","一定无婚姻","必有婚外情","一婚不到头"],"ans":3,"exp":"五种多婚组合之二：妻宫虽不多现，但妻宫被坏（合坏、刑坏、穿坏），一婚不到头。","sec":"男命多婚的五种组合","t":"calc"},{"q":"妻宫被坏，与妻宫没坏而妻星被坏又出现新妻星，两种情形哪句对？","opts":["前者一婚不到头；后者因新妻星出现容易多婚","两者都只主一婚，但有桃花","前者容易多婚；后者一婚不到头","两者都主不婚"],"ans":0,"exp":"妻宫被坏（组合2）是一婚不到头；妻宫没坏而妻星被坏，加上新的妻星出现（组合3）则容易多婚。","sec":"男命多婚的五种组合","t":"diff"},{"q":"「妻星多合」，按盲派口诀如何论婚？","opts":["合一次减一个，多合则无妻","合一次加一个，或因合而离开","合与婚无关，只看冲刑","合一次加一个，合多了也只算一婚"],"ans":1,"exp":"男命多婚组合之四：妻星多合，合一次加一个；或因合而离开。","sec":"男命多婚的五种组合","t":"rule"},{"q":"口诀「宫星双合，两次婚姻」是指什么情形？","opts":["一星一宫，第一次合到位，第二次又被合走","一星两宫，两次都合到位，所以白头到老","一星两宫或一宫两星，第一次合没到位，第二次才到位","一宫两星，第一次到位，第二次冲开"],"ans":2,"exp":"一个妻星对应两个妻宫（或反之），第一次合没到位，第二次合才到位，命该两次婚姻。","sec":"两条断离、断再娶的辅助诀","t":"rule"},{"q":"盘中没有透出丙丁劫财、羊刃、比肩，只有两个禄，按盲派怎么论？","opts":["两个禄各当一妻，主多婚","两个禄主劫财夺妻，主离婚","两个禄主妻宫被冲，主婚姻不稳","两个禄只表示自己，不表示离婚"],"ans":3,"exp":"没有透出丙丁劫财羊刃比肩，则两个禄只表示自己；凡劫财、羊刃透干对婚不好。","sec":"两条断离、断再娶的辅助诀","t":"diff"},{"q":"土作妻星且满盘财星，逢刑冲，按盲派怎么论婚？","opts":["反主一妻","必离婚，不再娶","刑冲越多，妻越多","主多桃花，婚外情多"],"ans":0,"exp":"凡土作妻星之命，逢刑冲反主一妻；夫妻宫不能刑坏，土互相牵制。不刑冲的土财星才有可能表示桃花。","sec":"三、反例：满盘财星逢刑冲，反主一妻","t":"diff"}]},{"n":97,"level":"高级","title":"女命多婚组合","qs":[{"q":"盲派论女命婚姻，夫星和夫宫分别取什么？","opts":["财星为夫星，日支为夫宫","官杀为夫星，日支为夫宫","食伤为夫星，日支为夫宫","官杀为夫星，月支为夫宫"],"ans":1,"exp":"女命以官杀为夫星、日支为夫宫；多婚结构都是围绕星、宫的好坏看的。","sec":"一、女命多婚的组合","t":"rule"},{"q":"夫宫没坏而夫星被坏，又有新的夫星出现，与夫宫虽不多现但夫宫被坏，各主什么？","opts":["前者一婚不到头；后者容易多婚","两者都主终身不婚","前者容易多婚；后者一婚不到头","两者都只主丈夫有外遇，不离婚"],"ans":2,"exp":"夫星被坏又有新夫星是多婚；夫宫被合坏、刑坏、穿坏则一婚不到头。","sec":"一、女命多婚的组合","t":"diff"},{"q":"女命夫星被比劫包、被比肩合走，主什么？","opts":["婚姻美满，比劫帮夫","丈夫早亡，守寡不再嫁","丈夫发财，但夫妻缘薄","丈夫必有外遇，初婚亦离"],"ans":3,"exp":"比劫争夫，夫星与宫的联系再好，初婚也离。","sec":"一、女命多婚的组合","t":"rule"},{"q":"盲派说的「关财门」是怎么回事？","opts":["财是官杀之原神，财被冲坏或劫克，必多婚","印被财克，官杀无生，必多婚","官杀被冲坏，财无依靠，必多婚","财被合住，官杀不透，必晚婚"],"ans":0,"exp":"财为夫星（官杀）的原神，财星被冲坏、被劫克，夫星无源，称关财门。","sec":"一、女命多婚的组合","t":"rule"},{"q":"「一星两宫、双宫双星」，主几次婚姻？","opts":["三次，因多现必刑","两次，第一次没合到位","一次，因星宫相合","两次，第二次没合到位"],"ans":1,"exp":"夫宫或夫星多现，第一次没合到位，主两次婚姻。","sec":"一、女命多婚的组合","t":"rule"},{"q":"夫宫辰在日、时伏吟，这种两辰并见是否表示二婚？","opts":["表示夫外遇但不离","表示二婚","不表示二婚","表示三婚"],"ans":2,"exp":"双宫主二婚，但辰在日时伏吟则不表示二婚。","sec":"一、女命多婚的组合","t":"calc"},{"q":"夫星与夫宫之间两穿、一破，一共几婚，第几次才稳？","opts":["共两婚，第二次才好","共三婚，第二次才好","共四婚，第三次才好","共三婚，第三次才好"],"ans":3,"exp":"两穿离两次，破一次，共三婚；刑的能量耗尽后第三次婚姻才好。","sec":"一、女命多婚的组合","t":"calc"},{"q":"夫宫合入夫星之墓，怎么断？","opts":["夫不死则离，把婚姻埋了","夫宫稳固，只是不爱说话","夫旺而不离，库中有财","只主晚婚，婚后美满"],"ans":0,"exp":"夫宫合入夫星之墓，婚姻被埋；夫不死则离。","sec":"二、典型命例","t":"rule"},{"q":"夫星多合（合一次加一个，或因合而离开），主什么？","opts":["主晚婚，合则稳固","主多婚，合一次加一个夫","主不婚，合则孤独","主丈夫发财，合则助夫"],"ans":1,"exp":"夫星多合，合一次加一个，或因合而离开，是多婚组合之一。","sec":"一、女命多婚的组合","t":"rule"},{"q":"女命合财，对婚姻有多大意义？","opts":["合财即合夫，主婚成","合财主夫有外遇","没有多大意义","合财主婚姻稳固"],"ans":2,"exp":"财是官杀的原神，女命合财本身对婚姻的意义不大，要看星宫刑穿的变化。","sec":"三、本章小结","t":"rule"}]},{"n":98,"level":"高级","title":"婚外情与桃花（男女命）","qs":[{"q":"按盲派，男命婚外情的基本格局是什么？","opts":["妻宫被冲，有副妻宫现","妻宫稳定，有伤官透干","妻宫稳定，有副妻宫现，再有配偶星相配","财星多，妻宫入墓"],"ans":2,"exp":"男命婚外情：妻宫相对稳定，有副妻宫出现，再有配偶星与之相配。","sec":"规则","t":"rule"},{"q":"男命婚外情有可能的前提是什么？","opts":["只要财多就有","只要伤官旺就有","一般须官杀旺，官杀制比劫","一般须比劫旺，无比劫财再多也无用"],"ans":3,"exp":"比劫主占有欲，一般必须比劫旺婚外情才有可能；如无比劫，再多财也无用。","sec":"规则","t":"rule"},{"q":"男命比劫旺而七杀透干制比劫，桃花如何论？","opts":["自我控制强，不一定有桃花","比劫旺必有桃花，杀只增加数量","七杀制比劫，桃花更多更乱","七杀透干则必无桃花且不婚"],"ans":0,"exp":"有七杀透干制比劫的，自我控制强，不一定有桃花；不是所有比劫旺的人都有桃花。","sec":"规则","t":"diff"},{"q":"男命伤官桃花与比劫桃花的区别是？","opts":["伤官桃花占有欲强，比劫桃花放任","伤官桃花情份不深，比劫桃花多而没感情","伤官桃花缠身，比劫桃花专一","两者都情深，只是数量不同"],"ans":1,"exp":"伤官主放任，桃花不缠身、用情不专一；比劫主占有，桃花多而没多少感情。","sec":"规则","t":"diff"},{"q":"男命时上有丑库而不被冲开，象义是什么？","opts":["主妻子早逝","主不近女色，无桃花","库里有很多女人","库里藏着一个固定情人"],"ans":2,"exp":"特殊象：时上库不开（如丑），里边有很多女人；库靠大运流年引动。","sec":"特殊象","t":"xiang"},{"q":"男命伤官在宾位、头上盖着庚（比劫），象义是什么？","opts":["主无桃花","是自己的正妻","是自己的情人且专情","是别人的女人"],"ans":3,"exp":"伤官桃花不缠身，伤官在宾位、头顶庚比劫，是别人的女人；庚坐戌也主外边的女人。","sec":"特殊象","t":"xiang"},{"q":"男命八字中的戌，桃花象上代表什么？","opts":["色情场所","寿元","正式妻子","贤惠之妻"],"ans":0,"exp":"特殊象：戌为色情场所；庚坐戌主外边的女人。","sec":"特殊象","t":"xiang"},{"q":"男命官星化财，与正常财星相比，桃花多少如何？","opts":["与正常财星相同","比正常财当桃花的命多得多","比正常财星少得多","官星化财则必无桃花"],"ans":1,"exp":"特殊象：官星化财，比正常财当桃花的命多得多。","sec":"特殊象","t":"rule"},{"q":"女命婚外情的规则，下列哪一条正确？","opts":["女命夫宫被冲才有桃花","女命见伤官再逢比劫，必有桃花","女命见禄再逢财官，容易有桃花","女命见印再逢官杀，容易有桃花"],"ans":2,"exp":"女命：夫宫稳定有副夫宫现，再有配偶星相配；有另外夫星拱入夫宫；见禄再逢财官容易有桃花。","sec":"规则","t":"rule"},{"q":"女命官星的退气库（辰、戌、未之类）取象为桃花，意思是？","opts":["是已故的丈夫","是将来的婚姻","是正式的丈夫","不是正式的丈夫"],"ans":3,"exp":"官星退气为桃花，意思是不是正式的丈夫；入墓不开则多，且是别人的男人。","sec":"补充象","t":"xiang"}]},{"n":99,"level":"高级","title":"包局婚姻判断","qs":[{"q":"按盲派，包局婚姻有哪三种基本结构？","opts":["星入墓、宫入墓、星宫同入墓","星合宫、宫合星、星宫互相冲","星生宫、宫生星、星宫互相克","星包宫、宫包星、星宫全被他星包"],"ans":3,"exp":"包是一个字被另外的字夹住围住：星在宫两头、宫在星两头，或星宫一起被别的字围住。","sec":"一、包局的三种基本结构","t":"rule"},{"q":"配偶星包局的婚姻有什么特点？","opts":["被配偶看得紧，不易离婚，离则代价大","配偶不管事，婚姻宽松","容易离婚，离婚代价小","配偶多外遇，但必离"],"ans":0,"exp":"包局婚姻自己被看得紧，容易累也不容易离婚，一旦要离要付出很大代价。","sec":"配偶星包局婚姻的三个特点","t":"rule"},{"q":"六合式的包局，婚姻是什么情形？","opts":["合住后配偶外出，聚少离多","合得紧看得紧，婚姻痛苦","合而不紧，一说就离","合则和睦，婚姻美满"],"ans":1,"exp":"六合式包局合得紧看得紧，晚上到点必须回去，所谓结婚等于坐牢。","sec":"配偶星包局婚姻的三个特点","t":"rule"},{"q":"以亥为妻星，两头各有一亥成包局，天干分别配哪组时包局不成立（反局）？","opts":["壬亥与庚亥","甲亥与丙亥","辛亥与乙亥","己亥与丁亥"],"ans":2,"exp":"两头字天干相克，象反了不是同一人，包局不成；其余几组天干相生，仍是同一人。","sec":"反局：两个同字不是同一人","t":"calc"},{"q":"包局出现反局（两头字象相反），婚姻如何？","opts":["只主吵架，不会离婚","要等冲夫宫的大运才离","包局更牢，婚姻离不了","包局不成立，婚姻必离"],"ans":3,"exp":"包局的前提是两头字象相同可视为同一人；象反则不是一个人，包局不成，婚姻必离。","sec":"反局：两个同字不是同一人","t":"rule"},{"q":"包局婚姻想离，下列哪个才是原局包局被破开的方式？","opts":["羊刃克妻大运或冲破夫宫的流年","流年再合一个配偶星","印星合入日主","大运生助配偶星"],"ans":0,"exp":"冲破夫妻宫（羊刃克妻之大运、冲夫宫流年）破了原局包局，终能离；六合式包局可被六合破暗合。","sec":"二、星包局命例（离不了）","t":"diff"},{"q":"女命官杀被食伤、禄印等包局，婚姻怎么论？","opts":["婚姻必离，包局为破","婚姻稳不会离，夫宫受破也只主手术伤灾","婚姻稳，但丈夫必外遇","婚姻不稳，因食伤克官"],"ans":1,"exp":"官星被包局稳，虽夫宫被穿被破（丑午穿、卯午破），也只主丈夫手术或伤灾，不离婚。","sec":"四、官杀包局、官局不离","t":"rule"},{"q":"盲派判断“被人包养”的口诀是什么？","opts":["女命八字官杀混杂，比劫包局","女命八字无印星，食伤包局","女命八字无官杀，财星包局","女命八字无财星，官星包局"],"ans":2,"exp":"女命无官杀，财星（或伤官带财）包局者被人包养；包她的人多带比劫库、有家室。","sec":"五、财包局：被人包养的组合","t":"rule"},{"q":"被包养的命，包养她的男人一般有什么特点？","opts":["官职高，但无子女","年龄小，无家室","出身贫寒，无钱财","带比劫库，有家室"],"ans":3,"exp":"包她的人多带比劫库（如戌中丁、未木库），是有家室的人。","sec":"五、财包局：被人包养的组合","t":"rule"}]},{"n":100,"level":"高级","title":"配偶情况判断（二婚、偏房、年龄差、父母反对与招婿）","qs":[{"q":"夫星前面有比劫在前争夫，按盲派怎么断？","opts":["配偶前面有过婚姻，或自己二婚","自己是偏房二奶","夫妻缘薄，必定离婚","配偶比自己年龄大"],"ans":0,"exp":"夫星前有比劫争夫（比劫在前，争在前边），断配偶前面有过婚姻或自己二婚。","sec":"一、配偶是否二婚（找二婚）","t":"rule"},{"q":"下列哪项表示配偶原是别人的？","opts":["夫星得正位坐夫宫","夫星入他人之库","夫宫包夫星","夫星坐禄，不被冲克"],"ans":1,"exp":"夫星或妻星从他宫出、夫星入他人之库，都表示配偶原是别人的。","sec":"一、配偶是否二婚（找二婚）","t":"rule"},{"q":"做偏房的典型组合是？","opts":["官杀混杂，又见正印","伤官见官，又见偏财","比劫争夫，又见偏印（枭）","比劫争夫，又见正印"],"ans":2,"exp":"比劫争夫又见偏印做偏房；正印是明媒正娶之意。","sec":"组合","t":"rule"},{"q":"女命夫宫穿到正印，怎么论？","opts":["偏房，但必转正","必离婚，不论名分","明媒正娶的正妻","只能是偏房"],"ans":3,"exp":"正印为明媒正娶，被夫宫穿到，所以只能是偏房。","sec":"组合","t":"calc"},{"q":"命中正印、枭都有，怎样论偏房转正？","opts":["破枭变印为转正","破印变枭为转正","合枭入库为转正","枭印俱被比劫争为转正"],"ans":0,"exp":"转正的关键是枭被破而变成印，即「破枭变印」。","sec":"组合","t":"rule"},{"q":"乙丑、辛丑两柱地支同为丑，辨是一个人还是两个人，看什么？","opts":["看月令，同令即同人","看天干，相克相反则为两人","看大运，换运即换人","看地支，同支即同一人"],"ans":1,"exp":"辨别一个人还是两个人，关键看天干；乙丑、辛丑天干象反，是两个人。","sec":"组合","t":"diff"},{"q":"地支的冲与合，各指示什么方向？","opts":["冲是去的方向，合是离开的方向","冲合都是离开的方向","冲是离开的方向，合是去的方向","冲合都是去的方向"],"ans":2,"exp":"地支冲合：冲是离开的方向，合是去的方向。","sec":"组合","t":"rule"},{"q":"男命妻星为亥，年上巳含比劫，巳亥冲；亥卯未三合局，妻宫稳定。妻有外情的情形？","opts":["外情不断，终致丧妻","妻无外情，冲为克妻","外情长期，必离婚","外情短暂偶尔，不会离婚"],"ans":3,"exp":"冲为短暂偶尔之意；亥卯未三合，妻宫稳定，所以妻有别的男人但不会离婚。","sec":"三、配偶有情人（配偶外情）","t":"calc"},{"q":"男命伤官比劫旺，与伤官比劫不旺，分别易找什么年龄的配偶？","opts":["旺的找小的；不旺的找大的","旺不旺都易找大的","旺的找大的；不旺的找小的","旺不旺都易找小的"],"ans":0,"exp":"口诀：男命伤官比劫旺的找小的，伤官比劫不旺找大的。","sec":"四、年龄差：嫁老夫、娶小妻","t":"diff"},{"q":"看配偶年龄：妻星一柱向年上拱，与食神妻星拱入夫宫，各主什么？","opts":["两者都主妻比自己大","向年上拱主妻大；食神拱入主妻小","向年上拱主妻小；食神拱入主妻大","两者都主妻比自己小"],"ans":1,"exp":"年主大，妻星一柱向年上拱，妻比自己大；食神主小，拱入夫宫之食神妻星，找小的。","sec":"四、年龄差：嫁老夫、娶小妻","t":"diff"},{"q":"父母反对婚姻，哪种结构终能成婚，哪种成不了？","opts":["夫宫包夫星与对象被穿，都能成","夫宫包夫星与对象被穿，都不成","夫宫包夫星能成；对象被穿被争不成","对象被穿被争能成；夫宫包夫星不成"],"ans":2,"exp":"父母反对而终能成婚：夫宫包夫星，婚姻没问题；对象被穿、被比肩争，母亲反对得逞，婚不成。","sec":"五、父母反对的婚姻","t":"diff"},{"q":"夫星落在月令，女命嫁出去仍住娘家与招婿，如何区分？","opts":["六合夫宫住娘家；暗合夫宫招女婿","暗合、六合都是招女婿","落在日柱暗合夫宫住娘家","暗合夫宫住娘家；六合夫宫招女婿"],"ans":3,"exp":"口诀：女命月令为娘家，夫星落月令、暗合夫宫者一般嫁出去依然住娘家；如是六合，一般是招女婿。","sec":"六、嫁出去住娘家与招婿入赘","t":"diff"}]},{"n":101,"level":"高级","title":"伤克配偶判断","qs":[{"q":"按盲派，看到命局「伤克配偶」的信息，本质是什么？","opts":["本人命硬，真正克死配偶","配偶本身命中有问题，本人只体现信息","配偶星太弱，需印星来救","配偶宫被大运流年冲坏所致"],"ans":1,"exp":"伤克配偶一定是配偶本身命中有问题，本人命中体现出伤克配偶的信息，并非真是本人克死的。","sec":"一、基本规则","t":"rule"},{"q":"水的墓、绝、死分别落在哪个地支？","opts":["墓在未，绝在巳，死在卯","墓在丑，绝在寅，死在子","墓在辰，绝在巳，死在卯","墓在辰，绝在申，死在午"],"ans":2,"exp":"死墓绝表：水墓辰、绝巳、死卯；金墓丑、绝寅、死子；木墓未、绝申、死午；火（土同）墓戌、绝亥、死酉。","sec":"死墓绝表与互绝","t":"calc"},{"q":"夫星是金（如庚、辛），哪个地支是它的墓、哪个是它的绝？","opts":["墓在戌，绝在亥","墓在辰，绝在巳","墓在未，绝在申","墓在丑，绝在寅"],"ans":3,"exp":"金墓丑、绝寅、死子，夫星为金时宫位见丑为临墓、见寅为临绝。","sec":"死墓绝表与互绝","t":"calc"},{"q":"口诀「互绝」包括下列哪四组？","opts":["寅酉、子巳、卯申、午亥","寅酉、子巳、卯午、申亥","寅卯、子巳、申酉、午亥","寅申、子午、卯酉、巳亥"],"ans":0,"exp":"口诀：寅酉互绝，子巳互绝，卯申互绝，午亥互绝。","sec":"死墓绝表与互绝","t":"rule"},{"q":"男命克妻，哪种劫财最严重？","opts":["午火劫财","申金劫财","寅木劫财","亥水劫财"],"ans":1,"exp":"男命羊刃容易克妻，劫财克妻，以申金劫财最严重。","sec":"一、基本规则","t":"rule"},{"q":"女命克夫的伤官，日主阴阳与伤官阴阳怎样配合才克？","opts":["阴日主见阳伤官克夫，阳日主见阴不克","阴阳日主见任何伤官都克夫","阳日主见阴伤官克夫，阴日主见阳不克","只有阴日主见阴伤官才克夫"],"ans":2,"exp":"阳日主见阴伤官克夫，阴日主见阳不克；阴伤官以乙卯辛酉己丁午及伤官库未丑戌最严重。","sec":"一、基本规则","t":"diff"},{"q":"女命乙木日主，天干透出丙火伤官，按此规则克夫吗？","opts":["不克，因为丙是食神不是伤官","克夫，伤官必克官","克夫，丙火最严重","不克，阴日主见阳伤官不克"],"ans":3,"exp":"阴日主见阳不克；乙日主的伤官是丙，丙为阳，阴日主见阳不克夫。","sec":"一、基本规则","t":"calc"},{"q":"女命夫星不宜临墓，「库不开」意味着什么？","opts":["库不开就是墓","库不开只有男命才算墓","库不开反而吉","库不开才能保夫星"],"ans":0,"exp":"女命夫星不宜临墓，库不开为墓，墓库需刑冲才开；夫星临墓被冲开则伤而不死。","sec":"一、基本规则","t":"rule"},{"q":"夫宫与夫星同时被坏（如宫被刑星被穿），按盲派怎么断？","opts":["只主夫病，不离婚","必离，也可能死夫","宫星同坏反主婚姻稳定","主夫有外遇但不离"],"ans":1,"exp":"夫宫与夫星同时被坏必离，也可能死夫；配偶宫、星三刑也主克。","sec":"一、基本规则","t":"rule"},{"q":"配偶星（或配偶）「墓绝同现」，主什么？","opts":["主离婚，不主死亡","主晚婚，应期在冲开墓库之年","主死亡，应期找刑开墓库或绝地引动之年","主多次婚姻，应期在合到之年"],"ans":2,"exp":"墓绝同现主死亡；应期看大运流年冲破、刑开墓库或引动绝地。","sec":"一、基本规则","t":"rule"}]},{"n":102,"level":"高级","title":"独身组合四型","qs":[{"q":"独身命的共同点是什么？","opts":["夫妻星先天被冲克尽","日主先天无根无气","夫妻宫先天有毛病","大运先天不见财官"],"ans":2,"exp":"独身命的共同点是夫妻宫先天有毛病；盲派把它归为四种宫位类型。","sec":"二、夫妻宫的四种先天毛病","t":"rule"},{"q":"夫妻宫与子女宫占比劫禄神、夫妻星不易进入，现实表现通常是？","opts":["一生没有任何异性伙伴，纯属独身","结婚后夫妻长期分居两地生活","婚后丈夫早亡，此后一直守寡","男朋友都是有家室的"],"ans":3,"exp":"这型主位占印劫禄，夫妻星进不来；官星虽有但坐比劫地、与劫财合，是别人的男人，有男友但不结婚。","sec":"二、夫妻宫的四种先天毛病","t":"rule"},{"q":"夫妻宫落制夫妻星之星，但制之不成，结果是？","opts":["夫妻星反坏夫妻宫，宫星相破","夫妻星入墓，墓不开而无法出来","正星得位天地合，偏星旺相来干挠","夫妻星被比劫夺去，宫内无星可用"],"ans":0,"exp":"宫欲制星而星强，反把夫妻宫坏掉，宫星相破，因此独身。","sec":"二、夫妻宫的四种先天毛病","t":"calc"},{"q":"夫妻宫落夫妻星之墓，并无刑冲克破，仍易独身，原因是？","opts":["偏星旺相，干挠正星","墓不开，财官入墓出不来","宫星相破，星反坏宫","比劫争夫，夫星被夺"],"ans":1,"exp":"夫妻宫占夫妻星之墓，墓不开则财官入墓不出，要开库之运才有婚。","sec":"二、夫妻宫的四种先天毛病","t":"calc"},{"q":"「水中捞月」型独身的结构是？","opts":["宫坐偏星，正星入墓而不得开库","宫制星不成，星强反坏夫妻宫位","宫坐正星且天地合，偏星旺相干挠","宫占比劫禄神，夫妻星难以进入宫内"],"ans":2,"exp":"夫妻宫坐夫妻正星且天地相合，本人有理想配偶，但命局偏星旺相干挠，遇到的总不如意，只能单身。","sec":"六、第四型：正星得位而偏星干挠（水中捞月）","t":"rule"},{"q":"妻星卯木入未墓，未墓不开，哪个大运才可能开库成婚？","opts":["辰运，辰未相逢开库","酉运，酉卯冲开卯木","午运，午未合开未库","戌运，戌未刑开未库"],"ans":3,"exp":"墓不开的独身命要行刑冲开库之运：未库逢戌刑开；午未是合，合不开库。","sec":"五、第三型：宫占星之墓，墓不开","t":"calc"},{"q":"女命官星坐比劫地，又与劫财相合，婚姻怎么断？","opts":["有男友，但一生不会结婚","有婚姻，丈夫多有外情","早婚而离，再婚稳定","晚婚且长久稳定"],"ans":0,"exp":"官星坐比劫地又合劫财，是别人的男人：有男朋友，但一生不结婚。","sec":"三、第一型：主位占比劫印禄","t":"calc"},{"q":"「水中捞月」型独身，运上有没有解除的办法？","opts":["行去掉伤官之运，工作强而得婚缘","一般无解，理想主义使然","行刑冲开库之运，墓开则有婚缘","官星落夫宫位之运，可有短暂婚缘"],"ans":1,"exp":"这型是理想主义加偏星干挠，章末归纳为一般无解；开库之运属第三型，官星落宫运属第一型。","sec":"七、本章小结","t":"rule"}]},{"n":103,"level":"高级","title":"差婚姻与好婚姻组合","qs":[{"q":"「差婚姻」（不离但差）的共同点，哪项对？","opts":["宫星入墓不开，但有大运冲开才不离","宫星全无关联，只靠大运维系不散","宫星被冲坏，但有合神救护而不离","宫星不坏或被包住，但有穿破隔阂"],"ans":3,"exp":"差婚姻宫星并未被坏（或被包住），所以不离；但存在穿、破、印食伤的隔阂，所以不好。","sec":"一、差婚姻（不离但差）","t":"diff"},{"q":"夫妻宫与夫星有穿、破、刑，但夫星被包局、合住而不坏，怎么断？","opts":["吵闹不和，但不离婚","必离婚，穿破主夫妻分离","无婚姻，宫星相破不能成婚","不吵不闹，穿破反主婚姻美满"],"ans":0,"exp":"差婚姻断法：有穿、破、刑则吵、不和；但宫星被包住、合住、不坏，所以不离。","sec":"一、差婚姻（不离但差）","t":"calc"},{"q":"看似有穿、冲、克、二夫二妻之象，被什么化解时婚姻反而很好？","opts":["印星化解官杀而解","包局、连体、一气所化解","食伤泄秀制官而解","大运比劫帮身而解"],"ans":1,"exp":"总纲：看似有穿冲克、二夫二妻之象，但被包局、连体、一气所化解，则婚姻很好。","sec":"二、好婚姻（易看错的组合）","t":"rule"},{"q":"夫宫为未，丁火杀星与巳火官星都与夫宫有关，且巳透乙与丁相连成连体，怎么看？","opts":["一个是夫，一个是情人","要看大运才能分一人二人","连体是一个人，一婚到头","是两个夫，主二婚"],"ans":2,"exp":"连体不以两个人看：丁乙巳连在一起是一个人，所以不是二婚，也无桃花。","sec":"2. 看似二妻（夫）实为一人","t":"calc"},{"q":"男命财星多、比劫弱，能不能断多婚、桃花多？","opts":["能，财多主多妻多婚","能，财多比劫弱更招桃花","不能，因为财星必受制","不能，比劫弱无精力兴趣"],"ans":3,"exp":"男命桃花或多婚一般要比劫旺才行；比劫弱则没有精力与兴趣找桃花，财多不等于多婚。","sec":"3. 财多不等于多婚、桃花被穿即无桃花","t":"rule"},{"q":"妻宫穿局中的桃花星，意味着什么？","opts":["反过来排拆桃花，无桃花婚姻好","妻宫被破，终将离婚收场","桃花入墓，晚年才得发作","桃花更旺，婚姻多有波折"],"ans":0,"exp":"妻宫穿桃花星就是反过来排拆的意思，所以从无桃花与情人，婚姻非常好。","sec":"3. 财多不等于多婚、桃花被穿即无桃花","t":"rule"},{"q":"男命八字既无财星、又无食伤星，以什么当妻？","opts":["以官杀当妻，官杀即配偶","以妻宫当妻，看宫的象","以比劫当妻，比劫即配偶","以印星当妻，印星即配偶"],"ans":1,"exp":"既无财也无食伤时，以妻宫为妻，看宫字本身的象。","sec":"4. 无财无食伤，以妻宫为妻","t":"rule"}]},{"n":104,"level":"高级","title":"父母死亡的组合与应期","qs":[{"q":"父（母）星在局中「多现而且杂现」，按盲派叫什么？主什么？","opts":["叫「患」，容易克父母","叫「杂」，主父母不和","叫「患」，只主父母多病不死","叫「旺」，主父母长寿"],"ans":0,"exp":"克父母六条之一：父（母）星多现而且杂现称为「患」，容易克父母。","sec":"一、克父母的六条组合","t":"rule"},{"q":"「财临墓地」在看父亲时主什么？","opts":["父亲发财","父当早死","父亲不管子女","父亲长寿"],"ans":1,"exp":"克父六条之一：财临墓地，父当早死；应期看冲开墓或天干引动墓。","sec":"一、克父母的六条组合","t":"rule"},{"q":"父母星无法立足的位置不同，各有什么含义？","opts":["只有日时立不住才克父母","立不住只主父母分居，不主死","年月、日时宫位上立不住，都是克父母的信息","只有年月立不住才克父母"],"ans":2,"exp":"父母星在年月宫位不能存在是克父母的信息，在主位日时宫位不能存在也是。","sec":"一、克父母的六条组合","t":"diff"},{"q":"断父母死亡的应期，第一步先找什么？","opts":["流年的天克地冲","父母星的墓库","日主的喜忌","父（母）星的原神"],"ans":3,"exp":"先找父母星的原神（生它的字），运或流年穿、克、合走原神，则父母之星失养。","sec":"判断应期的方法","t":"step"},{"q":"父星入墓，应期怎么取？","opts":["原局墓已备好，大运流年冲开墓或天干引动墓","原局无墓，运中补出墓才应","合住墓库之年才应","墓被冲开后永不再应"],"ans":0,"exp":"星入墓：原局墓已备好，大运流年冲开墓，或天干引动墓，即应。","sec":"判断应期的方法","t":"rule"},{"q":"父母死因取象：卯午相破、申子穿，分别主什么病？","opts":["卯午相破主尿毒症，申子穿主心脑血管病","卯午相破主心脑血管病，申子穿主尿毒症","卯午相破主胃癌，申子穿主血液病","卯午相破主肝胆病，申子穿主心脏病"],"ans":1,"exp":"卯为血管、午为心脏，卯午相破主心脑血管病；子为肾，申子水为肾，申子穿则尿毒症。","sec":"判断应期的方法","t":"xiang"},{"q":"按父母死因的取象，地支戌与子分别对应哪个脏腑？","opts":["戌为肾，子为心脏","戌为肝，子为肺","戌为心脏，子为肾","戌为肠胃，子为血管"],"ans":2,"exp":"取象：卯是血管、午是心脏、戌为心脏、子为肾。","sec":"判断应期的方法","t":"xiang"},{"q":"看母亲时，一定以印星为母吗？","opts":["印被穿则改以官杀为母","一定以印为母，财为父","男命以印为母，女命以财为母","不一定，先按该命实际的象验证何字为母"],"ans":3,"exp":"父母星要按该命实际的象去认，先验证以哪个字为母更符合，不可死守以印为母。","sec":"二、不以印为母的特例","t":"rule"}]},{"n":105,"level":"高级","title":"父母离异与弃养（过继、给出去）","qs":[{"q":"命中父母之星相克，但没有任何一方死亡的信息，应断什么？","opts":["父母分居但不离","父母离异","父母一方早亡","父母不和，但终身不离"],"ans":1,"exp":"看得出父母相克、看不出死亡信息，一定是离异。","sec":"一、父母离异","t":"rule"},{"q":"父星双合、伏吟，与母星双合、伏吟，各主什么？","opts":["父早亡，母早亡","父外遇不离，母外遇不离","父另娶，母改嫁","父改嫁，母另娶"],"ans":2,"exp":"父星双合、伏吟是父另娶；母星双合、伏吟是母改嫁。","sec":"一、父母离异","t":"diff"},{"q":"父母离异后，孩子是随父还是随母，怎么看？","opts":["看月令是印还是财","看年柱是父字还是母字","看时柱是男字还是女字","看日主坐在哪一方的字上"],"ans":3,"exp":"随母或随父，看自己（日主）坐在谁的字上。","sec":"一、父母离异","t":"rule"},{"q":"继父、继母在盘中怎么找？","opts":["暗合或冲引出的另一个字","月令里透出的比肩字","大运中新来的比劫字","时柱上透出的食伤字"],"ans":0,"exp":"继父、继母是暗合、冲所引出的另一个字；父母之星被他字合到继位也是。","sec":"一、父母离异","t":"rule"},{"q":"月令食神入墓，时上又见食神，主什么？","opts":["母亲早逝，父亲独养","父母不养，为过继命","一生衣食无忧","父母双全，晚年得子"],"ans":1,"exp":"月令食神入墓，父母不养；时上再见食神，为过继命。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"盲派把食神看作「养我之物」，食神被合、被穿、被绊，主什么？","opts":["身体虚弱，多病","与子女缘薄，晚得子","没饭吃，被送走","学业不顺，辍学"],"ans":2,"exp":"食神被合、被穿、被绊，就是没饭吃，被送养。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"时柱伏吟，又有天干五合（如丁壬合）合到主位，主什么？","opts":["随母改嫁，有继父","出国发展，远走他乡","父母双全，远方有贵人","远方食神合到主位，过继给他人"],"ans":3,"exp":"时柱伏吟、天干五合到主位，远方食神合到主位，所以过继（如过继给叔叔）。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"日支与年支相穿（如寅巳穿，穿倒食神），主什么？","opts":["父母不养","随母改嫁","父母双亡","父母另娶另嫁"],"ans":0,"exp":"日支与年支相穿，穿倒食神，父母不养。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"过继命里，月柱与时柱各代表谁？","opts":["月柱为祖父母，时柱为父母","月柱为生父母，时柱为养父母","月柱为养父母，时柱为生父母","年柱为生父母，月柱为养父母"],"ans":1,"exp":"看过继先分清：月柱是生父母，时柱是养父母。","sec":"二、父母弃养（过继、给出去）","t":"diff"},{"q":"乙庚合，合到门户（时柱），在弃养上主什么？","opts":["给人当差，晚年归家","留下来，母亲亲养","给出去，送养","随父同住，继母相伴"],"ans":2,"exp":"乙庚合合到门户，是给出去、送养之象。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"母带伤官、父星他合，在养育上分别主什么？","opts":["母带伤官溺爱自己；父星他合偏心自己","母带伤官不养自己；父星他合接济自己","母带伤官早亡；父星他合另娶","母带伤官不养自己；父星他合不管自己"],"ans":3,"exp":"母带伤官，不养自己；父星他合，不管自己。","sec":"二、父母弃养（过继、给出去）","t":"rule"}]},{"n":106,"level":"高级","title":"职业象法一：十天干与十二地支之象","qs":[{"q":"大阴阳与小阴阳的划分是（　）。","opts":["大阴阳金水为阳木火为阴，小阴阳乙丁己辛癸为阳","大阴阳木水为阳火金为阴，小阴阳甲丙戊庚壬为阳","大阴阳木火为阳金水为阴，小阴阳甲丙戊庚壬为阳","大阴阳甲丙戊庚壬为阳，小阴阳木火为阳"],"ans":2,"exp":"大阴阳以木火为阳、金水为阴；小阴阳以甲丙戊庚壬为阳、乙丁己辛癸为阴。","sec":"一、阴阳、五行与十干总说","t":"diff"},{"q":"戊土独透天干，职业倾向是什么？","opts":["记者，戊主传播","医生，戊主手术","银行职员，戊主金融","老师，戊有讲台之象"],"ans":3,"exp":"戊为高台、舞台、讲台，独透者易当老师。","sec":"二、十天干之象","t":"xiang"},{"q":"乙与丁，各自在传媒文化方面的象分别是（　）。","opts":["乙主纸张书籍传播，丁主文化文字智慧","乙主文化文字智慧，丁主纸张书籍传播","乙主讲台舞台，丁主文字荣誉","乙主光电影视色彩，丁主纸张传播"],"ans":0,"exp":"乙为书籍纸张毛笔丝线，有传播之象；丁为文明文化文字思根智慧医道玄学。丙才主色彩影视光电。","sec":"二、十天干之象","t":"xiang"},{"q":"庚、辛两干取象的主要区别是（　）。","opts":["庚为书画影视，辛为讲台建筑","庚为钢材机器军警，辛为珠宝针笔","庚为珠宝针笔，辛为钢材机器军警","庚为数字运算，辛为玄学西药"],"ans":1,"exp":"庚：五金钢材矿山机器金融军队警察手术；辛：珠宝玉器金饰针笔钱币精加工。","sec":"二、十天干之象","t":"xiang"},{"q":"庚金日主，局中无火，按盲派应怎么看？","opts":["金旺无火则化水，主聪明","金旺无火则主富，利于求财","金旺无火为顽金，难成才","金旺无火则最清贵，主文职"],"ans":2,"exp":"庚喜火炼方成器，金旺无火为顽金（顽铁）。","sec":"二、十天干之象","t":"rule"},{"q":"壬癸两干的类象，分别偏向（　）。","opts":["壬主文化文字，癸主讲台建筑","壬主玄学谋略西药，癸主数字运算","壬主珠宝针笔，癸主钢材机器","壬主数字运算，癸主玄学谋略西药"],"ans":3,"exp":"壬：运筹运算数字，易成会计；癸：玄学智谋美容产品西药。","sec":"二、十天干之象","t":"xiang"},{"q":"亥水与子水在象上的区别是（　）。","opts":["亥为不动之水，子为流转不息之水","亥为流转不息之水，子为不动之水","亥为阳水近壬，子为阴水近癸","亥为大海，子为小溪"],"ans":0,"exp":"亥占阴位而藏阳，阴水近癸；子占阳位而藏阴，阳水近壬；亥为不动之水，子为流转不息之水。","sec":"四、十二地支之象","t":"xiang"},{"q":"戌土除火库外，还是什么库，对应哪类职业？","opts":["水库，主车辆机器","文库，火主文，主学校编辑部教育部门","财库，主银行金融","武库，主军队警察"],"ans":1,"exp":"戌是火库，火主文，也是文库：学校、编辑部、教育部门；辰才是水库。","sec":"四、十二地支之象","t":"xiang"},{"q":"亥与会计职业相关的四种情况是（　）。","opts":["亥为比劫合财，被印墓，生助官杀，或亥为印","亥为印星，被官杀克，被比劫合，或亥为官","亥为食伤合财，被财墓，冲制财官，或亥为财","亥为伤官见官，被食神穿，被比劫冲，或亥为食"],"ans":2,"exp":"亥与会计相关：亥为食伤合财；亥被财墓；亥冲制财星或官杀星；亥为财星。","sec":"四、十二地支之象","t":"rule"},{"q":"己酉为赛车之象，为何不是车祸？","opts":["酉戌穿主发动机，不主车祸，不论强弱","己酉合住了戌，戌穿的作用消失","戌强酉弱，戌穿坏酉，所以反主速度","酉强戌弱，戌穿不坏酉；若只一个己酉才可能车祸"],"ans":3,"exp":"己象方向盘、酉为驾驶技术、酉戌穿为速度、戌为发动机；酉强戌弱穿不坏酉，所以不是车祸。","sec":"十二地支命例","t":"diff"},{"q":"用食神或伤官合法对抗官，常见的职业是（　）。","opts":["律师，站在当事人一边对抗检控机关","会计，替单位管理财务","法官，代表官方执法","军警，执行官方命令"],"ans":0,"exp":"伤官有对抗官之意，用伤官、食神合法对抗官，很可能是律师。","sec":"十二地支命例","t":"xiang"}]},{"n":107,"level":"高级","title":"职业象法二：生意人","qs":[{"q":"命局里承担财富的几类东西，级别由小到大怎么排？","opts":["官杀、食伤、财星","食伤、财星、官杀","财星、官杀、食伤","财星、食伤、官杀"],"ans":3,"exp":"财是养命之源，级别较小；食伤是财之源，比财大；官杀由财所生，是财富升级成权势规模，最大。","sec":"一、先定义：什么可以当财富看","t":"step"},{"q":"定财富级别时，「禄」代表哪一份财富？","opts":["自己能用到花到的那份，不是做大的资本","财升级成权势与产业的那一份财富","财的源头，源头大于水流，级别更大","可以做大规模的资本，用来扩张业务"],"ans":0,"exp":"口诀：财是养命钱，食伤是财源，官杀是财升级，禄是自己享用。","sec":"一、先定义：什么可以当财富看","t":"rule"},{"q":"做生意的命里，印星常常代表什么？","opts":["贵人提携和上级的赏识","门店、公司、厂子、规模","读书学历和单位里的工作","父母给的祖业遗产和房产"],"ans":1,"exp":"做生意的命里，印常常不是读书、不是工作，而是门店、公司、厂子、规模；印在年时门户，有几个印星往往几个厂子。","sec":"二、生意组合的几种基本结构","t":"rule"},{"q":"官杀库不开又无制，这样的命主多走什么路？","opts":["官杀无制主牢狱，不能做事","仍然当官，只是官位不高","不能当官，转而求财做生意","出家修行，不求财也不求官"],"ans":2,"exp":"官杀库不开又无制，不能当官，转而求财做生意。","sec":"二、生意组合的几种基本结构","t":"rule"},{"q":"禄冲财、寅申冲，再逢驿马，是什么组合？","opts":["守着门店稳定经营的格局","在单位里当官的格局","技术研发型的企业格局","做贸易，满世界跑"],"ans":3,"exp":"禄冲财、寅申冲是典型生意组合；逢驿马就是满世界跑、辛苦求财，如进出口贸易。","sec":"二、生意组合的几种基本结构","t":"xiang"},{"q":"劫财合财，对投资和赌博各主什么？","opts":["喜投资好赌，但赌必输，正经生意能赚","喜投资好赌，赌必赢，做正经生意反而不赚","喜赌博必发大财，做正经生意必定失败","不喜投资不好赌，只赚稳定的工资收入"],"ans":0,"exp":"劫财合财，被劫合去的财不做功，所以十赌九输；但做正经生意却能赚，赌与做生意要分开问。","sec":"二、生意组合的几种基本结构","t":"diff"},{"q":"取行业象时，酉金见水一般取什么象？","opts":["玻璃、化工类","酒店、饭店、餐饮","装修、彩绘类","车辆出租、物业"],"ans":1,"exp":"酉金见水有酒店、饭店、餐饮之象；未也有酒店之意。装修彩绘取丙火、车辆出租取申金、化工取子水。","sec":"三、取行业：象的拼合","t":"xiang"},{"q":"运中出现丁运、劫运、比劫运，对求财一般怎样？","opts":["比劫引动财库，主利于发大财做生意","比劫是自己的钱，主利于独立创业","帮别人、别人的钱，多主打工或破财","比劫帮身，主财运必定大发，利于做大"],"ans":2,"exp":"天干比劫透出，多为「帮别人」「别人的钱」，主打工、辛苦，或财被劫而破财。","sec":"四、大运流年的应期规律","t":"rule"},{"q":"按应期代换，流年辰到，相当于哪个字到？","opts":["午","申","酉","子"],"ans":3,"exp":"丑到等于申酉到，辰到等于子到：流年用本气所藏之字或同类字来代换，要熟练。","sec":"四、大运流年的应期规律","t":"calc"},{"q":"官杀被运岁引动而不被制，结果一般怎样？","opts":["不是升官发财，而是官非伤病盗贼小人","只主财运好转，与官非伤病无关","官杀不被制，反主清闲无事可做","升官发财，权势变得更大了些"],"ans":0,"exp":"官杀被引动而不被制，不是升官发财，而是官非、伤病、盗贼、小人。","sec":"四、大运流年的应期规律","t":"rule"},{"q":"命局有财库，库不开时怎么论？发财应期在哪？","opts":["财不能释放；运岁合闭财库时发财","财不能释放；运岁冲开刑开财库时发财","财已经在手；运岁冲开财库时破财","财已经在手；运岁闭库时才发财"],"ans":1,"exp":"库不开则财不能释放，运岁冲开、刑开财库就是发财的应期；财库合闭则不利。","sec":"二、生意组合的几种基本结构","t":"rule"}]},{"n":108,"level":"高级","title":"职业象法三：老师","qs":[{"q":"老师命里，食伤旺而形成包局，除了代表头脑口才，还代表什么象？","opts":["周围是一群学生","周围是一群同事","周围是一群上级领导","周围是一群病人"],"ans":0,"exp":"食伤既代表头脑、思想、口才，也代表学生；食伤旺而形成包局，就是周围一群学生的象，可以当老师。","sec":"一、老师命的识别条件","t":"xiang"},{"q":"老师象里，哪个天干代表讲台，什么形态最典型？","opts":["丙，光芒四射，火来照土","戊，独阳高透，阳来统阴","己，独阴低伏，阴来承阳","庚，棱角分明，金来制木"],"ans":1,"exp":"戊为高台、讲台，独阳高透，阳来统阴，如一人在高台上讲、学生在下面听，是老师的象。","sec":"一、老师命的识别条件","t":"xiang"},{"q":"十二地支中，哪两个字可以代表学校？","opts":["卯和酉","辰和未","寅和戌","子和午"],"ans":2,"exp":"寅与戌可代表学校：寅为食神又为学堂，戌为食伤库（学生之库），许多老师与这两字关系很大。","sec":"一、老师命的识别条件","t":"xiang"},{"q":"时柱见辛卯，老师象里辛、卯各取什么象？","opts":["辛为书本，卯为讲台","辛为教鞭，卯为粉笔","辛为讲台，卯为书柜","辛为粉笔，卯为教鞭"],"ans":3,"exp":"时见辛卯有老师的象：辛为粉笔，卯为教鞭；书象取己与未，讲台取戊。","sec":"一、老师命的识别条件","t":"xiang"},{"q":"命局金水旺、亥水配印，又是金水伤官，最可能教什么科目？","opts":["数学、物理化学等理科","语文、英语等文科","音乐、书法等艺术科","体育、舞蹈等技能科"],"ans":0,"exp":"木火旺主文、金水旺主理；亥水主数学，亥配印、金水伤官数理能力强，教统计、数学化学。","sec":"一、老师命的识别条件","t":"calc"},{"q":"同样是伤官配印，什么情况能入公门当校长，什么情况只做教师？","opts":["杂财星才能入公门；不杂财只教书","不杂财星能入公门；杂财、财重损格只教书","有无财星都只教书，不会入公门","有无财星都能入公门，看日主旺衰"],"ans":1,"exp":"口诀：伤官配印不见财，才能入公门；见财损格则入学校。财重又甲己合之类，只能做普通教师。","sec":"二、老师与","t":"diff"},{"q":"日支坐官杀库而无功，不能当官，适合做什么？","opts":["做医生最合适","做生意最合适","做老师最合适","做军警最合适"],"ans":2,"exp":"官杀库在坐下、无功，不是当官的命，做老师最合适；辰为杀库不开又不能制服，则不当官也不做生意，以读书、说话为业。","sec":"二、老师与","t":"rule"},{"q":"老师命的应期，伤官合印、食神合杀各应在什么事？","opts":["伤官合印为结婚，食神合杀为生子","伤官合印为参加工作，食神合杀为考学","伤官合印为升职，食神合杀为破财","伤官合印为考学，食神合杀为参加工作"],"ans":3,"exp":"伤官合印、财制印、食神合杀是参加工作、考学、调动的应期；考学要看伤官合印，不是印本身出现。","sec":"三、判断步骤","t":"step"},{"q":"老师命的婚姻，女命与男命各有什么常见规律？","opts":["女命伤官克夫，晚婚多婚常见；男命官印稳定","女命官印稳定；男命伤官克妻，多婚","女命男命都是晚婚，终身不婚","女命男命都是早婚，婚姻稳定"],"ans":0,"exp":"判断步骤里附带看婚姻：女命伤官克夫，晚婚、多婚常见；男命官印稳定。","sec":"三、判断步骤","t":"rule"},{"q":"己与未，在老师象里各取什么象？","opts":["己为讲台，未中藏卯是粉笔","己有书象，未中藏卯是书柜","己为教鞭，未中藏卯是书本","己为学校，未为学生之库"],"ans":1,"exp":"天干己土有书象，地支未中藏卯是书柜；己同时象口，说话为业。讲台取戊，学校取寅戌。","sec":"一、老师命的识别条件","t":"xiang"}]},{"n":109,"level":"高级","title":"职业象法四：公务员","qs":[{"q":"官杀没有被制服就合到日主身上，盲派怎么论？","opts":["官杀被合住，反而一生清闲平安","自己合一个毛病上身，一生灾祸连连","合身就是升官，不论有制无制","官杀有力，合身即主大贵显达"],"ans":1,"exp":"官杀有制再合身，才是我管理控制；无制而合，等于把毛病合到自己身上。","sec":"二、官位大小怎么看","t":"rule"},{"q":"公务员命里印星落在年上、与日主隔得远，权力如何？","opts":["印在年上只影响学历，不影响官位","印远隔反而权力更大、升得快","用之不得力，没什么权力","印远隔主升得特别快，官运亨通"],"ans":2,"exp":"印要用得上才有权，隔得远就用之不得力。","sec":"二、官位大小怎么看","t":"rule"},{"q":"官星合到的是比劫（别人的官），一般怎么论？","opts":["主在外地升迁，有调动","必定丢官，仕途中断","官位最高，自己掌握实权","官是别人的，只能当副手"],"ans":3,"exp":"合到别人的官只能当副手；若能合到自己身上，才是自己升官。","sec":"二、官位大小怎么看","t":"diff"},{"q":"官职升不高的典型组合是？","opts":["财透生官、官制不好、运又走财生旺官","官杀有制、食伤包局、权力集中","官杀库在日支下又被冲动发用","子辰一家包局，官杀有制成功"],"ans":0,"exp":"财生官而官无制，官越旺越难控制，升不高；包局、库被冲动则是权力大的象。","sec":"二、官位大小怎么看","t":"rule"},{"q":"官杀库坐在日支下、被冲动，一般怎么论？","opts":["库被冲破，官位不稳、没有权力","坐下官杀发用，有权力","官库被冲，主丢官、官位不保","冲动只主调动，不主有权力"],"ans":1,"exp":"官杀库在坐下被冲动，官杀发用，权力就出来了。","sec":"二、官位大小怎么看","t":"rule"},{"q":"盲派以哪两个字代表公门？","opts":["子与壬","卯与乙","寅与甲","申与庚"],"ans":2,"exp":"寅与甲在命局中占重要地位，是看公务员命先要找的字。","sec":"一、公务员命的基本组合","t":"rule"},{"q":"阳制阴局（甲、丁制辰、丑）的公务员，多在哪类部门？","opts":["组织、人事、编制","财政、税务、审计","乡镇党委、基层政府","公安、检察院、纪检"],"ans":3,"exp":"辰丑为阴为牢狱，甲丁为阳为光明正义，所以多在公安检察纪检一类。","sec":"三、不同部门的象","t":"xiang"},{"q":"伤官配印、寅与未包局、财制印得权，多是哪类部门？","opts":["权力部门（市委办、组织部）","公安、检察、纪检部门","财政、税务、审计部门","后勤、总务、行政部门"],"ans":0,"exp":"寅主公门，未与寅同象表权力，财制印得权，所以是权力部门。","sec":"三、不同部门的象","t":"xiang"},{"q":"判断公务员命，先后顺序是？","opts":["先判部门，再看做功，最后找公门","先找公门，再看做功，再判职务大小","先看婚姻六亲，再定职务大小","先排应期，再找公门，最后看做功"],"ans":1,"exp":"步骤是公门→做功→职务大小→部门→应期→复核婚姻六亲。","sec":"四、判断步骤","t":"step"}]},{"n":110,"level":"高级","title":"职业象法五：部队军官","qs":[{"q":"按盲派，军官命局里比劫羊刃库、寅戌、申各代表什么象？","opts":["官杀库为兵营；寅戌为武库；申为军警","比劫羊刃库为武库；寅戌为兵营；申为军警","比劫羊刃库为兵营；寅戌为武库；申为军警","比劫羊刃库为兵营；寅戌为军警；申为武库"],"ans":2,"exp":"比劫库有兵营、部队之意；寅戌为武库，戌本意是火药、枪支、炮弹；申为军警，常见火金相克。","sec":"一、军官的特殊组合","t":"xiang"},{"q":"申为军警，要成军官之象，申需要出现什么组合？","opts":["金水相生，如申子辰成局","水木相生，如亥卯未成局","木火相生，如寅午戌成局","火金相克，如丁制辛、午制申"],"ans":3,"exp":"申为军警，出现火金相克的组合（丁制辛、午制申）成军官。","sec":"一、军官的特殊组合","t":"rule"},{"q":"按盲派，军官里印星为权力，权力的做功方式是什么？","opts":["制印得权，即财制印","印生比劫，比劫护身","官杀生印，杀印相生而已","食伤泄印，伤官见官"],"ans":0,"exp":"制印得权（财制印）是军官最常见的做功；伤官配印、杀印相生也是权力象。","sec":"一、军官的特殊组合","t":"rule"},{"q":"盲派看军衔高低，什么样的命局军衔较高，什么样官职不大？","opts":["单层功军衔较高；包局太多反而不大","印官杀食伤包局高；伤食混杂小","印星太旺军衔较高；官杀混杂官职不大","比劫成林军衔较高；财星太旺官职不大"],"ans":1,"exp":"官位高低看包局：印包局、官杀包局、食伤包局军衔较高；单纯伤食混杂则官职不大。","sec":"二、军衔与升迁的判断","t":"diff"},{"q":"盲派所说「过河拆桥」之功是什么意思？","opts":["制去自己用完的比劫，权力集中","合住别人的官，让官位转给自己","冲穿别人的官或用完的神，位置留给自己","冲开官库，把别人的权力引到自己"],"ans":2,"exp":"过河拆桥是用一个字冲穿别人的官或自己已用完的用神，让官位空出来留给自己；如丑午穿、子午冲、丑未冲。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"「贼捕结构」里，贼神与捕神分别是什么？","opts":["官星为贼神，印星为捕神","比劫为贼神，财星为捕神","制者为贼神，被制者为捕神","被制者为贼神，制者为捕神"],"ans":3,"exp":"贼神是被制者、捕神是制者；制局中被制的神喜欢到位，如辰为贼神、戊为捕神，辰到则制神有对象，升职。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"原局有戊制辰的制局，行运见辰到，按盲派是什么应期？","opts":["贼神到位，制神有对象，利升职","印库被冲，权力受损，主降职","比劫到位，争夺官位，主降职","官星入墓，官位被收，主转业"],"ans":0,"exp":"辰为贼神、戊为捕神，被制的辰到位，捕神有对象可制，是升职之象。","sec":"二、军衔与升迁的判断","t":"calc"},{"q":"盲派看军官升迁，见到什么情形就要升官？","opts":["比劫出现，或印到被生、官杀合身而旺","戊土出现，或印到被制、官杀被制化","食神出现，或印到被合、财星入库较旺","戊土被克，或印库被冲、官杀到位无制"],"ans":1,"exp":"见戊土是做功重要字；戊出现，或印到被制、印库出现、官杀出现被制化，就要升官。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"同一原局，运岁里出现什么情形，军官会升迁停滞甚至转业？","opts":["印被合住而官星得力的大运","财星制印被引动的大运","印被穿、做功被破的大运","比劫帮身、官杀得助的大运"],"ans":2,"exp":"印被穿、做功被破的大运，升迁停滞，甚至变成闲职或转业。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"盲派看军官的步骤，前几步的正确顺序是什么？","opts":["先定军衔，再找武象，再找权力，再排应期","先排应期，再找武象，再找权力，再定军衔","先找权力，再找武象，再定军衔，再排应期","武象、权力、军衔、应期"],"ans":3,"exp":"先找武象（比劫羊刃库、寅戌、申、火金相克），再找权力（印、官杀、杀库，谁制谁），再定军衔级别，再排升职应期，后看转业退休与婚姻。","sec":"三、判断步骤","t":"step"},{"q":"盲派看军官转业、退休，看哪些信号？","opts":["官合入比劫，印被破，做功被破","财星被合，食神入库，印星生旺","官星被冲，比劫被制，运入印库","印星被生，官杀有制，运入财地"],"ans":0,"exp":"转业退休看官星合入别人（比劫）、印被破、做功被破，或运入「官非」。","sec":"三、判断步骤","t":"rule"},{"q":"军官命局做功多用冲穿，对婚姻有什么影响？","opts":["只影响子女宫，不影响妻星与夫妻宫","多伤妻星夫妻宫，婚姻多波折","与婚姻无关，只影响官位升迁快慢","冲穿越多，夫妻宫越稳固，家宅平安"],"ans":1,"exp":"做功用的是穿、冲，多与妻星、婚姻宫相关，所以军官婚姻多波折；复核时注意夫妻宫、妻星是否被穿冲。","sec":"六、本章小结","t":"rule"}]},{"n":111,"level":"高级","title":"职业象法六：会计","qs":[{"q":"会计命局取象，哪几个字被看作「数字、运算」之象？","opts":["巳、午、丙","申、酉、庚","寅、卯、甲","亥、子、壬"],"ans":3,"exp":"亥、子水带数字运算之意；壬主运算通达，与财星、官杀挂钩就容易从事会计。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"子未相穿与亥未拱财，在会计取象中各读作什么？","opts":["子未穿为运算，亥未拱财为计算财务","子未穿为管钱，亥未拱财为出纳","子未穿为计算财务，亥未拱财为运算","子未穿为书写，亥未拱财为运算"],"ans":0,"exp":"子之象如算盘珠，穿＝拨动，是打算盘之象，可直读为运算；亥未拱财是计算财务。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"会计的第三条规律「伤官／食神配印，且有亥子水参与做功」中，食伤与印各代表什么？","opts":["食伤是单位机构，印是头脑技能","食伤是头脑技能，印是单位机构","食伤是财库，印是数字运算","食伤是大机构，印是行动力"],"ans":1,"exp":"食伤是头脑、技能，印是单位、机构，亥子水加入就是用自己的数字技能为单位服务。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"丁壬合在会计命局里主什么象？","opts":["有行动之意，主比劫夺财","有远行之意，主外资企业","有书写之意，才华为机构所用","有计算之意，主钱财到手"],"ans":2,"exp":"丁壬合有书写之意，又是食神（伤官）配印，主才华为机构所用、学历文凭较高。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"会计命局中，年上的印或官（印带官合身）表示什么？","opts":["年为远方，表示出国留学","年为祖上，表示家族企业","年为门户，表示自己创业","年为远方，可表示外资、大企业"],"ans":3,"exp":"年为远方；印带官合身，可表示外资、大企业。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"会计命局里，寅（中含官杀）取什么象？","opts":["大机构，也代表大财","书写文职，也代表才华","眼睛视力，也代表辛苦","小单位，也代表小财"],"ans":0,"exp":"寅中含官杀，代表大机构，也代表大财，机构规模高。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"断会计命局的判断步骤，正确顺序是哪个？","opts":["先看大运流年，再找数字，再定级别","先找数字，再看做功方式，再定级别","先定级别，再找数字，再看做功方式","先看做功方式，再定级别，再找数字"],"ans":1,"exp":"步骤：①找数字（亥子壬）；②看做功方式；③定级别（财库开不开）；④看格局大小；⑤用大运流年验证。","sec":"一、会计命局的三条取象规律","t":"step"},{"q":"命局所管的钱很多，财库不开，这钱是谁的？怎样才轮到自己发财？","opts":["是自己的；财库不开也能发财","是自己的；财库被合住才发财","是单位的；财库被冲开刑开才轮到自己","是单位的；财库入墓后才发财"],"ans":2,"exp":"财库不开，所管的钱再多也是单位的；财库被冲开、刑开，才轮到自己发财。","sec":"一、会计命局的三条取象规律","t":"rule"},{"q":"断会计命局时，大运、流年怎样看作用？","opts":["流年先作用原局再合大运","大运先与流年作用再看原局","大运流年都只作用原局","大运看自身象再合原局，流年先合大运"],"ans":3,"exp":"看运口径：大运先看它自身的干支象意，再看与原局每一柱的作用；流年先与大运作用，再与原局作用。","sec":"一、会计命局的三条取象规律","t":"rule"},{"q":"月令巳火伤官与亥水印相冲，算不算「伤官配印」？","opts":["不算，是伤官与印不和，易丢工作","算，只是印被制，不影响单位","不算，是比劫夺印，主破财","算，是伤官配印中最强的一种"],"ans":0,"exp":"易错点：巳亥冲不是伤官配印而是伤官冲印；月令代表工作单位，月令坏印容易丢工作。","sec":"三、其余五例要点","t":"diff"},{"q":"会计命局级别高低（总监、行长与普通会计、出纳）怎么分？","opts":["食伤多见、无官杀级别高","官杀包局、有印有制级别高；局不成只能普通","官杀不包局、无印无制级别高","财星重见、比劫多级别高"],"ans":1,"exp":"官杀包局、有印有制，级别才高；局不成、制得不干净，只能做普通会计、出纳。","sec":"一、会计命局的三条取象规律","t":"rule"},{"q":"出纳命局里「戊坐子」取什么象？","opts":["子为眼睛，视力不佳，适合文员","子为算盘，主发大财，适合做老板","子为数字，认真仔细，适合做出纳","子为大机构，才华横溢，适合做总监"],"ans":2,"exp":"戊坐子，认真仔细，子为数字，故做出纳；若财被合走则只帮人管财。","sec":"三、其余五例要点","t":"xiang"}]},{"n":112,"level":"高级","title":"职业象法七：技术人员","qs":[{"q":"盲派看技术人员命局，一般用什么为用、什么代表单位？","opts":["食伤为用，官印为单位","比劫为用，财星为单位","财星为用，比劫为单位","官印为用，食伤为单位"],"ans":0,"exp":"食神伤官主头脑技术，官印为单位机构；技能为单位所用，就是技术人员的基本构成。","sec":"一、技术人员命局的总规律","t":"rule"},{"q":"技术人员命局与管理者命局，在格局上的区别是？","opts":["技术员必成制局，管理者必成包局","技术员不成包局、制局，成包局可做管理","技术员必成包局，管理者不成包局","两者都不成包局，只看食伤多少"],"ans":1,"exp":"没有包局、制局，只是靠技术吃饭，格局不大；格局大者能当管理者或领导。","sec":"一、技术人员命局的总规律","t":"diff"},{"q":"技术人员命局中，比劫参与做功代表什么？","opts":["主合伙开公司","主纯脑力、不用体力","动手能力，常是半体力半技术","主钱财被劫，工作不稳"],"ans":2,"exp":"比劫主动手能力；技术人员既付出脑力也付出体力，常是半体力半技术。","sec":"一、技术人员命局的总规律","t":"rule"},{"q":"乙未、戌、亥（壬）在技术行业取象上，依次对应什么？","opts":["数字运算、集成电路、电子电器","传媒影视、土建工程、数字运算","土建工程、电子电器、设计","集成电路、电子电器、数字运算"],"ans":3,"exp":"乙未为集成电路（也表传播、互联网）；戌为火库表电子、电器、电力；亥、子、壬表数字、运算。","sec":"行业取象表","t":"xiang"},{"q":"八字中己酉，在技术行业取象上主什么？","opts":["设计，己为线条、酉为面板","数字运算","土建工程","电信传媒"],"ans":0,"exp":"己酉：己为线条、酉为面板，设计之象；辰酉合表坐办公室。","sec":"行业取象表","t":"xiang"},{"q":"辰戌两字在技术行业取象上主什么？","opts":["电子电器，戌为火库","土建工程，戌为高楼","设计，辰为线条","集成电路"],"ans":1,"exp":"辰戌表土建工程，戌为高楼；戌作火库另表电子、电器、电力。","sec":"行业取象表","t":"xiang"},{"q":"技术人员常兼职教学，盲派取什么象？","opts":["伤食表老师，阴旺求阳","官印表学生，食伤表单位","伤食也表学生老师，阳旺求阴，学生求知","比劫表学生，财星表老师"],"ans":2,"exp":"伤食也表学生、老师，阳旺求阴（学生求知），所以技术人员常兼职教学。","sec":"行业取象表","t":"rule"},{"q":"八字没有食伤，也可能是技术命的日时组合是哪一个？","opts":["乙未日配丙戌时","丙寅日配壬辰时","戊戌日配辛酉时","壬辰日配己酉时"],"ans":3,"exp":"无食伤也可以是技术命：壬辰日配己酉时，己为线条、酉为面板，设计之象，辰酉合坐办公室。","sec":"一、技术人员命局的总规律","t":"rule"}]},{"n":113,"level":"高级","title":"职业象法八：银行工作人员","qs":[{"q":"银行象法里，「收」与「放」分别对应哪个方位五行？","opts":["西方金为放，东方木主收","东方木为放，西方金主收","南方火为放，北方水主收","东方木主收，西方金为放"],"ans":1,"exp":"银行吸收存款、发放贷款，用象法就是收与放：东方木为放，西方金主收。","sec":"一、银行命局的三条取象规律","t":"rule"},{"q":"局中同时出现卯与申，在银行取象上怎么看？","opts":["申为放卯为收，主证券业","只是木金相克，与银行无关","卯申组合为收放，容易是银行","卯申合为会计，与银行无关"],"ans":2,"exp":"收放组合包括卯酉、卯申、寅申、丑未，出现这类组合容易是银行。","sec":"一、银行命局的三条取象规律","t":"calc"},{"q":"哪两个字再配财星，就代表金融机构银行？","opts":["甲与寅","壬与亥","丙与午","庚与申"],"ans":3,"exp":"庚与申为金融之意，银行属金融机构，再配财星就代表银行。","sec":"一、银行命局的三条取象规律","t":"rule"},{"q":"亥、子、壬在职业象里与什么行业相关，需要与什么相连？","opts":["数字，与财星财库相连","药物，与食伤相连","文字，与印星相连","权力，与官杀相连"],"ans":0,"exp":"银行第一条取象规律：数字与财富发生关联，与会计组合类似，亥子壬为数字，与财星、财库相连。","sec":"一、银行命局的三条取象规律","t":"rule"},{"q":"十二地支里，哪个字能装财又是财库的地方，直接取银行象？","opts":["辰","丑","戌","未"],"ans":1,"exp":"丑是金库又是财库，能装财又是财库的地方就是银行。","sec":"配套细节象","t":"xiang"},{"q":"丑未冲在银行象里怎么取？","opts":["一收一放，丑代表寅，未代表酉","一生一克，丑代表酉，未代表亥","一收一放，丑代表酉，未代表寅","一动一静，丑代表子，未代表午"],"ans":2,"exp":"丑未冲＝一收一放，银行之象；丑代表酉（金），未代表寅（木）。","sec":"配套细节象","t":"xiang"},{"q":"杀印相生、官带财帽的结构，银行象里取什么？","opts":["发放贷款的业务员","仓库保管员","管账的会计","管财的官"],"ans":3,"exp":"杀印相生、官带财帽表示管财的官，官星带财就是管财。","sec":"配套细节象","t":"xiang"},{"q":"财星包局，取象怎么看？","opts":["单位都是钱，取象为银行","家里钱多，取象为富商","财被封死，取象为穷困","财被围住，取象为破财"],"ans":0,"exp":"财星包局表示单位都是钱，取象为银行；包局所包之神都可理解成一家。","sec":"配套细节象","t":"xiang"},{"q":"判断银行命局的步骤，第一步看什么？","opts":["做功方式是印做功还是食伤做功","收放字与金融字，是否与财星或财库绑定","大运岁运是否引动丑未冲","职位高低，是否包局"],"ans":1,"exp":"步骤：先找卯酉、卯申、寅申、丑未、庚申酉，是否与财绑定；再看做功，再定职位，注意双层职业，最后对运。","sec":"判断步骤","t":"step"},{"q":"银行命局中，什么结构才能当官（行长、经理）？","opts":["食伤泄秀、比劫成势","财星太旺、印星虚透","包局、杀印相生、印带官","官杀无制、印被坏"],"ans":2,"exp":"包局、杀印相生、印带官才能当官；官杀无制、印被坏只是职员。","sec":"判断步骤","t":"rule"},{"q":"运岁里出现什么情况，银行命局会离岗或不顺？","opts":["丑未冲被引动","卯申合被引动","寅申冲被运岁引动","子穿未，或合坏丑未冲、卯申合"],"ans":3,"exp":"丑未冲、卯申合被运岁引动是升职或入行；被子穿未、合坏则离岗或不顺。","sec":"判断步骤","t":"rule"},{"q":"戊己印星杂透，在职业象上主什么？","opts":["金融与法律两种工作性质","军警与财务两种工作性质","建筑与地产两种工作性质","医药与教育两种工作性质"],"ans":0,"exp":"戊己印星杂透为双层职业：金融＋法律。","sec":"判断步骤","t":"xiang"}]},{"n":114,"level":"高级","title":"职业象法九：地产商与建筑商","qs":[{"q":"下列干支柱中，哪一柱是戊土高岗取象高大建筑的象？","opts":["己未","乙卯","戊戌","丁丑"],"ans":2,"exp":"戊土为高岗，戊戌、戊申、戊辰、戊午参与做功取财，可以搞建筑；己未属木土组合一类，不是高岗象。","sec":"一、地产建筑命局的四类取象","t":"calc"},{"q":"卯戌合、卯未合、甲己合、寅未这类木土组合，取什么象？","opts":["钢筋水泥","酒店煤矿","高楼大厦","土木工程"],"ans":3,"exp":"木土组合＝土木工程；高楼取戊土，钢筋水泥取丑辰。","sec":"一、地产建筑命局的四类取象","t":"xiang"},{"q":"取「钢筋水泥」象的是哪两个地支，各藏什么？","opts":["丑中藏金、辰中藏乙","辰中藏癸、戌中藏丁","丑中藏金、戌中藏辛","辰中藏乙、未中藏乙"],"ans":0,"exp":"钢筋水泥取丑、辰两字：丑土中藏金，辰土中藏乙，丑辰参与做功。","sec":"一、地产建筑命局的四类取象","t":"xiang"},{"q":"十神中哪一个主房子，在地产命局里要参与做功？","opts":["食伤或食伤库","印或印库","官杀或官杀库","比劫或比劫库"],"ans":1,"exp":"四类象之一：印主房子，印或印库参与做功；辰为印库，辰戌冲就是印库做功。","sec":"一、地产建筑命局的四类取象","t":"rule"},{"q":"未、丑、戌三个地支，在地产类职业象里各代表什么？","opts":["未为高楼，丑为矿山，戌为煤矿","未为矿山，丑为高楼，戌为酒店","未为酒店，丑为煤矿，戌为高楼矿山","未为煤矿，丑为酒店，戌为高楼矿山"],"ans":2,"exp":"未代表酒店，丑为煤矿；戌代表高楼、矿山，戌在门户表地产建筑生意。","sec":"配套细节象","t":"xiang"},{"q":"财在墓库之中，被冲开、刑开，一般怎么论？","opts":["只有刑开才发财，冲开坏库","只有冲开才发财，刑开不发","冲刑开库都主破财","冲开、刑开都可以发财"],"ans":3,"exp":"只要财在墓库之中，冲开、刑开都可以发财。","sec":"配套细节象","t":"rule"},{"q":"丁印虚透，在地产命局里是什么象？","opts":["名誉，不是权力","学历，主读书","实权，掌管财权","房子，主置业"],"ans":0,"exp":"戊虚透、财虚透＝虚名、虚权；丁印虚透不是权力而是名誉。","sec":"配套细节象","t":"diff"},{"q":"木火燥土包局，又有印星参与，主什么？","opts":["官灾官司","能发大财","先富后破","不得财"],"ans":1,"exp":"木火燥土包局，印参与，能发大财；比劫夺财则先富后破。","sec":"配套细节象","t":"rule"},{"q":"原为官员的人下海经商，命局上常见什么原因？","opts":["比肩劫财得助，官星稳固","食神生财，印星被合","伤官配印格被破，财库被引动","官杀得制，印星旺透"],"ans":2,"exp":"原为官员下海，多是伤官配印格被破（如申亥相穿）、财库被引动，官位不久；打工起家多是印库（辰）加伤官配印。","sec":"判断步骤","t":"rule"},{"q":"判断地产建筑命局，走完找房子土木、看财库之后，第三步看什么？","opts":["婚姻星宫是否稳固","出身是官员还是打工","大运是否冲开财库","官杀与制化，能否制杀取财"],"ans":3,"exp":"步骤：先找房子与土木，再看财库，再看官杀与制化（制杀取财），再看出身，最后对运。","sec":"判断步骤","t":"step"},{"q":"地产命局里，哪种情形主先富后破？","opts":["杀无制、劫财夺财、比肩分财","财库刑开发财","印库被冲开","制杀取财成功"],"ans":0,"exp":"制杀取财成功可发大财；杀无制、劫财夺财、比肩分财则是先富后破。","sec":"判断步骤","t":"rule"}]},{"n":153,"level":"专题","title":"体用与宾主作用专题","qs":[{"q":"看父母，宫与星怎样受损才断父母亡？","opts":["体坏即断，用坏只主病","体用同时出问题才断，只坏一边不断","宫星任一受损即断亡","用坏即断，体坏只主病"],"ans":1,"exp":"生身父母只有一个、一生不能换，所以必须体（宫）用（星）同坏才下重断。","sec":"1. 宫为体，星为用","t":"rule"},{"q":"妻宫为忌且受冲，而妻星为喜、旺相，论刑妻吗？","opts":["要看妻星强弱才定","不论，妻星喜且旺则不克","论，体为忌受冲则不论用都克妻","只在流年再冲时才克"],"ans":2,"exp":"妻宫为体、妻星为用；体为忌、受冲，则不论用是喜是忌、强弱，都会克妻。","sec":"1. 宫为体，星为用","t":"calc"},{"q":"子女的体、用受损，分别应什么？","opts":["体受损＝生后遇凶；用受损＝小产","体受损＝晚年无子；用受损＝小产","体用都损才有子女之事","体受损＝小产；用受损＝生后遇凶"],"ans":3,"exp":"子女受胎时看体（母体），出生后以用为主；故体损小产，用损生后遇凶。","sec":"1. 宫为体，星为用","t":"diff"},{"q":"体制用与制体所出之物，哪个为正局？","opts":["体制用的东西为正，制体所出为反","制体所出之物为正，制用为反","制官杀为反，制财为正","只要制住，都论正局"],"ans":0,"exp":"水是官杀（用的东西），体来制，天经地义是正局；水是体自身生出的伤官，宜用不宜制，制它则成反局。","sec":"1. 正局与反局：谁是体、谁是用","t":"diff"},{"q":"财旺却无功，须怎样财才聚、才作功？","opts":["须比劫帮身，身强任财","须见官，官星统财才聚","须无官杀，财才不被分夺","须食伤生财，财越旺越好"],"ans":1,"exp":"财旺不等于有功，财多本身没有用，须见官，官统财才能聚；也可财去印、去劫财、入库。","sec":"2. 财多无功：何时有功","t":"rule"},{"q":"财（水）极大时，制财宜用哪种方式？","opts":["克制为主，越克越净","只有官星统财才行","合制或泄制，克制无功反害","三种制法效果相同"],"ans":2,"exp":"制财之法有合制、克制、泄制；水大时克制无功反害，宜合制、泄制。","sec":"2. 财多无功：何时有功","t":"rule"},{"q":"木火局与金水局，哪个先天有功？","opts":["金水局先天有功，木火局先天无功","两者都先天有功","两者都先天无功","木火局先天有功，金水局先天无功"],"ans":3,"exp":"火炎上、水润下：木火成势时时上伤官也制得住；金水成势，伤官成废神，只能务农或当兵。","sec":"3. 木火局有功，金水局先天无功","t":"rule"},{"q":"「合用财星」与「合用官星」，看法的区别是？","opts":["合财看身强弱；合官看官下之支","两者都看所坐之支","合官看身强弱；合财看财下之支","两者都看身强弱"],"ans":0,"exp":"合财要看身之强弱（弱喜财虚透、旺喜财旺相）；合官没有这种说法，要看官下之支是什么。","sec":"4. 合用官星、合用财星","t":"diff"},{"q":"日支被制，哪类星可制？","opts":["正偏都可制","偏的可制，正的一般不可制","正的可制，偏的不可制","正偏都不可制"],"ans":1,"exp":"日支被制也是做功：杀坐支、偏的可制，制则做功；正的一般不可制，制则伤亲人。","sec":"5. 合禄局与日支被制","t":"rule"},{"q":"下列四柱，哪一柱干支同象（天干属性可与地支同看）？","opts":["乙亥","壬申","癸卯","己巳"],"ans":2,"exp":"凡天干生地支的柱子才同象：癸生卯；乙亥、己巳、壬申都是支生干，不同象。","sec":"4. 天干异性相克与同象","t":"calc"},{"q":"天干之间异性相克，功如何？","opts":["只在天干气弱时无功","同性异性相克功相同","有功，且大于同性相克","无功，除非合制"],"ans":3,"exp":"天干异性相克无功（除合制外）；同性相克功也不大，天干气弱则更小。","sec":"4. 天干异性相克与同象","t":"rule"},{"q":"看盘时，判断谁来作功的先后顺序是？","opts":["日主，再日支，再日主的延伸物","日支，再日主，再延伸物","月令，再日主，再日支","先定身强弱，再看从与不从"],"ans":0,"exp":"先看日主是否参与作功；不参与看日支；再不参与看延伸物。日主不参与就弃之不看，强弱无关紧要。","sec":"2. 看盘顺序","t":"step"}]},{"n":154,"level":"专题","title":"应期与墓穿专题","qs":[{"q":"按盲派，流年在应期上管什么？","opts":["管年龄段，一柱管若干年","只管吉凶，不管应期","只管应期，吉凶由原局与大运定","既管应期，也直接定吉凶"],"ans":2,"exp":"流年只起引动作用，必须配合大运与原局才定吉凶；大运才是定吉凶的一层。","sec":"一、应期的基本框架（补充）","t":"rule"},{"q":"行地支大运时，体用怎么分？","opts":["天干为体，地支为用","干支皆为体","干支皆为用，以原局为体","地支为体，天干为用"],"ans":3,"exp":"行天干运天干为体、地支为用；行地支运则反过来，地支为体、天干为用。","sec":"一、应期的基本框架（补充）","t":"rule"},{"q":"原局有卯（木禄），流年见乙，和原局有未，流年见乙，两种情形的「虚到」分别怎么论？","opts":["乙代卯主虚透弱化；乙代未只主到位","两种都主弱化","乙代卯只主到位；乙代未主虚透弱化","两种都只主到位，不弱化"],"ans":0,"exp":"禄神虚到大运流年主虚而弱化；墓神或余气虚到不弱化，只表示到位。乙对应卯、未、辰。","sec":"一、应期的基本框架（补充）","t":"calc"},{"q":"按干支互应对照，庚、辛、壬三个天干在流年出现，各自主要应到哪些地支？","opts":["庚应申、丑；辛应酉、戌；壬应亥、申","庚应申；辛应酉、丑；壬应亥、申","庚应申、酉；辛应酉；壬应亥、子","庚应申；辛应酉；壬应亥、子"],"ans":1,"exp":"互应表：庚—申，辛—酉、丑，壬—亥、申。辛可应丑，壬可应申，是易漏处。","sec":"一、应期的基本框架（补充）","t":"calc"},{"q":"大运与八字有合时，流年冲大运，「当运」与「不当运」有何不同？","opts":["不当运为冲去，当运为引动","不当运为破合，当运为引动","不当运为引动，当运为冲去","无论当运与否都是冲去"],"ans":2,"exp":"冲运：不当运是引动，当运才是冲去；冲的若是八字中的字，应论破合。","sec":"一、应期的基本框架（补充）","t":"diff"},{"q":"子、午、酉、卯见各自的墓（如酉见丑），一般怎么论？","opts":["以破论，墓气外泄","一律以入墓论","以冲论，墓被冲开","因有半合局，以拱合论，不以墓论"],"ans":3,"exp":"子午酉卯见各自墓一般不以墓论；但中神已很弱要死时见墓才为应期，死、墓、绝三者为应。","sec":"六、墓的细则","t":"rule"},{"q":"年支午、月支戌，位置先后相对，在盲派里算什么？","opts":["拱，不是入墓","入墓，须年支在前","入墓，位置先后不影响","冲，午戌相对为冲"],"ans":0,"exp":"午戌、子辰之类位置相对是拱，不是入墓；寅申巳亥见墓入之、多而墓之才是入墓。","sec":"六、墓的细则","t":"diff"},{"q":"「害」对墓库起什么作用？","opts":["害可以开墓","害不能开墓","害只能开阳库不能开阴库","害能开墓但力量弱"],"ans":1,"exp":"占事盘里戌库与酉相害，害不能开墓，所以鸟出不了门；刑、冲才可开库。","sec":"六、墓的细则","t":"rule"},{"q":"禄神在八字中出现（含伏吟），什么情形下才算凶？","opts":["只要禄伏吟就凶","只要禄被财星见到就凶","禄无功、遭局中回制穿害，或单薄无助","禄为功神且合气势时才凶"],"ans":2,"exp":"禄是功神且局中是禄的气势，伏吟反而发迹；禄无功、被回制穿害、单薄无助，出现则凶。","sec":"六、墓的细则","t":"rule"},{"q":"八字中一方两个戌、一方一个辰（戌辰戌戌之类），戌冲辰结果如何？","opts":["双方相抵，辰戌皆无损","三戌拱辰，辰得保护","辰反冲戌，戌被冲坏","一方二、一方一不平衡，辰被冲坏"],"ans":3,"exp":"一方两个、一方一个，力量不平衡，少数一方坏；若夹在两边则是夹冲，与夹刑不同论。","sec":"六、墓的细则","t":"rule"}]},{"n":155,"level":"专题","title":"伤官、六亲与命格组合专题","qs":[{"q":"金水伤官的喜忌，按盲派口诀是哪一条？","opts":["喜见财官，怕见印","喜见印，怕见官","喜见印，怕见官，喜见杀","喜见官，怕见印"],"ans":3,"exp":"金水伤官喜官怕印；喜印怕官是土金伤官，喜财官怕印是水木伤官，别串口诀。","sec":"一、伤官诀","t":"rule"},{"q":"「金水伤官喜见官」这条口诀，用在原局和大运上有什么区别？","opts":["只适用原局，大运见官反而不好","只适用大运，原局不论","原局大运都适用，见官皆吉","原局忌官，大运喜官"],"ans":0,"exp":"金水伤官喜官只对原局成立；大运见官星（如午运）会出事，不能照搬。","sec":"一、伤官诀","t":"diff"},{"q":"土金伤官「怕见官」，原局与大运的口径是什么？","opts":["原局不忌，大运忌见官","原局忌见官，大运不忌","原局、大运都忌见官","原局、大运都不忌见官"],"ans":1,"exp":"土金伤官怕官是原局的忌，大运见官不忌（如癸卯运升总督）。","sec":"一、伤官诀","t":"diff"},{"q":"土金伤官原局里既有伤官、又有官星，但两者不相见（不在一起相碰），怎么论？","opts":["照样坏格，按伤官见官论","只看官星，伤官不论","不坏格，按伤官合官杀论","格局降一档，只能守财"],"ans":2,"exp":"伤官与官不「相见」就不坏格；相见才是伤官见官坏格。","sec":"一、伤官诀","t":"rule"},{"q":"土金伤官见官，官星以卯酉相见与以寅申相见，结论有何不同？","opts":["卯酉见者格可大，寅申见者格小","两者都不坏格，格局一样大","卯酉与寅申都只能做普通人","卯酉见者格小，寅申见者格可大但坏格"],"ans":3,"exp":"口诀总结：卯酉相见格小；寅申相见格可大，但仍是坏格。","sec":"一、伤官诀","t":"diff"},{"q":"水木伤官与土金伤官，对「官」的态度分别是？","opts":["水木伤官见官为吉，土金伤官怕见官","两者都喜见官","两者都怕见官","水木伤官怕见官，土金伤官喜见官"],"ans":0,"exp":"水木伤官喜见财官；土金伤官喜印怕官。两类对官的态度相反。","sec":"一、伤官诀","t":"diff"},{"q":"火土伤官里，哪种日主与伤官的组合较好？","opts":["丙火见戊土","丁火见戊土，伤官佩制","丙火见己土","丁火见己土"],"ans":1,"exp":"火土伤官看组合：丁见戊较好（制水有功），丙见己反而容易坏格。","sec":"一、伤官诀","t":"rule"},{"q":"丁火日主，按盲派「父星」标准（不论男女），下列哪个字可以当父星？","opts":["甲（印）","丁（比肩、禄）","辛（偏财）","己（食神）"],"ans":2,"exp":"财官杀为父：丁日财为庚辛、官杀为壬癸，辛是财；己食神、丁比劫属母星一路，甲是印不当父。","sec":"二、六亲","t":"calc"},{"q":"命中找到父母星，有父母相克的信息，却看不出任何一方死亡，按盲派口诀怎么断？","opts":["父亲早亡","父母同住但不和","母亲早亡","一定是父母离异"],"ans":3,"exp":"口诀：看到父母相克信息而看不出一方死亡，那一定是离异。","sec":"二、六亲","t":"rule"},{"q":"「父星双合、伏吟」与「母星双合」，各应什么？","opts":["父别娶；母改嫁","父早亡；母早亡","父母都主离异但各自不再婚","父改嫁；母别娶"],"ans":0,"exp":"口诀：父星双合、伏吟，父别娶；母星双合，母改嫁。","sec":"二、六亲","t":"diff"},{"q":"按盲派过河拆桥命格的基本原理，发大财的关键是什么？","opts":["宾位财重生主位官杀，把财弄住","主位财重生宾位官杀，把官杀弄住","主位财轻，靠大运补财","主位官杀重，让财星透出"],"ans":1,"exp":"主位财重生宾位官杀，官杀聚集财的能量，制住、合住或穿住官杀就发大财。","sec":"三、过河拆桥命格","t":"rule"},{"q":"过河拆桥命格里，「弄住」宾位官杀的功，原局与大运有何差别？","opts":["只有大运弄住才算数","原局弄住功小，大运弄住功大","原局弄住功大，大运弄住功小","原局和大运功力一样大"],"ans":2,"exp":"原局弄住的功大，大运弄住的功小。","sec":"三、过河拆桥命格","t":"diff"}]},{"n":156,"level":"专题","title":"象法与象的应用专题","qs":[{"q":"按盲派「体、用、象」框架，十个天干、十二个地支属于哪一项？","opts":["体","象","用","局"],"ans":0,"exp":"干支本身是体；五行生克、干支关系、十神宫位是用；体与用结合形成的具体判断是象。","sec":"一、体、用、象","t":"rule"},{"q":"下列哪一项属于「用」而不是「体」或「象」？","opts":["体与用结合后的具体结论","十神与宫位","十个天干","十二个地支"],"ans":1,"exp":"用指五行生克、干支关系、十神与宫位；干支是体，最后的结论才是象。","sec":"一、体、用、象","t":"diff"},{"q":"天干相合为反象：甲己合，谁喜谁不喜？","opts":["甲喜己合，己不喜甲合","两者都喜","己喜甲合，甲不喜己合","两者都不喜"],"ans":2,"exp":"尊卑之合，卑者被尊者所合则喜，尊者被卑者反合则不喜。","sec":"3. 天干合为反象","t":"rule"},{"q":"按干合反象，丁壬（大小之合）这一合里，谁喜谁不喜？","opts":["丁壬都不喜","丁壬都喜","壬喜丁合，丁不喜壬合","丁喜壬合，壬不喜丁合"],"ans":3,"exp":"口诀：丁壬大小之合，丁喜壬合，壬不喜丁合，被合者小者喜。","sec":"3. 天干合为反象","t":"calc"},{"q":"原局有两丙、两寅，没有别的眼睛象。看眼睛，按盲派对称性取象，可以怎么看？","opts":["对称的火可象眼睛","对称的金可象眼睛","对称的木可象眼睛","对称的水可象眼睛"],"ans":0,"exp":"凡对称性的火（两丙、两丁、两午、两戌、两巳、两寅）都可以象眼睛。","sec":"3. 命例","t":"calc"},{"q":"盲派说「亥为计算」，要取会计、出纳之象，亥要满足什么条件？","opts":["亥与印星相关，如合印、生印","亥与财星相关，如合财、被财墓、本身是财","亥与比劫相关，如合比劫、临禄","亥与官星相关，如合官、被官克"],"ans":1,"exp":"亥水与财星相关（合财、被财墓、本身是财、冲制财星等），多为会计出纳。","sec":"2. 各支取象（要点）","t":"rule"},{"q":"同样食神，卯木为食神与辛金为食神，各自喜食什么？","opts":["卯木食神喜食面，辛金食神喜食肉","卯木食神喜食肉，辛金食神喜食面","卯木食神喜食面，辛金食神喜食米","卯木食神喜食米，辛金食神喜食面"],"ans":2,"exp":"卯细长如面，故卯木食神喜食面；辛金食神喜食米。","sec":"2. 各支取象（要点）","t":"diff"},{"q":"盲派地支取象中，「辰」的关键象是什么？","opts":["思想","公门","律令","车"],"ans":3,"exp":"辰为车；寅为公门，巳为思想，申为律令、收敛。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"地支「寅」与「申」的关键象，下列哪组对？","opts":["寅为公门，申为律令、收敛","寅为思想，申为武库","寅为律令，申为公门","寅为车，申为计算"],"ans":0,"exp":"寅为公门（政府机关、组织），申为律令、收敛（司法、金融）。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"取象的几种方式里，「干支得墓库，有集团性、聚集性」属于哪一种？","opts":["共象","墓象","带象","换象"],"ans":1,"exp":"墓象指得墓库而有聚集性；共象是本象加十神象，换象是制与被制互换，带象是干支相生。","sec":"1. 取象的几种方式","t":"step"},{"q":"换象与带象的区别是哪项？","opts":["换象是干支相生；带象是制过后互换","换象是得墓库聚集；带象是组合成局","换象是制过后互换；带象是干带支象","换象是本象加十神象；带象是相合而成"],"ans":2,"exp":"换象：地支冲制、合制，被制方与制方可换象使用；带象：干支相生，干能带支象，支能带干歇脚。","sec":"1. 取象的几种方式","t":"diff"},{"q":"盲派「借象」的两种关系是什么？","opts":["天干通墓库，或同五行阴阳相同的字","天干通长生，或同阴阳五行不同的字","天干通合神，或相冲的两个字","天干通禄神，或同五行阴阳不同的字"],"ans":3,"exp":"借象口诀：天干通禄神、同五行但阴阳不同的字，可互借其象，如丙与巳、寅与卯。","sec":"4. 借象","t":"rule"}]},{"n":157,"level":"专题","title":"职业专题（一）：口才求财与会计","qs":[{"q":"按盲派，财星入库而库不开，职业上意味着什么？","opts":["钱是祖上的，靠继承家业过日子","钱是替别人管的，做会计业务打工","钱存得住，适合自己当老板做事","钱会被劫财分走，只能合伙经营"],"ans":1,"exp":"库不开则财不是自己的，只能替人管、替人干；库被冲开才可能自己赚到。","sec":"一、职业取象的总方法","t":"rule"},{"q":"用伤官、食神做功的技术类职业人，对投资的态度应是（　）。","opts":["宜投资，只要财星入库就不会破","宜投资，食伤生财越投越旺发","不宜风险投资，投资劫财合财必破","可投资但只能合伙，不能独资干"],"ans":2,"exp":"食伤做功靠技术口才吃饭，一投资引来劫财合财，必破。","sec":"一、职业取象的总方法","t":"rule"},{"q":"同样见子水、亥水，下面哪种情形才可以断会计？","opts":["八字里见到子水或亥水就可断会计","子水亥水只要入了墓库就可以断","子水亥水与比劫合化以后就可以断","数字之象、做功、单位三者俱备"],"ans":3,"exp":"见子亥不一定是会计，必须数字之象+做功+单位三者俱备。","sec":"三、会计与数字之象","t":"diff"},{"q":"按本教材，亥水、子水在八字里主什么象？","opts":["数字、计算、液体","药罐、化学、制药","电子、媒体、手","金属、针、牙、骨"],"ans":0,"exp":"亥子水主数字计算液体；午火主电子媒体手；酉金主金属针牙骨；辰为药罐化学。","sec":"一、职业取象的总方法","t":"xiang"},{"q":"按本教材，戌土主哪类象？","opts":["服务、体力、出力一类的行业","火药刀枪学校，也主酒店娱乐场所","药罐、化学、制药一类的东西","金属、针、牙、骨一类的东西"],"ans":1,"exp":"戌为火库，主火药刀枪学校；业务章里又主电器、娱乐场所、酒店。辰为药罐化学，未为服务体力。","sec":"一、职业取象的总方法","t":"xiang"},{"q":"财星虚透并带驿马，落在年或时，职业上多主什么？","opts":["财入墓库，适合专门做管账事","财在内，守着本地稳稳做生意","财在外，需出门求财，多跑动","财稳固，适合安坐办公室工作"],"ans":2,"exp":"财虚透带驿马在年时，财在外面，要出门求，多是业务、打工。","sec":"二、口才与业务求财","t":"rule"},{"q":"业务员命中「禄做功」与「用比劫制财」的职业含义，区别是（　）。","opts":["禄做功是自己当老板，比劫制财是打工","禄做功是打工，比劫制财是辛苦求财","两者都是自己当老板，只是辛苦不同","禄做功是辛苦求财，比劫制财是打工"],"ans":3,"exp":"规律小结：禄做功辛苦求财；用比劫制财是打工；财库不开不是自己的钱。","sec":"4. 规律小结","t":"diff"},{"q":"业务命中「合劫财而拿货」，按盲派取象是（　）。","opts":["从别人那里拿产品去卖","把货物卖给合伙的那个人","产品被劫财抢走，卖不出去","自己生产产品再卖给别人"],"ans":0,"exp":"合劫财是向别人拿东西，所以是拿货销售而非自己生产。","sec":"2. 行业落点","t":"rule"},{"q":"子、未两字相见，按盲派会计之象，应怎么论？","opts":["子未合，水土相合，主财库聚拢","子未穿，数字穿财做功，会计典型","子未冲，子水冲未土，主官司是非","子未穿，水土相克，只主脾胃毛病"],"ans":1,"exp":"子水为数字，未为财，穿为做功，是会计的典型组合。","sec":"2. 取象要点","t":"rule"},{"q":"会计命中，天干透甲木坐印、透食神，各表示什么？","opts":["甲木坐印是办公室，透食神是打工","甲木坐印是做公职，透食神是业务","甲木坐印是打工，透食神是坐办公室","甲木坐印是自己开业，透食神是打工"],"ans":2,"exp":"天干透甲木坐印，是打工之象；透食神，是坐办公室之象。","sec":"2. 取象要点","t":"rule"}]},{"n":158,"level":"专题","title":"职业专题（二）：医生、教师与军官","qs":[{"q":"按盲派取象，医生命局里官杀和食伤各代表什么？","opts":["官杀为药或刀，食伤为病人","官杀为医院，食伤为病人","官杀为病人，食伤为药或刀","官杀为药，印星为刀"],"ans":2,"exp":"伤官（食伤）制官杀，是医生；官杀制不了的，可以当病人看。","sec":"四、医生","t":"xiang"},{"q":"医生命局中，辛金与申金的取象有何不同？","opts":["申金代表针头，辛金不代表","辛、申都代表针头","辛金代表手术刀，申金代表针头","辛金代表针头，申金不代表"],"ans":3,"exp":"明文：辛金代表针头，申金则不代表。","sec":"四、医生","t":"xiang"},{"q":"医生命局中，制酉金、辰土、卯木分别主哪类医术？","opts":["制酉为牙科骨科，辰为药物研究，卯为中医","制酉为药物研究，辰为牙科骨科，卯为中医","制酉为牙科骨科，辰为中医，卯为药物研究","制酉为中医，辰为牙科骨科，卯为药物研究"],"ans":0,"exp":"酉主骨骼牙齿筋骨，辰为药罐汤水化学，卯为花草吃喝所以是中医。","sec":"四、医生","t":"xiang"},{"q":"时上食神坐丑，局中又有丑未相冲，是医生，按盲派最宜断哪一科？","opts":["骨科","妇产科","药物研究","牙科"],"ans":1,"exp":"食神在时上主女性、孩子，坐丑为子息宫、生殖系统，丑未冲是制丑，故为妇产科。","sec":"四、医生","t":"calc"},{"q":"用食神伤官做功的医生（或教师），在财运上有什么忌？","opts":["只忌官杀投资，食伤投资无碍","食伤是实的，才可搞风险投资","食伤是实的，不能搞风险投资","必须多投资，才能引动食伤"],"ans":2,"exp":"用食伤做功的人，食伤实则绝对不能风险投资；劫财高透坐食伤库更爱赌、十赌九输。","sec":"四、医生","t":"rule"},{"q":"医生的医术高低，按盲派主要看什么？","opts":["看印：印重则必然医术一般","看比劫：比劫重坏印则医术一般","看官：官重坏印则医术一般","看财：财重坏印则医术一般"],"ans":3,"exp":"财重坏印则医术一般；入墓的财库当食神看，医术就会提高。","sec":"四、医生","t":"rule"},{"q":"木火伤官制印，看似求官，为何教师命不论作官？","opts":["日主所求不是官，靠食伤在门户的口才吃饭","因为伤官见官，必定是师","因为官星入墓，无法求官","因为印星太旺，不需制官"],"ans":0,"exp":"官师分界：甲己合等告诉你不是当官的命，教师靠口才吃饭，不是官。","sec":"五、教师","t":"diff"},{"q":"教师命里，时上伤官坐财库，各取什么象？","opts":["伤官为学生，财库为风险投资","伤官为学生，财库为工作单位","伤官为单位，财库为学生","伤官为校长，财库为学生"],"ans":1,"exp":"时上伤官主孩子、学生，座财库，财库是工作单位；中学生是大点的孩子，小学生是小孩。","sec":"五、教师","t":"xiang"},{"q":"教师命里「官星两头合」与「卯午破」各象征什么？","opts":["两者都是学生不听话","官星两头合为学生不听话，卯午破为学生听话","官星两头合为学生听话，卯午破为学生不听话","两者都是学生听话"],"ans":2,"exp":"明文：官星两头合，听话；卯午破，学生不听话。","sec":"五、教师","t":"xiang"},{"q":"军官命里戌土取什么象？戌被刑冲打开主什么？","opts":["水库、药库；行医或买房","书库、文库；考学或升学","金库、财库；发财或破财","火药库、刀枪库；当兵或提升"],"ans":3,"exp":"带火药的字做功必是部队；戌土被刑冲打开，当兵或提升。","sec":"六、军官","t":"xiang"},{"q":"日主坐库，库「开」与「不开」分别如何论？","opts":["刑冲开则为库，不开则为墓","开与不开都是库","开与不开都是墓","刑冲开则为墓，不开则为库"],"ans":0,"exp":"日坐库一定要刑冲，刑冲开才为库，不开就成墓。","sec":"六、军官","t":"rule"},{"q":"下列哪组都是军官命里「提升」的应期规律？","opts":["官杀生印、印库被冲、财生杀、伤官合官","官杀被制、印库出现、杀库被冲、伤官合杀","官杀被制、印库被合、杀库被冲、食神制印","官杀被合、印被财生、杀库被填、食神合杀"],"ans":1,"exp":"提升应期：官杀被制、印被制、印库出现、财制印、杀库被冲、伤官合杀、食神合印。","sec":"六、军官","t":"step"}]},{"n":159,"level":"专题","title":"疾病专题","qs":[{"q":"按盲派看病，阴阳失衡时，失阳和阳亢的后果分别是什么？","opts":["失阳主代谢停止；阳亢主血瘀不通","失阴易死亡；失阳多血压高","失阳多血压高；阳亢易死亡","失阳易死亡；阳亢血压高"],"ans":3,"exp":"失阳者容易死亡；阳多阴少则血压高、心脏出问题。阴多阳少、灭阳才是代谢停止、水湿凝聚。","sec":"一、总纲：三条看病原则","t":"diff"},{"q":"日主左右两边都是克泄之神（如官杀或枭神夹日），按盲派主什么？","opts":["夭命大凶，依靠被运克即死期","主身弱多病，印运来时可解","主多病缠身，但逢印运可过关化解","主心脏病，应期在冲日支之年发作"],"ans":0,"exp":"凶神夹日主夭命大凶，命中唯一的依靠被大运克，就是死期。","sec":"一、总纲：三条看病原则","t":"rule"},{"q":"原局有「卯」与「午」两字，卯破午，主身体出什么问题？","opts":["肝胆疏泄不力，主糖尿病症","血管破裂出血，重则脑溢血","肝火伤心，主失眠心悸神乱","血液凝滞不通，主血脂血稠"],"ans":1,"exp":"卯为血管，午为心脏，卯破午即血管破、出血，重则脑出血、心肌梗死。","sec":"三、干支组合与病性","t":"calc"},{"q":"原局有「寅」「亥」相合，主什么病性？","opts":["湿土壅肺，哮喘咳嗽不止","阳盛阴弱，血压升高心悸","水湿伤肝，血脂高、生痰","火克金伤血，重则成白血病"],"ans":2,"exp":"寅亥合是水湿浸木，肝失疏泄，主风湿、血脂高、心脏病，水湿生痰重则精神怪病。","sec":"三、干支组合与病性","t":"calc"},{"q":"原局辰、丑两字相合化金，主哪个脏腑出毛病？","opts":["肝郁气滞，头晕失眠","肾与膀胱，尿频尿急","脾胃失调，消化不良","肺壅，哮喘、咳嗽"],"ans":3,"exp":"丑辰合金，辰丑为湿土壅住金水之肺，成肺壅、哮喘、咳嗽。","sec":"三、干支组合与病性","t":"calc"},{"q":"按盲派的身体象法，地支「酉」和「戌」分别主什么？","opts":["酉主肺耳；戌主心包心胃","酉为肾、泌尿；戌为心脏、血压","酉为神经、面；戌为脾胃、体力","酉为大肠、骨；戌为膀胱、淋巴"],"ans":0,"exp":"酉主肺、耳，戌主心包、心、胃、神经，所以酉戌穿伤肺、心、神明。","sec":"二、干支象法对应身体","t":"xiang"},{"q":"按盲派的身体象法，子、丑、午三个地支分别主什么？","opts":["子主心脏血压；丑主脾胃；午主肾泌尿","子主血肾；丑主生殖；午主心脏","子主管道关节；丑主肺；午主头面神经","子主膀胱前列腺；丑主心包；午主血液肾"],"ans":1,"exp":"子为血液、肾、泌尿；丑为生殖器、妇科、肛门；午为心脏、阳亢、血压、神经。","sec":"二、干支象法对应身体","t":"xiang"},{"q":"天干甲、庚、辛在身体上分别对应什么？","opts":["甲主颈、毛发；庚主肺；辛主大肠","甲主头胆；庚主小肠；辛主膀胱口","甲主头胆；庚主大肠；辛主肺齿","甲主胃鼻；庚主大肠；辛主肌肤腹"],"ans":2,"exp":"天干象：甲头胆，庚大肠，辛肺齿。乙才是颈、毛发，丙才是小肠。","sec":"二、干支象法对应身体","t":"xiang"},{"q":"按盲派，糖尿病的三种机制是什么？","opts":["土来浊水、阳亢血热、肝肾同源","胃热消食、肺壅湿滞、肝脾失调","金水不通、胃热消食、阴阳离决","土来浊水、胃热消食、肝脾失调"],"ans":3,"exp":"糖尿病三机制：水主血或尿、土主甜，土来浊水；胃热消食（消渴）；肝脾失调，多数与燥热有关。","sec":"九、糖尿病","t":"rule"},{"q":"盲派看疾病的判断步骤，正确顺序是什么？","opts":["先阴阳平衡，再找被坏字，后看运岁","先看大运流年引动，再看阴阳平衡，最后找被坏的字","先找被坏的字，再看阴阳平衡，最后看运岁引动","先看日主旺衰，再找被坏的字，最后看用神有根无根"],"ans":0,"exp":"先看阴阳是否平衡、有无阳亢灭阳凶神夹日，再查原局被坏的字对应部位，最后由大运流年引动定发病与应期。","sec":"十、判断步骤","t":"step"},{"q":"盲派看死亡应期，主要看什么年份？","opts":["日支被冲或被刑之年","唯一依靠被克绝、穿、合绊之年","印星入墓之年","大运交脱之年"],"ans":1,"exp":"死亡应期看用神（唯一的依靠）被克绝、被穿、被合绊之年。","sec":"十、判断步骤","t":"rule"}]},{"n":160,"level":"专题","title":"婚姻问答专题","qs":[{"q":"看婚姻时，主次关系是（　）。","opts":["配偶宫（日支）为主，配偶星为辅","配偶宫与配偶星只看合冲，不分主次","年柱为主，日支与配偶星同为辅","配偶星为主，配偶宫（日支）为辅"],"ans":0,"exp":"婚姻以配偶宫（日支）为主，配偶星为辅，再抓配偶宫的延伸副宫。","sec":"一、看婚姻的要点","t":"rule"},{"q":"配偶宫与配偶星发生哪一类关系，表示婚姻出问题而不是有缘？","opts":["相冲也属一种关联，不算出问题","相穿、相刑、相破","相生、相合、拱合","天干压地支、地支带天干"],"ans":1,"exp":"生合拱为好缘；冲是关联；穿刑破表示婚姻出问题。","sec":"一、看婚姻的要点","t":"diff"},{"q":"下面哪一条属于好婚姻的条件？","opts":["夫妻宫暗合配偶星以外的星","夫妻宫多现，配偶星也多现","夫妻宫安静，不被刑冲穿破、不杂透多现","夫妻宫被刑冲，表示感情热烈"],"ans":2,"exp":"好婚姻要求宫安静：有用时不被刑冲破穿，不六合暗合他星，不杂透多现。","sec":"二、好婚姻的条件","t":"rule"},{"q":"女命丑为夫宫、寅为夫星，寅丑暗合，按盲派这表示（　）。","opts":["夫星合走夫宫，丈夫容易另有新欢","寅丑暗合为他合，婚姻不稳必离","夫宫制夫星，女管丈夫但婚姻差","夫星合到夫宫，丈夫只跟自己好"],"ans":3,"exp":"配偶星合到配偶宫，表示配偶只跟自己好；他合才是合走。","sec":"二、好婚姻的条件","t":"calc"},{"q":"夫妻宫被破坏的程度与离婚的关系是（　）。","opts":["破坏轻则不一定离，太重必离，宫未坏不离","只要宫被刑冲穿破，就一定离婚","宫被破坏即分居，外遇才是离婚","宫未坏但有外遇分居，就必然离婚"],"ans":0,"exp":"能否离婚看宫的破坏程度：轻者不一定离，重者必离，宫未坏即使分居、外遇也不离。","sec":"三、差婚姻的组合与离婚的程度","t":"rule"},{"q":"配偶的正星与偏星，对「制」的要求区别是（　）。","opts":["正星可以制，偏星不可制","偏星可以制，正星不可制","正星偏星都可制，只看力量","正星偏星都不可制，制必离婚"],"ans":1,"exp":"男命正财、女命正官为正星，受制则婚姻易出问题；偏财、七杀为偏星，可以制。","sec":"四、多婚的判断规则","t":"diff"},{"q":"因夫（妻）宫被坏而离婚的，判断婚姻次数应怎么数？","opts":["夫妻星有几个，就是几次婚姻","大运走几步配偶运，就是几次婚姻","坏宫的东西有几个，就是几次婚姻","夫妻宫出现几次，就是几次婚姻"],"ans":2,"exp":"宫被坏离婚的看坏它的东西有几个；星多现离婚的才看配偶星有几个。","sec":"四、多婚的判断规则","t":"step"},{"q":"「一星两宫」：夫星拱合夫宫，但命中有两个夫宫的字，怎么断？","opts":["必离婚，第二次一定白头到老","会有两次婚姻，两字在日时伏吟也一样","只有一次婚姻，两宫相合更稳","会有两次婚姻，若两字在日时伏吟则不算二婚"],"ans":3,"exp":"第一次合不到位，会有两次婚姻；两字日时伏吟则不表示二婚。","sec":"四、多婚的判断规则","t":"rule"},{"q":"女命夫宫坐偏印、时柱占禄，按盲派属于哪种命局组合？","opts":["独身组合","好婚姻组合","多婚组合","夫星合夫宫的组合"],"ans":0,"exp":"夫宫坐偏印、时占禄、日时逢禄印，日时不见财官而劫逢劫印，都是独身组合。","sec":"五、独身命","t":"rule"}]},{"n":161,"level":"专题","title":"答疑汇编专题（一）：作功、体用、反局与合用","qs":[{"q":"盲派看八字，判断谁作功，先后顺序是哪个？","opts":["日支，其次月令，再看日主","日主，其次日支，再看日主的延伸物","月令，其次日主，再看时柱","用神，其次日主，再看日支"],"ans":1,"exp":"先看日主是否作功；不参与则看日柱（日支）；再不行看日主延伸物。不先看身强弱或从与不从。","sec":"2. 先看谁作功","t":"step"},{"q":"日主与日支表达的意思不一致时，以谁为主？","opts":["以日支为主","以月令为主","以日主为主","以势大的一方为主"],"ans":2,"exp":"作功顺序里明文：日主与日支意思不一致，以日主为主。","sec":"2. 先看谁作功","t":"rule"},{"q":"「木火局」与「金水局」的先天作功情况，下列哪个对？","opts":["木火与金水局都先天有功","金水局先天有功，木火局先天无功","木火与金水局都先天无功","木火局先天有功，金水局先天无功"],"ans":3,"exp":"木火「火炎上」，木见火燃烧本身就作功；金水「水润下」先天无功。","sec":"3. 好命与差命","t":"diff"},{"q":"财多的八字要作功，口诀说财作功有哪三式？","opts":["去印、去劫、入库","去劫、生官、入库","去印、去官、入库","去食、去劫、合官"],"ans":0,"exp":"口诀：财多无功要见官；财作功三式：去印、去劫、入库。","sec":"4. 学历、职业、财官怎么用作功看","t":"rule"},{"q":"日主身弱、水为财且很多而无功，要让财「入库」作功，需见下列哪个字？","opts":["丑","辰","戌","未"],"ans":1,"exp":"财多无功，入库是作功三式之一；辰是水库（本章以辰库收财为例）。","sec":"4. 学历、职业、财官怎么用作功看","t":"calc"},{"q":"体用关系中，「行干运」与「行支运」怎么分体用？","opts":["行干运与行支运都是大运为体","行干运与行支运都是原局为用","行干运支为体干为用；行支运干为体支为用","行干运干为体支为用；行支运支为体干为用"],"ans":2,"exp":"行干运，支为体，干为用；行支运，以干为体，支为用。","sec":"二、体用的多种用法","t":"rule"},{"q":"看六亲的体用，「宫位」与「星」哪个是体哪个是用？","opts":["星为体，宫位为用","两者都是用","两者都是体","宫位为体，星为用"],"ans":3,"exp":"宫位是定的，星可以变（如婚姻，家是定的，进来的女主人可变）。","sec":"二、体用的多种用法","t":"diff"},{"q":"盲派看父母，怎样才断父母过世？","opts":["体用同时出问题","印星被克","仅体出问题","仅用出问题"],"ans":0,"exp":"生身父母一生不能换，不像婚姻那样看；体用同时出问题，才断过世。","sec":"二、体用的多种用法","t":"rule"},{"q":"按同象规则，癸卯、丁丑、甲子、乙亥四柱，哪一柱天干与地支「同象」？","opts":["甲子、乙亥","癸卯、丁丑","丁丑、乙亥","癸卯、甲子"],"ans":1,"exp":"天干生地支的柱子同象（癸生卯、丁生丑）；支生干（子生甲、亥生乙）不算。","sec":"1. 同象","t":"calc"},{"q":"按盲派，天干异性相克（非合制）是什么结果？","opts":["有功但会被冲坏","功大","无功","功小"],"ans":2,"exp":"同性相克功不大；天干异性相克无功（除了合制）。","sec":"2. 虚实","t":"rule"},{"q":"反局的两种类型是什么？","opts":["合局反局与冲局反局","原局反局与流年反局","日主反局与月令反局","原局反局与大运反局"],"ans":3,"exp":"原局反局是日主或日柱意思与八字整体相反；大运反局是大运与原局意向对抗。","sec":"1. 反局的定义","t":"diff"},{"q":"日主合财，身弱与身旺各喜什么样的财星？","opts":["身弱喜财虚透，身旺喜财旺相","身弱身旺都喜财旺相","身弱身旺都喜财虚透","身弱喜财旺相，身旺喜财虚透"],"ans":0,"exp":"身弱合财，财重则无财，喜财星虚透；身旺合财，喜财旺相，财虚则不主财富（换象除外）。","sec":"五、日主合财的用法","t":"rule"}]},{"n":162,"level":"专题","title":"答疑汇编专题（二）：合冲穿、墓库、禄神与六亲位置","qs":[{"q":"按盲派，原局合制干净，大运又来冲，怎么论？","opts":["冲开合神，反而更吉","合被冲开，象就换成冲的象","合制不喜冲，冲则反局","冲运只是引动，原局不变"],"ans":2,"exp":"原局合制干净时，运来冲不是象变，而是整个局反了。","sec":"一、合与冲的细节","t":"rule"},{"q":"合之后又逢冲，能不能因此换象？","opts":["合在前冲在后，冲胜则换象","合神被冲开后，按冲论象","只要逢冲就换象","冲制不干净，不能换象"],"ans":3,"exp":"冲换象必须冲制干净；又合又冲一定不干净，所以不换。","sec":"一、合与冲的细节","t":"diff"},{"q":"年午、月戌两字相邻，问午入戌墓吗？","opts":["不入墓，午戌论拱","入墓，但要有冲才算","入墓，午火墓在戌","不入墓，按午戌半合火局论"],"ans":0,"exp":"入墓只有寅申巳亥见墓才成立；午戌论拱，不是入墓。","sec":"二、墓库的问题","t":"calc"},{"q":"按盲派，墓库里的东西什么时候才起作用？","opts":["入库即可用，冲反而破坏","逢冲刑开库才有用","库中本气一出就有用","逢合闭库才有用"],"ans":1,"exp":"官财之库不刑不冲没有用，冲刑开库才流动，近冲作功最大。","sec":"二、墓库的问题","t":"rule"},{"q":"子丑合与寅丑暗合，对丑库的处理有何不同？","opts":["两者都闭库，只是闭的五行不同","两者都不闭库，只论五行生克","子丑合闭金库；寅丑暗合不闭库，看谁制谁","子丑合不闭库；寅丑暗合闭土库"],"ans":2,"exp":"子丑合闭金库；寅丑暗合不闭库，只是制的意思，要看各自气势。","sec":"二、墓库的问题","t":"diff"},{"q":"墓库逢冲时，库里的气力量怎么排？","opts":["余气最大，墓气居中，本气最小","三气平分，看月令来定先后","本气最大，余气次之，墓气最小","墓库之气大于余气，本气未必更大"],"ans":3,"exp":"按力量排名，墓库之气＞余气，本气未必大过墓气。","sec":"二、墓库的问题","t":"rule"},{"q":"按盲派，干禄（日禄归时）的时柱只有哪两个？","opts":["丁未时与癸丑时","戊午时与己未时","甲寅时与乙卯时","丙午时与丁巳时"],"ans":0,"exp":"日禄归时中干禄只有丁未时、癸丑时，且成禄格的并不多。","sec":"三、禄、空亡与日禄归时","t":"rule"},{"q":"禄神伏吟（大运又见禄），什么情况不怕？","opts":["禄落在日支，直接帮身","禄为功神且局中是禄的气势","日主身弱，需要帮扶","禄逢三合成局，力量加倍"],"ans":1,"exp":"禄为功神且局中是禄的气势，不怕伏吟；禄无功、遭穿害、单薄无助才凶。","sec":"三、禄、空亡与日禄归时","t":"diff"},{"q":"断禄绊桃花时，禄要落在哪里才算？","opts":["只在月支","四支任何一处","日支或时支","年支或月支"],"ans":2,"exp":"日支、时支是主位，禄才代表日主本人；他支为宾位，不算。","sec":"三、禄、空亡与日禄归时","t":"rule"},{"q":"按盲派，六亲位置怎么找？","opts":["夫妻在日支，子女只在时柱","四亲都只在对应宫位里找","父母在时日，夫妻在年月","父母在年月，夫妻子女可在任何位置"],"ans":3,"exp":"除父母在年月找外，夫妻子女可在局中任何位置。","sec":"四、六亲的位置","t":"rule"},{"q":"看子女时，宫位什么情况才特别要看？","opts":["不生育或克子女时才显示宫位","星位不现时才看宫位","宫位始终比星位重要","只要时支逢冲就看宫位"],"ans":0,"exp":"子女只有不生育或克子女者宫位才显示，其他情况宫位不重要。","sec":"四、六亲的位置","t":"diff"},{"q":"按盲派，财怎样才算大财？","opts":["财透天干即为大财","财与日柱作了功，此财才较大","财多身旺就是大财","见财即为大财"],"ans":1,"exp":"凡财都是钱，只有财与日柱作了功才较大；无功只取旁财，仅够维持生活。","sec":"四、六亲的位置","t":"rule"}]},{"n":163,"level":"专题","title":"命术轶闻断例精讲","qs":[{"q":"盲师一派断命，命局与大运流年各是什么关系？","opts":["命局大运各占一半，同等重要","大运为根本，命局只是底子","先排大运定格局，再看命局喜忌","命局为根本，大运流年只是应期"],"ans":3,"exp":"先从命局象看有无婚姻、发财、做官的信息，再排运流年定应期。","sec":"一、盲师一派的基本路数","t":"rule"},{"q":"八字里没有发财的信息，行财运会怎样？","opts":["未必能富，甚至行财运反而潦倒","行财运小发，破财在后","行财运必定发财","财运多少只看运，原局不论"],"ans":0,"exp":"八字是根本，行运是应期；原局无发财象，行财运也难发。","sec":"一、盲师一派的基本路数","t":"rule"},{"q":"长生十二宫（沐浴、临官、墓、绝、胎等）在盲派里怎么看？","opts":["只用来断寿数，其他不看","是描述事物从始到终的象，不是旺衰","是判断日主旺衰的标准","是判断喜用神的依据"],"ans":1,"exp":"长生十二宫是象，如乙在申为「胎」，应孩子与妻子一块来；不拿来定旺衰。","sec":"一、盲师一派的基本路数","t":"diff"},{"q":"盲师看妻（配偶）的取法，结婚前后有什么区别？","opts":["婚前婚后都只以财星为妻","婚前婚后都只以妻宫为妻","婚前以财为女朋友，婚后以妻宫为妻","婚前以妻宫为妻，婚后以财为妻"],"ans":2,"exp":"结婚前以财为女朋友，结婚后以妻宫（日支）为妻。","sec":"一、盲师一派的基本路数","t":"diff"},{"q":"女命官星在年上与官星在月上，所找对象有何不同？","opts":["官在年上找年纪大的，官在月上找年纪小的","官在年上找近处的，官在月上找远方的","官在年上主早婚，官在月上主晚婚","官在年上找远方的，官在月上找同学同事等近处的"],"ans":3,"exp":"年柱远、月柱近，官的位置定对象远近。","sec":"二、断例一：癸巳 甲寅 甲辰 丁卯（孽情）","t":"diff"},{"q":"女命比劫旺，对象的年龄差一般是什么情况？","opts":["不是找年龄大很多的，就是找年龄小的","一般找比自己大一两岁的","只找比自己小的","多找年龄相当的"],"ans":0,"exp":"比劫旺定年龄差：不大就小，很少相当。","sec":"二、断例一：癸巳 甲寅 甲辰 丁卯（孽情）","t":"rule"},{"q":"女命断婚时，七杀「管到」几岁？此前走财走官的流年可婚动。","opts":["二十四岁","十六岁","十二岁","二十岁"],"ans":1,"exp":"七杀管到十六岁；十六岁流年走财走官就结婚。","sec":"二、断例一：癸巳 甲寅 甲辰 丁卯（孽情）","t":"rule"},{"q":"断子女时，食神与伤官各代表什么？刑克在食神，应什么？","opts":["食神为男、伤官为女；刑克食神克男","食神为女、伤官为男；刑克食神克子","食神为女、伤官为男；刑克食神克女","食神伤官都为女，刑克食神克女"],"ans":2,"exp":"食神为女，伤官为男；寅巳相刑刑在食神，所以克女儿。","sec":"二、断例一：癸巳 甲寅 甲辰 丁卯（孽情）","t":"diff"},{"q":"盲派里「违法星」是哪个字？它与官星相穿主什么？","opts":["辰；与官相穿，意为官司缠身","戌；与官相合，意为官非","丑；与官相穿，意为小人是非","戌；与官相穿，意为违反法律"],"ans":3,"exp":"核心看戌土，戌与官星相穿为违法；劫财伤官穿官是犯罪组合。","sec":"三、断例二：己酉 甲戌 甲申 乙丑（牢狱命定）","t":"rule"},{"q":"女命财官都入库、一直没婚姻，要等什么样的运才能成婚？","opts":["冲开库的运","印星当令的运","比劫帮身的运","财官透干的运"],"ans":0,"exp":"并非没有官财，而是入库不能用；冲开库之运才有婚。","sec":"四、断例三：辛卯 辛丑 丙辰 甲午（老姑娘）","t":"rule"},{"q":"「逢克论凶」速判法，原局克字多少代表什么？大运增加克字呢？","opts":["克字多少不论，只看生字多少","克字越多层次越低；运中增克则增凶","克字越多层次越高；运中增克则增吉","原局克多层次低；运中增克反而减凶"],"ans":1,"exp":"克代表破坏冲击，克字越多越凶；克数大于生数时应凶。","sec":"五、断例四：断“逢克论凶”的简易法","t":"rule"}]}]};
